INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88120, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他对这份报告被满意。", "corrected_sentence": "他对这份报告很满意。", "error_description": "用词错误：“被”表示被动，不能修饰形容词“满意”。程度副词“很”应放在“满意”前，应说“很满意”，不能说“被满意”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '040634d2-eecc-4f2b-ac40-4e35c0af5098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
