INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88139, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "property", "definition": "种种是说很多种，各种各样。", "primary_collocate": null, "pronunciation": "zhǒng zhǒng", "ipa": "tʂʊŋ˨˩˦ tʂʊŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他有种种理由不去开会。", "target_word": "种种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年，我遇到了种种麻烦。", "target_word": "种种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种种迹象表明，今年的冬天会很冷。", "target_word": "种种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为种种原因，会议改到了下个星期。", "target_word": "种种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她向我讲了生活中的种种趣事。", "target_word": "种种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师回答了学生们提出的种种问题。", "target_word": "种种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对我说了种种好处，我还是没买。", "target_word": "种种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种种办法他都试过了，孩子还是不吃饭。", "target_word": "种种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种种压力让他晚上睡不好。", "target_word": "种种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行中的种种经历，他都写进了日记。", "target_word": "种种", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "种种：很多种、各种各样（作定语，修饰原因、困难等名词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e0c221-b8bd-4749-8a15-ebb972445d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88139, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "精美", "is_correct": false, "explanation": "搭配：“精美”形容做工精致的物品，不能修饰“理由”"}, {"text": "种种", "is_correct": true, "explanation": "正确：“种种”表示多种多样，修饰“理由”，句意是有各种各样的理由"}, {"text": "光荣", "is_correct": false, "explanation": "搭配：“光荣”说事情令人自豪，“光荣理由”不通顺"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的身材体积，不能修饰“理由”"}], "explanations": {"精美": "搭配：“精美”形容做工精致的物品，不能修饰“理由”", "种种": "正确：“种种”表示多种多样，修饰“理由”，句意是有各种各样的理由", "光荣": "搭配：“光荣”说事情令人自豪，“光荣理由”不通顺", "高大": "体貌：“高大”形容人或物的身材体积，不能修饰“理由”"}, "sentence_index": 0, "correct_answer": "种种"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间屋子里堆着种种一模一样的书。", "explanation": "语义：误把“种种”当成“某一种”来用。“种种”只表示多种多样，不能修饰完全相同的一批书，这里应说“一批一模一样的书”。"}, {"text": "他每天都重复同一个动作，种种动作让人觉得很无聊。", "explanation": "语义：误把“种种”当成“某一种”来用。“种种”只表示多种多样，不能指同一个动作，这里应说“某种动作”。"}, {"text": "这个计划只有唯一的种种目标。", "explanation": "语义：误把“种种”当成“某一种”来用。“种种”只表示多种多样，不能指一个目标，这里应说“这个计划的目标”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e2401e-2f59-4ebb-9d07-980fe50a58c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88139, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "锋利", "is_correct": false, "explanation": "搭配：“锋利”形容刀刃等，不能修饰“好处”"}, {"text": "寒冷", "is_correct": false, "explanation": "搭配：“寒冷”形容天气，不能修饰“好处”"}, {"text": "坏", "is_correct": false, "explanation": "语义：“坏”与“好处”的褒贬相反，句中说的是对方列出的优点"}, {"text": "种种", "is_correct": true, "explanation": "正确：“种种”表示多种多样，修饰“好处”，句意是说了各种各样的好处"}], "explanations": {"锋利": "搭配：“锋利”形容刀刃等，不能修饰“好处”", "寒冷": "搭配：“寒冷”形容天气，不能修饰“好处”", "坏": "语义：“坏”与“好处”的褒贬相反，句中说的是对方列出的优点", "种种": "正确：“种种”表示多种多样，修饰“好处”，句意是说了各种各样的好处"}, "sentence_index": 6, "correct_answer": "种种"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他只读了一本书，却写了种种读后感。", "explanation": "语义：误把“种种”当成“几”的数量义来用。“种种”强调种类多样，不表示数量少的几个，这里应说“几篇读后感”。"}, {"text": "这两台机器完全相同，但它们有种种区别。", "explanation": "语义：误把“种种”当成“一些、若干”来用。“种种”强调种类繁多，不能指少数几处区别，这里应说“有些区别”。"}, {"text": "这间屋子里只有一把椅子，却摆满了种种椅子。", "explanation": "语义：误把“种种”当成“某一种”来用。“种种”只表示多种多样，只有一把椅子时不能用“种种”，应说“一把椅子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e2401e-2f59-4ebb-9d07-980fe50a58c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88139, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们听到了一种种说法，却不知道哪个是真的。", "corrected_sentence": "我们听到了种种说法，却不知道哪个是真的。", "error_description": "错误：在“种种”前加了“一”，成了“一种种”。“种种”是区别词，前面不能直接加数量词，应说“种种说法”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e2401e-2f59-4ebb-9d07-980fe50a58c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88139, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车站里有很种种人，有的在等车，有的在聊天。", "corrected_sentence": "车站里有种种人，有的在等车，有的在聊天。", "error_description": "错误：在“种种”前加了“很”。“种种”是区别词，不能受程度副词修饰，应直接说“种种人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e2401e-2f59-4ebb-9d07-980fe50a58c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
