INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88152, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用各种材料雕刻或塑造立体形象的艺术，也指这类作品。", "primary_collocate": null, "pronunciation": "diāo sù", "ipa": "tjau̯˥ su˥˩", "syllable_count": 2, "sentences": [{"text": "他从小就喜欢学习雕塑。", "target_word": "雕塑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座雕塑是用青铜做成的。", "target_word": "雕塑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园中间有一座很大的雕塑。", "target_word": "雕塑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雕塑和绘画都是美术课的内容。", "target_word": "雕塑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的雕塑在美术馆展出了。", "target_word": "雕塑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件雕塑表现了一个跑步的人。", "target_word": "雕塑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校门口新放了一座石头雕塑。", "target_word": "雕塑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想报名参加雕塑课。", "target_word": "雕塑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位艺术家擅长雕塑。", "target_word": "雕塑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有很多古代雕塑。", "target_word": "雕塑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "件", "label": "量词"}, {"form": "雕塑家", "label": "复合词"}, {"form": "雕塑作品", "label": "复合词"}], "register": "中性", "sense_fingerprint": "雕刻塑造立体形象的艺术门类及其作品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476bafa-4a1b-4403-b163-44a07b2b0ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88152, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空气", "is_correct": false, "explanation": "语义：「学习」的对象是知识或技能，空气不能被学习，与句中的「从小就喜欢学习」不搭。"}, {"text": "雕塑", "is_correct": true, "explanation": "雕塑是雕刻塑造立体形象的艺术门类，可以作为学习的对象，符合句意。"}, {"text": "车", "is_correct": false, "explanation": "搭配：说「学车」，不说「学习车」，「学习」后不接具体的交通工具。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳是天体，不是人可以学习的内容，与「学习」不搭配。"}], "explanations": {"空气": "语义：「学习」的对象是知识或技能，空气不能被学习，与句中的「从小就喜欢学习」不搭。", "雕塑": "雕塑是雕刻塑造立体形象的艺术门类，可以作为学习的对象，符合句意。", "车": "搭配：说「学车」，不说「学习车」，「学习」后不接具体的交通工具。", "太阳": "语义：太阳是天体，不是人可以学习的内容，与「学习」不搭配。"}, "sentence_index": 0, "correct_answer": "雕塑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天在展厅看到一只雕塑。", "explanation": "这里应该用〈件〉或〈座〉。〈只〉用于动物或成对物品中的一个，不用于雕塑这类艺术作品。"}, {"text": "公园的入口处竖着一条雕塑。", "explanation": "这里应该用〈座〉。〈条〉用于细长的东西，雕塑是立体作品，应该用〈座〉或〈件〉来计量。"}, {"text": "这间屋子里放着一根雕塑。", "explanation": "这里应该用〈件〉。〈根〉用于细长条状的东西，不能用来计量雕塑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b2f6d0-4009-4c46-a64f-4bf1effb2f7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88152, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，不能用石头做成，也不会摆在学校门口。"}, {"text": "西瓜", "is_correct": false, "explanation": "语义：西瓜是水果，不是石头做的东西，与句中的「石头」相矛盾。"}, {"text": "雕塑", "is_correct": true, "explanation": "雕塑是用石头等材料做成的立体艺术作品，「石头雕塑」搭配自然，符合句意。"}, {"text": "棉被", "is_correct": false, "explanation": "语义：棉被是纺织品，与「石头」的材质相矛盾，不能说「石头棉被」。"}], "explanations": {"月亮": "语义：月亮是天体，不能用石头做成，也不会摆在学校门口。", "西瓜": "语义：西瓜是水果，不是石头做的东西，与句中的「石头」相矛盾。", "雕塑": "雕塑是用石头等材料做成的立体艺术作品，「石头雕塑」搭配自然，符合句意。", "棉被": "语义：棉被是纺织品，与「石头」的材质相矛盾，不能说「石头棉被」。"}, "sentence_index": 6, "correct_answer": "雕塑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场雕塑下午两点开始，欢迎大家准时参加。", "explanation": "这里把〈雕塑〉当成了有开始时间的活动。雕塑是艺术门类或作品，不是活动，此处应指〈雕塑展〉。"}, {"text": "这个雕塑唱得很好听。", "explanation": "这里把〈雕塑〉当成了会唱歌的人。雕塑是造型艺术作品，不会唱歌，此处应指〈歌手〉。"}, {"text": "他把雕塑念给了奶奶听。", "explanation": "这里把〈雕塑〉当成了文字。雕塑是立体造型的艺术，不是文章，不能用〈念〉；若要念，应指〈诗〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b2f6d0-4009-4c46-a64f-4bf1effb2f7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88152, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家院子里放着一只雕塑。", "corrected_sentence": "我家院子里放着一座雕塑。", "error_description": "量词错误：“雕塑”应使用量词“座”（或“件”），“只”用于动物或成对物品中的一个，这里用错了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b2f6d0-4009-4c46-a64f-4bf1effb2f7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88152, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "博物馆门口有一座很大雕塑。", "corrected_sentence": "博物馆门口有一座很大的雕塑。", "error_description": "错误：形容词“很大”修饰名词“雕塑”时漏了结构助词“的”，应说“很大的雕塑”。正确：“一座很大的雕塑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b2f6d0-4009-4c46-a64f-4bf1effb2f7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
