INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88161, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "似乎是好像是这样，但是不太确定。", "primary_collocate": null, "pronunciation": "sì hū", "ipa": "sɨ˥˩ xu˥", "syllable_count": 2, "sentences": [{"text": "他似乎不太高兴，一句话也没说。", "target_word": "似乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面似乎下雨了，地上是湿的。", "target_word": "似乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她似乎忘了今天是我的生日。", "target_word": "似乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店似乎没有人，门也关着。", "target_word": "似乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师似乎没听懂我的问题。", "target_word": "似乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我似乎在哪儿见过你。", "target_word": "似乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的病似乎好多了。", "target_word": "似乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋里很安静，似乎没人在家。", "target_word": "似乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子似乎有点怕黑。", "target_word": "似乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事似乎比我想的难。", "target_word": "似乎", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "好像是这样但不太确定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b9c7047-c41d-4dd6-a29e-9eca3dfeee0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88161, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "似乎", "is_correct": true, "explanation": "正确：“似乎”表示根据表象作出的不确定推测，与“一句话也没说”的表现相符。"}, {"text": "非常", "is_correct": false, "explanation": "语义：“非常”表示程度很高，与“不太高兴”的低程度相矛盾。"}, {"text": "特别", "is_correct": false, "explanation": "语义：“特别”强调程度突出，同样与“不太”的低程度相冲突。"}, {"text": "纷纷", "is_correct": false, "explanation": "配价：“纷纷”要求多个主体同时出现，句中主语只有“他”一人。"}], "explanations": {"似乎": "正确：“似乎”表示根据表象作出的不确定推测，与“一句话也没说”的表现相符。", "非常": "语义：“非常”表示程度很高，与“不太高兴”的低程度相矛盾。", "特别": "语义：“特别”强调程度突出，同样与“不太”的低程度相冲突。", "纷纷": "配价：“纷纷”要求多个主体同时出现，句中主语只有“他”一人。"}, "sentence_index": 0, "correct_answer": "似乎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的名字似乎叫李明。", "explanation": "这里应该用〈是〉。“似乎”表示不确定的推测；说话人对自己的名字很确定，应直接说“我的名字是李明”。"}, {"text": "我刚才亲眼看见他进了教室，他似乎进了教室。", "explanation": "这里应该用〈确实〉。“似乎”表示不确定的推测；“亲眼看见”说明事实已经确定，应说“他确实进了教室”。"}, {"text": "我刚才亲手在合同上签了字，它似乎还没有签。", "explanation": "这里应该用〈确实〉。“似乎”表示不确定的推测；“亲手签了字”是说话人确知的事实，不能说“似乎还没有签”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e180dd-508b-4434-8fa4-cf412f9f8831') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88161, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "似乎", "is_correct": true, "explanation": "正确：“似乎”表示推测，与“病好多了”的判断相符。"}, {"text": "必须", "is_correct": false, "explanation": "语义：“必须”表示必要或义务，不能用来描述病情的好转。"}, {"text": "有点", "is_correct": false, "explanation": "语义：“有点”表示程度不高，与“好多了”的大幅改善相矛盾。"}, {"text": "连忙", "is_correct": false, "explanation": "搭配：“连忙”修饰动作，不修饰“病好多了”这样的状态。"}], "explanations": {"似乎": "正确：“似乎”表示推测，与“病好多了”的判断相符。", "必须": "语义：“必须”表示必要或义务，不能用来描述病情的好转。", "有点": "语义：“有点”表示程度不高，与“好多了”的大幅改善相矛盾。", "连忙": "搭配：“连忙”修饰动作，不修饰“病好多了”这样的状态。"}, "sentence_index": 6, "correct_answer": "似乎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我似乎能保证明天准时到。", "explanation": "这里应该用〈一定〉。“似乎”表示不确定的推测，与肯定的承诺“保证”相矛盾。"}, {"text": "我在北京出生，似乎是北京人。", "explanation": "这里应该用〈当然〉。“似乎”表示不确定的推测；“在北京出生”已经确定了身份，应说“当然是北京人”。"}, {"text": "麻烦你似乎把窗户关上。", "explanation": "这里应该用〈请〉。请求需要明确表达，“似乎”会使请求变得含糊，应说“请你把窗户关上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e180dd-508b-4434-8fa4-cf412f9f8831') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88161, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈似乎的有点累，早早就睡了。", "corrected_sentence": "妈妈似乎有点累，早早就睡了。", "error_description": "多写“的”。“似乎”是副词，后面不能加“的”，应写作“妈妈似乎有点累”；“似乎的”后接“有点”，句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e180dd-508b-4434-8fa4-cf412f9f8831') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88161, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他最近似乎地很忙，常常加班。", "corrected_sentence": "他最近似乎很忙，常常加班。", "error_description": "“地”用错。“似乎”是副词，后面不能加“地”，应写作“似乎很忙”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e180dd-508b-4434-8fa4-cf412f9f8831') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
