INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88163, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "草是绿色的小植物，长在地上，很软很矮。", "primary_collocate": null, "pronunciation": "cǎo", "ipa": "tsʰau̯˨˩˦", "syllable_count": 1, "sentences": [{"text": "院子里的草绿了。", "target_word": "草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "羊在山坡上吃草。", "target_word": "草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗躺在草上睡着了。", "target_word": "草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天来了，草长得很快。", "target_word": "草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要踩草。", "target_word": "草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸每个星期都给院子里的草浇水。", "target_word": "草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边的草又软又绿。", "target_word": "草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后，草上有很多小水珠。", "target_word": "草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶牛喜欢吃新鲜的草。", "target_word": "草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风一吹，草轻轻地动了起来。", "target_word": "草", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一片草", "label": "量词"}, {"form": "一棵草", "label": "量词"}, {"form": "草地", "label": "复合"}, {"form": "小草", "label": "复合"}], "register": "中性", "sense_fingerprint": "草：地上长的绿色、柔软、矮小的植物（日常所见的草）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e0c221-b8bd-4749-8a15-ebb972445d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88163, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "草", "is_correct": true, "explanation": "正确答案：草，指地上长的绿色、柔软的小植物。"}, {"text": "早", "is_correct": false, "explanation": "zǎo（第三声）与 cǎo 的声母不同（z 与 c），意思是早上。"}, {"text": "炒", "is_correct": false, "explanation": "chǎo 与 cǎo 的声母不同（ch 与 c），意思是翻炒。"}, {"text": "找", "is_correct": false, "explanation": "zhǎo 与 cǎo 的声母不同（zh 与 c），意思是寻找。"}, {"text": "扫", "is_correct": false, "explanation": "sǎo 与 cǎo 的声母不同（s 与 c），意思是打扫。"}], "explanations": {"草": "正确答案：草，指地上长的绿色、柔软的小植物。", "早": "zǎo（第三声）与 cǎo 的声母不同（z 与 c），意思是早上。", "炒": "chǎo 与 cǎo 的声母不同（ch 与 c），意思是翻炒。", "找": "zhǎo 与 cǎo 的声母不同（zh 与 c），意思是寻找。", "扫": "sǎo 与 cǎo 的声母不同（s 与 c），意思是打扫。"}, "sentence_index": null, "correct_answer": "草"}, "level_3": {"options": [{"text": "草", "is_correct": true, "explanation": "正确：草生长在院子里，变绿符合语境。"}, {"text": "雪", "is_correct": false, "explanation": "语义：雪是白色的，不会变成绿色。"}, {"text": "狗", "is_correct": false, "explanation": "语义：狗是动物，不会变成绿色。"}, {"text": "手", "is_correct": false, "explanation": "搭配：“绿了”通常说植物或叶子变色，不说人的手。"}], "explanations": {"草": "正确：草生长在院子里，变绿符合语境。", "雪": "语义：雪是白色的，不会变成绿色。", "狗": "语义：狗是动物，不会变成绿色。", "手": "搭配：“绿了”通常说植物或叶子变色，不说人的手。"}, "sentence_index": 0, "correct_answer": "草"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在山坡上看到了一只草。", "explanation": "这里应该用〈片〉。“只”用于动物，草成片生长时要用“片”。"}, {"text": "山坡上有一座草。", "explanation": "这里应该用〈片〉。“座”用于山、房屋等大型物体，不用于草。"}, {"text": "我在窗台上放了一辆草。", "explanation": "这里应该用〈把〉。“辆”用于车辆，草成束时要用“把”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e2401e-2f59-4ebb-9d07-980fe50a58c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88163, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "草", "is_correct": true, "explanation": "正确答案：草，指地上长的绿色、柔软的小植物。"}, {"text": "好", "is_correct": false, "explanation": "hǎo（第三声）与 cǎo 的声母不同（h 与 c），意思是好的。"}, {"text": "老", "is_correct": false, "explanation": "lǎo 与 cǎo 的声母不同（l 与 c），意思是年纪大的。"}, {"text": "考", "is_correct": false, "explanation": "kǎo 与 cǎo 的声母不同（k 与 c），意思是考试。"}, {"text": "彩", "is_correct": false, "explanation": "cǎi 与 cǎo 的韵母不同（ai 与 ao），意思是彩色。"}, {"text": "少", "is_correct": false, "explanation": "shǎo 与 cǎo 的声母不同（sh 与 c），意思是数量不多。"}], "explanations": {"草": "正确答案：草，指地上长的绿色、柔软的小植物。", "好": "hǎo（第三声）与 cǎo 的声母不同（h 与 c），意思是好的。", "老": "lǎo 与 cǎo 的声母不同（l 与 c），意思是年纪大的。", "考": "kǎo 与 cǎo 的声母不同（k 与 c），意思是考试。", "彩": "cǎi 与 cǎo 的韵母不同（ai 与 ao），意思是彩色。", "少": "shǎo 与 cǎo 的声母不同（sh 与 c），意思是数量不多。"}, "sentence_index": null, "correct_answer": "草"}, "level_3": {"options": [{"text": "草", "is_correct": true, "explanation": "正确：草柔软、发绿，符合河边的描写。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是硬的，不会软。"}, {"text": "冰", "is_correct": false, "explanation": "语义：冰是冷而硬的，不能说又软又绿。"}, {"text": "脸", "is_correct": false, "explanation": "体貌：描写人的脸不说“又软又绿”，这样形容不成立。"}], "explanations": {"草": "正确：草柔软、发绿，符合河边的描写。", "石头": "语义：石头是硬的，不会软。", "冰": "语义：冰是冷而硬的，不能说又软又绿。", "脸": "体貌：描写人的脸不说“又软又绿”，这样形容不成立。"}, "sentence_index": 6, "correct_answer": "草"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶把草切碎，放进锅里炒着吃。", "explanation": "这里应该用〈菜〉。草一般不是用来炒着吃的食物，做菜要说〈菜〉。"}, {"text": "院子角落里放着一张草。", "explanation": "这里应该用〈丛〉。“张”用于纸、桌子等平面的东西，草应说“一丛草”。"}, {"text": "墙边立着一头草。", "explanation": "这里应该用〈丛〉。“头”用于牲畜，草不用“头”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e2401e-2f59-4ebb-9d07-980fe50a58c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88163, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山坡上有一只草。", "corrected_sentence": "山坡上有一片草。", "error_description": "错误在量词：成片生长的草应用量词“片”，“只”用于动物，不能用于草。正确说法是“一片草”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e2401e-2f59-4ebb-9d07-980fe50a58c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88163, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "河边又软又绿草，很好看。", "corrected_sentence": "河边又软又绿的草，很好看。", "error_description": "错误在定语：“又软又绿”修饰名词“草”时要加“的”，应说“又软又绿的草”，不能说“又软又绿草”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e2401e-2f59-4ebb-9d07-980fe50a58c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
