INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88164, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "茎干柔软、较矮小的植物的统称。", "primary_collocate": null, "pronunciation": "cǎo", "ipa": "tsʰau̯˨˩˦", "syllable_count": 1, "sentences": [{"text": "这种草可以做药。", "target_word": "草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上有各种各样的草和花。", "target_word": "草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草和树不一样，草比较矮。", "target_word": "草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在花园里种了几种草。", "target_word": "草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种草冬天也不会死。", "target_word": "草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们看了几种草的图片。", "target_word": "草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠里很少有草。", "target_word": "草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片土地太干了，连草都不长。", "target_word": "草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶说这种草泡水喝对身体好。", "target_word": "草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把草的叶子放在书里做书签。", "target_word": "草", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种草", "label": "量词"}, {"form": "一棵草", "label": "量词"}, {"form": "草原", "label": "复合"}, {"form": "草药", "label": "复合"}], "register": "中性", "sense_fingerprint": "草：茎干柔软、较矮小的植物的统称（与树相对的一类植物）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e0c221-b8bd-4749-8a15-ebb972445d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88164, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "草", "is_correct": true, "explanation": "正确答案：草，指茎干柔软、较矮小的植物。"}, {"text": "跑", "is_correct": false, "explanation": "pǎo 与 cǎo 的声母不同（p 与 c），意思是奔跑。"}, {"text": "保", "is_correct": false, "explanation": "bǎo 与 cǎo 的声母不同（b 与 c），意思是保护。"}, {"text": "脑", "is_correct": false, "explanation": "nǎo 与 cǎo 的声母不同（n 与 c），意思是大脑。"}, {"text": "搞", "is_correct": false, "explanation": "gǎo 与 cǎo 的声母不同（g 与 c），意思是做、搞。"}, {"text": "操", "is_correct": false, "explanation": "cāo（第一声）与 cǎo 的声调不同，意思是操作。"}], "explanations": {"草": "正确答案：草，指茎干柔软、较矮小的植物。", "跑": "pǎo 与 cǎo 的声母不同（p 与 c），意思是奔跑。", "保": "bǎo 与 cǎo 的声母不同（b 与 c），意思是保护。", "脑": "nǎo 与 cǎo 的声母不同（n 与 c），意思是大脑。", "搞": "gǎo 与 cǎo 的声母不同（g 与 c），意思是做、搞。", "操": "cāo（第一声）与 cǎo 的声调不同，意思是操作。"}, "sentence_index": null, "correct_answer": "草"}, "level_3": {"options": [{"text": "草", "is_correct": true, "explanation": "正确：这种草可以入药，符合语境。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是机器，不能做药。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃是矿物制品，不能做药。"}, {"text": "衣服", "is_correct": false, "explanation": "搭配：“做药”通常说草药、药材，不搭配“衣服”。"}], "explanations": {"草": "正确：这种草可以入药，符合语境。", "电脑": "语义：电脑是机器，不能做药。", "玻璃": "语义：玻璃是矿物制品，不能做药。", "衣服": "搭配：“做药”通常说草药、药材，不搭配“衣服”。"}, "sentence_index": 0, "correct_answer": "草"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在花园里种了几只草。", "explanation": "这里应该用〈种〉。“只”用于动物，说草的种类要用“种”。"}, {"text": "他在花园里种了几座草。", "explanation": "这里应该用〈种〉。“座”用于山、房屋等，不用于草的种类。"}, {"text": "他在花园里种了几首草。", "explanation": "这里应该用〈种〉。“首”用于诗歌、歌曲，不用于草的种类。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e2401e-2f59-4ebb-9d07-980fe50a58c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88164, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "草", "is_correct": true, "explanation": "正确答案：草，指茎干柔软、较矮小的植物。"}, {"text": "讨", "is_correct": false, "explanation": "tǎo 与 cǎo 的声母不同（t 与 c），意思是讨论。"}, {"text": "倒", "is_correct": false, "explanation": "dǎo 与 cǎo 的声母不同（d 与 c），意思是倒下。"}, {"text": "惨", "is_correct": false, "explanation": "cǎn 与 cǎo 的韵母不同（an 与 ao），意思是悲惨。"}, {"text": "糙", "is_correct": false, "explanation": "cāo（第一声）与 cǎo 的声调不同，意思是粗糙。"}], "explanations": {"草": "正确答案：草，指茎干柔软、较矮小的植物。", "讨": "tǎo 与 cǎo 的声母不同（t 与 c），意思是讨论。", "倒": "dǎo 与 cǎo 的声母不同（d 与 c），意思是倒下。", "惨": "cǎn 与 cǎo 的韵母不同（an 与 ao），意思是悲惨。", "糙": "cāo（第一声）与 cǎo 的声调不同，意思是粗糙。"}, "sentence_index": null, "correct_answer": "草"}, "level_3": {"options": [{"text": "草", "is_correct": true, "explanation": "正确：沙漠里少有草，符合语境。"}, {"text": "空气", "is_correct": false, "explanation": "语义：沙漠里一直有空气，不能说“很少有空气”。"}, {"text": "大海", "is_correct": false, "explanation": "语义：沙漠中没有大海，说“很少有大海”与语境矛盾。"}, {"text": "脚", "is_correct": false, "explanation": "搭配：“很少有”不用于人的身体部位，不说“很少有脚”。"}], "explanations": {"草": "正确：沙漠里少有草，符合语境。", "空气": "语义：沙漠里一直有空气，不能说“很少有空气”。", "大海": "语义：沙漠中没有大海，说“很少有大海”与语境矛盾。", "脚": "搭配：“很少有”不用于人的身体部位，不说“很少有脚”。"}, "sentence_index": 6, "correct_answer": "草"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈炒了一盘草，我们都吃得很香。", "explanation": "这里应该用〈菜〉。草不是人吃的食物，炒着吃的要说〈菜〉。"}, {"text": "这些草很硬，可以拿来做桌子。", "explanation": "这里应该用〈木〉。草茎柔软，“很硬”和“做桌子”要用〈木〉，草不能这样用。"}, {"text": "孩子们在操场上吃草，笑得很开心。", "explanation": "这里应该用〈饭〉。“吃草”只用于牲畜，人吃东西要说“吃饭”，草不是人吃的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e2401e-2f59-4ebb-9d07-980fe50a58c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88164, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只草茎很软，可以编篮子。", "corrected_sentence": "这种草茎很软，可以编篮子。", "error_description": "错误在量词：说草的种类要用“种”，“只”用于动物，不能用于草。正确说法是“这种草”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e2401e-2f59-4ebb-9d07-980fe50a58c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88164, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "沙漠边缘偶尔能看到一些草们。", "corrected_sentence": "沙漠边缘偶尔能看到一些草。", "error_description": "错误在名词后缀：“们”只用于指人的名词，草不能加“们”。应说“一些草”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e2401e-2f59-4ebb-9d07-980fe50a58c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88169, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "桌子", "is_correct": false, "explanation": "“桌子”是名词，与“来日”没有反义关系。"}, {"text": "河流", "is_correct": false, "explanation": "“河流”是名词，与“来日”的任何义项都没有反义关系。"}, {"text": "石头", "is_correct": false, "explanation": "“石头”是名词，与“来日”没有反义关系。"}, {"text": "往日", "is_correct": true, "explanation": "“往日”指过去的日子，与“来日”指将来的日子正好相反。"}], "correct_answer": "往日", "explanations": {"桌子": "“桌子”是名词，与“来日”没有反义关系。", "河流": "“河流”是名词，与“来日”的任何义项都没有反义关系。", "石头": "“石头”是名词，与“来日”没有反义关系。", "往日": "“往日”指过去的日子，与“来日”指将来的日子正好相反。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e180dd-508b-4434-8fa4-cf412f9f8831') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88169, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "书包", "is_correct": false, "explanation": "“书包”是名词，与“来日”没有反义关系。"}, {"text": "海洋", "is_correct": false, "explanation": "“海洋”是名词，与“来日”的任何义项都没有反义关系。"}, {"text": "窗户", "is_correct": false, "explanation": "“窗户”是名词，与“来日”没有反义关系。"}, {"text": "往日", "is_correct": true, "explanation": "“往日”指过去的日子，与“来日”指将来的日子正好相反。"}], "correct_answer": "往日", "explanations": {"书包": "“书包”是名词，与“来日”没有反义关系。", "海洋": "“海洋”是名词，与“来日”的任何义项都没有反义关系。", "窗户": "“窗户”是名词，与“来日”没有反义关系。", "往日": "“往日”指过去的日子，与“来日”指将来的日子正好相反。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e180dd-508b-4434-8fa4-cf412f9f8831') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88169, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "来日是还没有到的日子。", "primary_collocate": null, "pronunciation": "lái rì", "ipa": "lai̯˧˥ ʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "今天先说到这里，来日我们再聊。", "target_word": "来日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说来日一定会报答你的帮助。", "target_word": "来日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在多努力，来日才会过得好。", "target_word": "来日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来日的事谁也不知道，别想太多。", "target_word": "来日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次没成功，来日还有机会。", "target_word": "来日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老朋友告别时说：“来日再见！”", "target_word": "来日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们约好来日一起去海边玩。", "target_word": "来日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他心里想着来日要开一家小店。", "target_word": "来日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在存点钱，是为了来日用。", "target_word": "来日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别怕失败，来日的路还很长。", "target_word": "来日", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "来日方长", "label": "成语"}], "register": "书面", "sense_fingerprint": "还没有到的日子，指将来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b9c7047-c41d-4dd6-a29e-9eca3dfeee0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88169, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "昨天", "is_correct": false, "explanation": "语义：“昨天”指已经过去的日子，与“我们再聊”所指的将来相冲突。"}, {"text": "当初", "is_correct": false, "explanation": "语义：“当初”指过去的时候，不能用来表示以后再聊。"}, {"text": "来日", "is_correct": true, "explanation": "“来日”指还没到的日子，与“再聊”的将来语境相符。"}, {"text": "河边", "is_correct": false, "explanation": "搭配：“河边”是地点，不能充当“再聊”的时间状语。"}], "explanations": {"昨天": "语义：“昨天”指已经过去的日子，与“我们再聊”所指的将来相冲突。", "当初": "语义：“当初”指过去的时候，不能用来表示以后再聊。", "来日": "“来日”指还没到的日子，与“再聊”的将来语境相符。", "河边": "搭配：“河边”是地点，不能充当“再聊”的时间状语。"}, "sentence_index": 0, "correct_answer": "来日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老人喜欢回忆来日的童年。", "explanation": "这里应该用“往昔”。“来日”指还没到的时间，不能用于回忆已经过去的童年。"}, {"text": "这件事来日已经解决了。", "explanation": "这里不用“来日”。“来日”指还没到的日子，不能用于已经完成的事情。"}, {"text": "我们住在来日附近。", "explanation": "这里不用“来日”。“来日”是时间词，不能表示地点，应换成“城市”这类地点名词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e180dd-508b-4434-8fa4-cf412f9f8831') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88169, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上个月", "is_correct": false, "explanation": "语义：“上个月”指已经过去的时间，与约定的将来相冲突。"}, {"text": "公园", "is_correct": false, "explanation": "搭配：“公园”是地点，不能作时间状语，与“约好……一起去海边玩”不搭配。"}, {"text": "来日", "is_correct": true, "explanation": "“来日”指还没到的日子，与“约好”之后的将来安排相符。"}, {"text": "去年", "is_correct": false, "explanation": "语义：“去年”指过去的一年，与约好之后的行动冲突。"}], "explanations": {"上个月": "语义：“上个月”指已经过去的时间，与约定的将来相冲突。", "公园": "搭配：“公园”是地点，不能作时间状语，与“约好……一起去海边玩”不搭配。", "来日": "“来日”指还没到的日子，与“约好”之后的将来安排相符。", "去年": "语义：“去年”指过去的一年，与约好之后的行动冲突。"}, "sentence_index": 6, "correct_answer": "来日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一个来日。", "explanation": "这里不用“来日”。“来日”指还没到的时间，是抽象的时段，不是可以买的东西。"}, {"text": "妈妈的来日很温柔。", "explanation": "这里不用“来日”。“来日”指还没到的时间，不能用来形容人的性格。"}, {"text": "他把来日放进了书包。", "explanation": "这里不用“来日”。“来日”是时间，不是具体的物品，不能用“把……放进”处置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e180dd-508b-4434-8fa4-cf412f9f8831') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88169, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "来日了我们一起出发。", "corrected_sentence": "来日我们一起出发。", "error_description": "“来日”指将来，其后不能加“了”。“来日了我们一起出发”错误，应为“来日我们一起出发”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e180dd-508b-4434-8fa4-cf412f9f8831') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88169, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很来日我们再一起看海。", "corrected_sentence": "来日我们再一起看海。", "error_description": "“来日”是时间名词，前面不能加副词“很”修饰。“很来日我们再一起看海”错误，应去掉“很”，为“来日我们再一起看海”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e180dd-508b-4434-8fa4-cf412f9f8831') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88170, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "窗帘", "is_correct": false, "explanation": "“窗帘”是名词，与“来日”没有反义关系。"}, {"text": "池塘", "is_correct": false, "explanation": "“池塘”是名词，与“来日”的任何义项都没有反义关系。"}, {"text": "铅笔", "is_correct": false, "explanation": "“铅笔”是名词，与“来日”没有反义关系。"}, {"text": "往日", "is_correct": true, "explanation": "“往日”指过去的日子，与“来日”指将来的日子正好相反。"}], "correct_answer": "往日", "explanations": {"窗帘": "“窗帘”是名词，与“来日”没有反义关系。", "池塘": "“池塘”是名词，与“来日”的任何义项都没有反义关系。", "铅笔": "“铅笔”是名词，与“来日”没有反义关系。", "往日": "“往日”指过去的日子，与“来日”指将来的日子正好相反。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e180dd-508b-4434-8fa4-cf412f9f8831') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88170, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "杯子", "is_correct": false, "explanation": "“杯子”是名词，与“来日”没有反义关系。"}, {"text": "山峰", "is_correct": false, "explanation": "“山峰”是名词，与“来日”的任何义项都没有反义关系。"}, {"text": "雨伞", "is_correct": false, "explanation": "“雨伞”是名词，与“来日”没有反义关系。"}, {"text": "往日", "is_correct": true, "explanation": "“往日”指过去的日子，与“来日”指将来的日子正好相反。"}], "correct_answer": "往日", "explanations": {"杯子": "“杯子”是名词，与“来日”没有反义关系。", "山峰": "“山峰”是名词，与“来日”的任何义项都没有反义关系。", "雨伞": "“雨伞”是名词，与“来日”没有反义关系。", "往日": "“往日”指过去的日子，与“来日”指将来的日子正好相反。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e180dd-508b-4434-8fa4-cf412f9f8831') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88170, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "将来的日子；也指第二天。", "primary_collocate": null, "pronunciation": "lái rì", "ipa": "lai̯˧˥ ʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "天色已晚，来日再谈这件事吧。", "target_word": "来日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天太累了，来日再去看你。", "target_word": "来日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他答应来日把书还给我。", "target_word": "来日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来日的天气会比今天更好。", "target_word": "来日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不知道来日会发生什么。", "target_word": "来日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她希望来日能当一名医生。", "target_word": "来日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的工作做完了，来日继续。", "target_word": "来日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你放心，来日我一定来帮你。", "target_word": "来日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来日的计划，我们明天再讨论。", "target_word": "来日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天努力，只为来日过上好日子。", "target_word": "来日", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "来日方长", "label": "成语"}], "register": "书面", "sense_fingerprint": "将来的日子，也指第二天", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b9c7047-c41d-4dd6-a29e-9eca3dfeee0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88170, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上周", "is_correct": false, "explanation": "语义：“上周”指已经过去的一周，与“再谈”的将来不符。"}, {"text": "桌上", "is_correct": false, "explanation": "搭配：“桌上”是地点，不能作时间状语。"}, {"text": "来日", "is_correct": true, "explanation": "“来日”指将来，与“再谈这件事”的后续安排相符。"}, {"text": "昨夜", "is_correct": false, "explanation": "语义：“昨夜”指已经过去的夜晚，与“再谈”冲突。"}], "explanations": {"上周": "语义：“上周”指已经过去的一周，与“再谈”的将来不符。", "桌上": "搭配：“桌上”是地点，不能作时间状语。", "来日": "“来日”指将来，与“再谈这件事”的后续安排相符。", "昨夜": "语义：“昨夜”指已经过去的夜晚，与“再谈”冲突。"}, "sentence_index": 0, "correct_answer": "来日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天就来日出发了。", "explanation": "这里不用“来日”。“来日”指将来或第二天，与“昨天就……了”的已完成语境相冲突。"}, {"text": "书本放在来日上了。", "explanation": "这里不用“来日”。“来日”是时间词，不能表示放置东西的地点或平面。"}, {"text": "这位老师的来日很严肃。", "explanation": "这里不用“来日”。“来日”不能用来形容人的性格，描述人应该用别的词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e180dd-508b-4434-8fa4-cf412f9f8831') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88170, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "书桌", "is_correct": false, "explanation": "搭配：“书桌”是地点，不能作时间状语，与“继续”的时间安排不搭配。"}, {"text": "昨晚", "is_correct": false, "explanation": "语义：“昨晚”指已经过去的夜晚，与“继续”的后续安排冲突。"}, {"text": "来日", "is_correct": true, "explanation": "“来日”指将来，与“做完了……继续”的后续安排相符。"}, {"text": "当年", "is_correct": false, "explanation": "语义：“当年”指过去的某一年，与“继续”的后续安排冲突。"}], "explanations": {"书桌": "搭配：“书桌”是地点，不能作时间状语，与“继续”的时间安排不搭配。", "昨晚": "语义：“昨晚”指已经过去的夜晚，与“继续”的后续安排冲突。", "来日": "“来日”指将来，与“做完了……继续”的后续安排相符。", "当年": "语义：“当年”指过去的某一年，与“继续”的后续安排冲突。"}, "sentence_index": 6, "correct_answer": "来日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "书架上摆着一个来日。", "explanation": "这里不用“来日”。“来日”指还没到的时间，是抽象的时段，不是可以摆放的具体物品。"}, {"text": "他去年来日就已经结婚了。", "explanation": "这里不用“来日”。“来日”指还没到的日子，不能用于已经发生的过去事件。"}, {"text": "他把来日送给了朋友。", "explanation": "这里不用“来日”。“来日”是时间，不是可以赠送的物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e180dd-508b-4434-8fa4-cf412f9f8831') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88170, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "来日过我们会再见面。", "corrected_sentence": "来日我们会再见面。", "error_description": "“过”表示已经发生，不能加在表示将来的“来日”后。“来日过我们会再见面”错误，应去掉“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e180dd-508b-4434-8fa4-cf412f9f8831') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
