INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88178, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "哥哥和弟弟的合称；也泛指有亲缘关系的男子。", "primary_collocate": null, "pronunciation": "xiōng dì", "ipa": "ɕjʊŋ˥ ti˥˩", "syllable_count": 2, "sentences": [{"text": "他们兄弟几个都在外地工作。", "target_word": "兄弟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兄弟们都来参加他的婚礼。", "target_word": "兄弟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷有五个兄弟。", "target_word": "兄弟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年时，兄弟们都回老家。", "target_word": "兄弟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和叔叔家的兄弟关系很好。", "target_word": "兄弟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家兄弟几个都很高。", "target_word": "兄弟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父亲和他的兄弟一起做生意。", "target_word": "兄弟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兄弟们坐在一起聊天。", "target_word": "兄弟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有几个兄弟？", "target_word": "兄弟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的兄弟们都住在农村。", "target_word": "兄弟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "名词；哥哥弟弟的合称；泛指有亲缘关系的男子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e5d9128-ce98-4150-aea3-14a63da0a28d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88178, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "兄弟", "is_correct": true, "explanation": "兄弟：指哥哥和弟弟，此处是“他们”的几个兄弟。"}, {"text": "夫妻", "is_correct": false, "explanation": "语义：“夫妻”只指两人，不能与“几个”这样的不定数量搭配。"}, {"text": "同桌", "is_correct": false, "explanation": "搭配：“同桌”是两人同坐一桌的关系，不能说“他们同桌几个”。"}, {"text": "双胞胎", "is_correct": false, "explanation": "语义：“双胞胎”只指两个人，与“几个”表示的多数概念矛盾。"}], "explanations": {"兄弟": "兄弟：指哥哥和弟弟，此处是“他们”的几个兄弟。", "夫妻": "语义：“夫妻”只指两人，不能与“几个”这样的不定数量搭配。", "同桌": "搭配：“同桌”是两人同坐一桌的关系，不能说“他们同桌几个”。", "双胞胎": "语义：“双胞胎”只指两个人，与“几个”表示的多数概念矛盾。"}, "sentence_index": 0, "correct_answer": "兄弟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她俩是亲兄弟，从小一起长大。", "explanation": "这里应该用〈亲姐妹〉。兄弟只指男性，“她俩”是女性，不能用兄弟。"}, {"text": "她和丈夫是兄弟。", "explanation": "这里应该用〈夫妻〉。兄弟指男性亲属，“她”是女性，“丈夫”与她是夫妻关系，不能说兄弟。"}, {"text": "我和爷爷是兄弟。", "explanation": "这里应该用〈祖孙〉。兄弟指同辈的男性亲属，“我”与“爷爷”是祖孙，辈分不同，不能称兄弟。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed880c2a-f0c2-4fac-8d1e-932e3919a069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88178, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "兄弟", "is_correct": true, "explanation": "兄弟：指他的哥哥、弟弟等男性亲属，此处是“他”的兄弟，与父亲一起做生意。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：“婴儿”不会做生意，与“一起做生意”的语义相矛盾。"}, {"text": "宠物", "is_correct": false, "explanation": "配价：“做生意”的参与者须是能行动的人，“宠物”不能充当这一角色。"}, {"text": "植物", "is_correct": false, "explanation": "搭配：“植物”不能与“他的”构成可以一起做生意的人物关系，不能说“父亲和他的植物一起做生意”。"}], "explanations": {"兄弟": "兄弟：指他的哥哥、弟弟等男性亲属，此处是“他”的兄弟，与父亲一起做生意。", "婴儿": "语义：“婴儿”不会做生意，与“一起做生意”的语义相矛盾。", "宠物": "配价：“做生意”的参与者须是能行动的人，“宠物”不能充当这一角色。", "植物": "搭配：“植物”不能与“他的”构成可以一起做生意的人物关系，不能说“父亲和他的植物一起做生意”。"}, "sentence_index": 6, "correct_answer": "兄弟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她和哥哥是亲兄弟，从小很亲近。", "explanation": "这里应该用〈亲兄妹〉。兄弟只指男性，“她”是女性，应说“她和哥哥是亲兄妹”。"}, {"text": "他和孙子是兄弟。", "explanation": "这里应该用〈祖孙〉。兄弟指同辈的男性亲属，“孙子”比“他”低两辈，不能称兄弟。"}, {"text": "我和侄子是兄弟。", "explanation": "这里应该用〈叔侄〉。兄弟指同辈的男性亲属，“侄子”比“我”低一辈，应说叔侄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed880c2a-f0c2-4fac-8d1e-932e3919a069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88178, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家兄弟几只都很能干。", "corrected_sentence": "我家兄弟几个都很能干。", "error_description": "错误：计量“几只”用于动物，指人应用“几个”。“几只兄弟”不通，应为“几个兄弟”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed880c2a-f0c2-4fac-8d1e-932e3919a069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88178, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的兄弟三人们都住在农村。", "corrected_sentence": "我的兄弟三人都住在农村。", "error_description": "错误：“三人”后又加了“们”。“人们”与数词不能同用，应为“我的兄弟三人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed880c2a-f0c2-4fac-8d1e-932e3919a069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
