INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88180, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "速度很高的。", "primary_collocate": null, "pronunciation": "gāo sù", "ipa": "kaʊ˥ su˥˩", "syllable_count": 2, "sentences": [{"text": "这台机器需要高速的电机。", "target_word": "高速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种跑车是高速的，一般人不敢开。", "target_word": "高速", "complexity_tier": "T3", "furigana": "zhè zhǒng pǎo chē shì gāo sù de, yì bān rén bù gǎn kāi.", "sentence_source": "generated"}, {"text": "高速的列车一眨眼就过去了。", "target_word": "高速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在高速的运转下，机器很快就热了。", "target_word": "高速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高速的生活让他觉得很累。", "target_word": "高速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们很喜欢这种高速的网络。", "target_word": "高速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高速的水流把小船冲走了。", "target_word": "高速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高速的电梯让他耳朵很不舒服。", "target_word": "高速", "complexity_tier": "T3", "furigana": "gāo sù de diàn tī ràng tā ěr duo hěn bù shū fu.", "sentence_source": "generated"}, {"text": "医生说高速的撞击很危险。", "target_word": "高速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的风很大，是高速的气流。", "target_word": "高速", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高速公路", "label": "复合"}], "register": "中性", "sense_fingerprint": "速度很高的，作定语修饰名词或作宾语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d3828f-e88f-4827-ada6-b99a5aa80d30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
