INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88180, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "高速", "is_correct": true, "explanation": "正确。高速：速度很高的。"}, {"text": "告诉", "is_correct": false, "explanation": "gào（第四声）与 gāo（第一声）声调不同，意思是把事情讲给别人知道。"}, {"text": "高处", "is_correct": false, "explanation": "chù（第四声）与 sù 声母不同，意思是较高的地方。"}, {"text": "高数", "is_correct": false, "explanation": "shù（第四声）与 sù 声母不同，意思是高等数学，是口语说法。"}], "explanations": {"高速": "正确。高速：速度很高的。", "告诉": "gào（第四声）与 gāo（第一声）声调不同，意思是把事情讲给别人知道。", "高处": "chù（第四声）与 sù 声母不同，意思是较高的地方。", "高数": "shù（第四声）与 sù 声母不同，意思是高等数学，是口语说法。"}, "sentence_index": null, "correct_answer": "高速"}, "level_3": {"options": [{"text": "高速", "is_correct": true, "explanation": "正确。“高速的水流”指速度很高的水流，符合语境。"}, {"text": "困倦", "is_correct": false, "explanation": "语义：“困倦”形容人的状态，不能修饰水流。"}, {"text": "瘦小", "is_correct": false, "explanation": "体貌：“瘦小”描述体形，不能修饰水流。"}, {"text": "懒惰", "is_correct": false, "explanation": "语义：“懒惰”形容人的品性，不能修饰水流。"}], "explanations": {"高速": "正确。“高速的水流”指速度很高的水流，符合语境。", "困倦": "语义：“困倦”形容人的状态，不能修饰水流。", "瘦小": "体貌：“瘦小”描述体形，不能修饰水流。", "懒惰": "语义：“懒惰”形容人的品性，不能修饰水流。"}, "sentence_index": 6, "correct_answer": "高速"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗汤很高速，喝的时候要小心。", "explanation": "这里应该用〈烫〉。“高速”指速度，不用来说汤的冷热。"}, {"text": "他的力气是高速的。", "explanation": "这里应该用〈大〉。“高速”指速度，不用来说力气的大小。"}, {"text": "这种茶的味道很高速。", "explanation": "这里应该用〈浓〉。“高速”指速度，不用来形容味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '040634d2-eecc-4f2b-ac40-4e35c0af5098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88180, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一台高速地打印机。", "corrected_sentence": "这是一台高速的打印机。", "error_description": "错误在修饰词。“高速”修饰名词“打印机”时要用“的”，不能用“地”。正确形式为“高速的打印机”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '040634d2-eecc-4f2b-ac40-4e35c0af5098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88180, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子弹高速的射出，打中了目标。", "corrected_sentence": "子弹高速射出，打中了目标。", "error_description": "错误在修饰词。“高速”修饰动词“射出”时不用“的”，直接放在动词前面即可，或用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '040634d2-eecc-4f2b-ac40-4e35c0af5098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88187, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "明亮", "is_correct": true, "explanation": "“明亮”指有光、亮堂，与“黑暗”在没有光的意义上相对。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”形容头脑灵活，与“黑暗”没有反义关系。"}, {"text": "寒冷", "is_correct": false, "explanation": "“寒冷”与“温暖”相对，与“黑暗”没有反义关系。"}, {"text": "整齐", "is_correct": false, "explanation": "“整齐”指排列有序，与“黑暗”没有反义关系。"}], "correct_answer": "明亮", "explanations": {"明亮": "“明亮”指有光、亮堂，与“黑暗”在没有光的意义上相对。", "聪明": "“聪明”形容头脑灵活，与“黑暗”没有反义关系。", "寒冷": "“寒冷”与“温暖”相对，与“黑暗”没有反义关系。", "整齐": "“整齐”指排列有序，与“黑暗”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed880c2a-f0c2-4fac-8d1e-932e3919a069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88187, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "明亮", "is_correct": true, "explanation": "“明亮”指有光、亮堂，与“黑暗”在没有光的意义上相对。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”指没有声音，与“黑暗”没有反义关系。"}, {"text": "热闹", "is_correct": false, "explanation": "“热闹”指人多声杂，与“黑暗”没有反义关系。"}, {"text": "甜蜜", "is_correct": false, "explanation": "“甜蜜”形容味道或感情美好，与“黑暗”没有反义关系。"}], "correct_answer": "明亮", "explanations": {"明亮": "“明亮”指有光、亮堂，与“黑暗”在没有光的意义上相对。", "安静": "“安静”指没有声音，与“黑暗”没有反义关系。", "热闹": "“热闹”指人多声杂，与“黑暗”没有反义关系。", "甜蜜": "“甜蜜”形容味道或感情美好，与“黑暗”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed880c2a-f0c2-4fac-8d1e-932e3919a069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88187, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "黑暗是没有光，什么也看不见。", "primary_collocate": null, "pronunciation": "hēi àn", "ipa": "xei˥ an˥˩", "syllable_count": 2, "sentences": [{"text": "黑暗里什么也看不见。", "target_word": "黑暗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "停电后，屋子里很黑暗。", "target_word": "黑暗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子怕黑暗，不敢一个人睡。", "target_word": "黑暗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洞里又冷又黑暗。", "target_word": "黑暗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在黑暗中慢慢往前走。", "target_word": "黑暗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑了，路上越来越黑暗。", "target_word": "黑暗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我打开灯，黑暗不见了。", "target_word": "黑暗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地下室很黑暗，要带手电。", "target_word": "黑暗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黑暗的房间里没有一点声音。", "target_word": "黑暗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在黑暗中找到了门。", "target_word": "黑暗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "形容词；没有光；什么也看不见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e5d9128-ce98-4150-aea3-14a63da0a28d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88187, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "耀眼", "is_correct": false, "explanation": "语义：“耀眼”指光很强，与“什么也看不见”矛盾。"}, {"text": "黑暗", "is_correct": true, "explanation": "正确：“黑暗”指没有光，与“什么也看不见”一致。"}, {"text": "雪白", "is_correct": false, "explanation": "体貌：“雪白”描述可见的颜色，与“什么也看不见”矛盾。"}, {"text": "温暖", "is_correct": false, "explanation": "搭配：“温暖”描述温度或气氛，不能作为“里”前的处所词。"}], "explanations": {"耀眼": "语义：“耀眼”指光很强，与“什么也看不见”矛盾。", "黑暗": "正确：“黑暗”指没有光，与“什么也看不见”一致。", "雪白": "体貌：“雪白”描述可见的颜色，与“什么也看不见”矛盾。", "温暖": "搭配：“温暖”描述温度或气氛，不能作为“里”前的处所词。"}, "sentence_index": 0, "correct_answer": "黑暗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块布料是黑暗的，做窗帘正好。", "explanation": "这里应该用〈漆黑〉。“黑暗”指没有光，不用来形容布料的颜色；颜色深要用“漆黑”。"}, {"text": "台灯亮着，屋里的光线很黑暗。", "explanation": "这里应该用〈昏暗〉。灯亮着时光线只能是昏暗，“黑暗”指完全没有光，与亮着的台灯矛盾。"}, {"text": "晒了一个夏天，他的胳膊很黑暗。", "explanation": "这里应该用〈黝黑〉。“黑暗”不用来说皮肤的颜色，晒得很深的皮肤要用“黝黑”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed880c2a-f0c2-4fac-8d1e-932e3919a069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88187, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "光亮", "is_correct": false, "explanation": "语义：开了灯，光亮应当出现，不会“不见了”，与“打开灯”矛盾。"}, {"text": "黑暗", "is_correct": true, "explanation": "正确：开灯后黑暗会消失，“不见了”与之搭配。"}, {"text": "干净", "is_correct": false, "explanation": "搭配：“干净”指没有污垢的状态，不能作为会“不见了”的事物。"}, {"text": "宽敞", "is_correct": false, "explanation": "搭配：“宽敞”形容空间，不能用作“不见了”的主语。"}], "explanations": {"光亮": "语义：开了灯，光亮应当出现，不会“不见了”，与“打开灯”矛盾。", "黑暗": "正确：开灯后黑暗会消失，“不见了”与之搭配。", "干净": "搭配：“干净”指没有污垢的状态，不能作为会“不见了”的事物。", "宽敞": "搭配：“宽敞”形容空间，不能用作“不见了”的主语。"}, "sentence_index": 6, "correct_answer": "黑暗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一听这话，脸色立刻黑暗下来。", "explanation": "这里应该用〈阴沉〉。“黑暗”指缺少光线，形容脸色要用“阴沉”或说“脸色黑下来”。"}, {"text": "节日晚会的气氛很黑暗，大家都在唱歌跳舞。", "explanation": "这里应该用〈热闹〉。“黑暗”指没有光，与唱歌跳舞的气氛矛盾；形容场面欢快要用“热闹”。"}, {"text": "这间教室的窗户很大，阳光很好，里面黑暗得很。", "explanation": "这里应该用〈明亮〉。窗户大、阳光好，屋里应当明亮，“黑暗”指没有光，与语境矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed880c2a-f0c2-4fac-8d1e-932e3919a069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88187, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山洞里黑暗的什么也看不见。", "corrected_sentence": "山洞里黑暗得什么也看不见。", "error_description": "错误形式“黑暗的什么也看不见”，正确形式“黑暗得什么也看不见”。“什么也看不见”是表示程度的补语，要用“得”，不能用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed880c2a-f0c2-4fac-8d1e-932e3919a069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88187, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "走廊里渐渐黑暗上来了。", "corrected_sentence": "走廊里渐渐黑暗下来了。", "error_description": "错误形式“黑暗上来”，正确形式“黑暗下来”。表示颜色或光线由亮变暗的趋向要用“下来”，“上来”方向相反，不能用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed880c2a-f0c2-4fac-8d1e-932e3919a069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
