INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88205, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们去年享受过学生优惠过。", "corrected_sentence": "我们去年享受过学生优惠。", "error_description": "体标位置错误：“过”只能紧跟动词“享受”，句末“优惠过”多出一个“过”。正确形式为“享受过学生优惠”，不能说“享受过学生优惠过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '040634d2-eecc-4f2b-ac40-4e35c0af5098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88205, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学生去电影院时可以享受一只优惠。", "corrected_sentence": "学生去电影院时可以享受一项优惠。", "error_description": "量词错误：“优惠”是抽象的待遇，应搭配量词“项”，不能用“只”。“只”用于动物或成对器官等具体事物，应说“享受一项优惠”，不能说“享受一只优惠”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '040634d2-eecc-4f2b-ac40-4e35c0af5098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
