INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88206, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "价格、待遇等比一般的更好的好处。", "primary_collocate": null, "pronunciation": "yōu huì", "ipa": "jou˥ xweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这个城市给外地人才很多优惠。", "target_word": "优惠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家对小公司有税收优惠。", "target_word": "优惠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "银行给老客户一些优惠。", "target_word": "优惠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生在这里能得到不少优惠。", "target_word": "优惠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个政策给农民带来了优惠。", "target_word": "优惠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买房子的时候，他享受了贷款优惠。", "target_word": "优惠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了留住人才，公司给他们提供了很多优惠。", "target_word": "优惠", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家酒店给长住的客人更多优惠。", "target_word": "优惠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新办的工厂可以得到土地优惠。", "target_word": "优惠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老客户总能得到更好的优惠。", "target_word": "优惠", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "优惠券", "label": "复合词"}, {"form": "优惠价", "label": "复合词"}], "register": "通用", "sense_fingerprint": "优惠：价格、待遇、政策等方面比一般更好的好处，如税收优惠、贷款优惠", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8d3828f-e88f-4827-ada6-b99a5aa80d30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88206, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "优惠", "is_correct": true, "explanation": "正确。优惠：价格、待遇、政策等方面比一般更好的好处。"}, {"text": "优化", "is_correct": false, "explanation": "huà（第四声）与 huì 韵母不同，意思是优化，使更好。"}, {"text": "忧悔", "is_correct": false, "explanation": "huǐ（第三声）与 huì（第四声）声调不同，意思是后悔。"}, {"text": "邮汇", "is_correct": false, "explanation": "yóu（第二声）与 yōu（第一声）声调不同，意思是邮政汇款。"}], "explanations": {"优惠": "正确。优惠：价格、待遇、政策等方面比一般更好的好处。", "优化": "huà（第四声）与 huì 韵母不同，意思是优化，使更好。", "忧悔": "huǐ（第三声）与 huì（第四声）声调不同，意思是后悔。", "邮汇": "yóu（第二声）与 yōu（第一声）声调不同，意思是邮政汇款。"}, "sentence_index": null, "correct_answer": "优惠"}, "level_3": {"options": [{"text": "优惠", "is_correct": true, "explanation": "正确。“优惠”指城市给人才的待遇，符合“很多优惠”的语境。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学生的课后任务，城市不会把它“给”人才作为待遇。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的体格特征，城市无法“给”人才身高。"}, {"text": "钢铁", "is_correct": false, "explanation": "语义：钢铁是建筑材料，不能作为给人才的待遇。"}], "explanations": {"优惠": "正确。“优惠”指城市给人才的待遇，符合“很多优惠”的语境。", "作业": "语义：作业是学生的课后任务，城市不会把它“给”人才作为待遇。", "身高": "体貌：身高是人的体格特征，城市无法“给”人才身高。", "钢铁": "语义：钢铁是建筑材料，不能作为给人才的待遇。"}, "sentence_index": 0, "correct_answer": "优惠"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "每天读书对头脑有很多优惠。", "explanation": "这里应该用〈好处〉。优惠用于价格、待遇或政策方面，不用来说读书对头脑的益处。"}, {"text": "这个方案的优惠是跑得快，所以很多人选它。", "explanation": "这里应该用〈优点〉。优惠指价格、待遇、政策等带来的好处，不用来说方案本身的长处。"}, {"text": "这个孩子很优惠，大家都愿意和他玩。", "explanation": "这里应该用〈友好〉。优惠只用于价格、待遇、政策等方面，不用来形容孩子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '040634d2-eecc-4f2b-ac40-4e35c0af5098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88206, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "优惠", "is_correct": true, "explanation": "正确。优惠：价格、待遇、政策等方面比一般更好的好处。"}, {"text": "游回", "is_correct": false, "explanation": "yóu（第二声）与 yōu（第一声）声调不同，huí（第二声）与 huì（第四声）声调不同，意思是游着返回。"}, {"text": "友会", "is_correct": false, "explanation": "yǒu（第三声）与 yōu（第一声）声调不同，意思是朋友之间的团体或聚会。"}, {"text": "油灰", "is_correct": false, "explanation": "yóu（第二声）与 yōu（第一声）、huī（第一声）与 huì（第四声）声调均不同，意思是一种用油调成的腻子。"}], "explanations": {"优惠": "正确。优惠：价格、待遇、政策等方面比一般更好的好处。", "游回": "yóu（第二声）与 yōu（第一声）声调不同，huí（第二声）与 huì（第四声）声调不同，意思是游着返回。", "友会": "yǒu（第三声）与 yōu（第一声）声调不同，意思是朋友之间的团体或聚会。", "油灰": "yóu（第二声）与 yōu（第一声）、huī（第一声）与 huì（第四声）声调均不同，意思是一种用油调成的腻子。"}, "sentence_index": null, "correct_answer": "优惠"}, "level_3": {"options": [{"text": "优惠", "is_correct": true, "explanation": "正确。“优惠”指公司为留住人才提供的待遇，符合语境。"}, {"text": "病毒", "is_correct": false, "explanation": "语义：病毒不是公司能提供给员工的东西，句子不通。"}, {"text": "噪音", "is_correct": false, "explanation": "语义：噪音是刺耳的声响，公司不会作为待遇提供给人才，句子不通。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：体重是人的身体特征，不能由公司提供。"}], "explanations": {"优惠": "正确。“优惠”指公司为留住人才提供的待遇，符合语境。", "病毒": "语义：病毒不是公司能提供给员工的东西，句子不通。", "噪音": "语义：噪音是刺耳的声响，公司不会作为待遇提供给人才，句子不通。", "体重": "体貌：体重是人的身体特征，不能由公司提供。"}, "sentence_index": 6, "correct_answer": "优惠"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次洪水的优惠很大，大家都很难过。", "explanation": "这里应该用〈损失〉。优惠是对人有利的价格或待遇，不用来说洪水造成的损失。"}, {"text": "她的写作水平有很大优惠。", "explanation": "这里应该用〈进步〉。优惠用于价格、待遇和政策，不用来说写作水平的提高。"}, {"text": "这次登山有很大优惠。", "explanation": "这里应该用〈难度〉。优惠是对人有利的价格或待遇，不用来说登山的难度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '040634d2-eecc-4f2b-ac40-4e35c0af5098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88206, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校为老师们争取了到一些优惠。", "corrected_sentence": "学校为老师们争取到了一些优惠。", "error_description": "错误在补语与“了”的位置。“争取到”是动补结构，“了”应放在“到”后面，不能放在“到”前面。正确形式为“争取到了一些优惠”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '040634d2-eecc-4f2b-ac40-4e35c0af5098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88206, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老客户总能得到一些的优惠。", "corrected_sentence": "老客户总能得到一些优惠。", "error_description": "错误在“一些”与“优惠”之间多了“的”。“一些”修饰名词时直接放在名词前，不加“的”。正确形式为“一些优惠”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '040634d2-eecc-4f2b-ac40-4e35c0af5098') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
