INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88209, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "中央政府是管整个国家大事的最大的政府。", "primary_collocate": null, "pronunciation": "zhōng yāng zhèng fǔ", "ipa": "tʂʊŋ˥ jɑŋ˥ tʂɤŋ˥˩ fu˨˩˦", "syllable_count": 4, "sentences": [{"text": "中央政府管着整个国家的大事。", "target_word": "中央政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中央政府是全国最大的政府。", "target_word": "中央政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻里说，中央政府要提高工资。", "target_word": "中央政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中央政府的决定对全国都有用。", "target_word": "中央政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各个省的政府都要听中央政府的话。", "target_word": "中央政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中央政府每年都会开一次大会。", "target_word": "中央政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们介绍了中央政府的工作。", "target_word": "中央政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中央政府为受灾的地区送去了粮食。", "target_word": "中央政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爷爷常看中央政府的新闻。", "target_word": "中央政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中央政府决定在全国种更多树。", "target_word": "中央政府", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "正式", "sense_fingerprint": "管全国大事的最大的政府", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476bafa-4a1b-4403-b163-44a07b2b0ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88209, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厨房", "is_correct": false, "explanation": "语义：厨房是房间，不能管理国家大事，与「整个国家」不相称。"}, {"text": "水", "is_correct": false, "explanation": "配价：「管着」需要有管理权的主体，水不能作主语管理国家大事。"}, {"text": "中央政府", "is_correct": true, "explanation": "中央政府是管理整个国家大事的最大政府，作主语「管着整个国家的大事」符合句意。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是学习的场所，不管国家大事，与「整个国家」不相称。"}], "explanations": {"厨房": "语义：厨房是房间，不能管理国家大事，与「整个国家」不相称。", "水": "配价：「管着」需要有管理权的主体，水不能作主语管理国家大事。", "中央政府": "中央政府是管理整个国家大事的最大政府，作主语「管着整个国家的大事」符合句意。", "教室": "语义：教室是学习的场所，不管国家大事，与「整个国家」不相称。"}, "sentence_index": 0, "correct_answer": "中央政府"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个城市里有三朵中央政府。", "explanation": "这里应该用〈个〉。〈朵〉用于花朵、云朵等，不能用于机构。"}, {"text": "我们国家有一只中央政府。", "explanation": "这里应该用〈个〉。〈只〉用于动物或成对物品中的一个，不能用于机构。"}, {"text": "这座岛上有一条中央政府。", "explanation": "这里应该用〈个〉。〈条〉用于细长的东西，不能用于机构。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b2f6d0-4009-4c46-a64f-4bf1effb2f7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88209, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "镜子", "is_correct": false, "explanation": "语义：镜子是物品，不是可以被介绍工作的机构，与句中的「工作」不搭。"}, {"text": "中央政府", "is_correct": true, "explanation": "中央政府的工作是可以向学生介绍的内容，「介绍了中央政府的工作」符合句意。"}, {"text": "苹果", "is_correct": false, "explanation": "语义：苹果是水果，不是可以介绍工作的对象，与句意不符。"}, {"text": "饼干", "is_correct": false, "explanation": "配价：「……的工作」需要有工作能力的人或机构作主体，饼干不能有「工作」。"}], "explanations": {"镜子": "语义：镜子是物品，不是可以被介绍工作的机构，与句中的「工作」不搭。", "中央政府": "中央政府的工作是可以向学生介绍的内容，「介绍了中央政府的工作」符合句意。", "苹果": "语义：苹果是水果，不是可以介绍工作的对象，与句意不符。", "饼干": "配价：「……的工作」需要有工作能力的人或机构作主体，饼干不能有「工作」。"}, "sentence_index": 6, "correct_answer": "中央政府"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "中央政府负责规划本地的公交路线。", "explanation": "这里应该用〈地方政府〉。〈中央政府〉管全国大事，不负责规划某一地区的公交路线。"}, {"text": "中央政府负责组织本县的小学招生。", "explanation": "这里应该用〈县政府〉。〈中央政府〉的职权范围是全国，不直接组织某一县的招生。"}, {"text": "中央政府决定在本区修建一个公园。", "explanation": "这里应该用〈区政府〉。〈中央政府〉管全国大事，不决定某一区的具体建设项目。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b2f6d0-4009-4c46-a64f-4bf1effb2f7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
