INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88213, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "服务业是帮别人做事、不是做东西的行业，比如饭店。", "primary_collocate": null, "pronunciation": "fú wù yè", "ipa": "fu˧˥ u˥˩ jɛ˥˩", "syllable_count": 3, "sentences": [{"text": "饭店和酒店都属于服务业。", "target_word": "服务业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务业的工作是帮客人做事。", "target_word": "服务业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在服务业工作，每天都要对客人笑。", "target_word": "服务业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开饭店是服务业，不是做东西的工作。", "target_word": "服务业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在很多年轻人想去服务业工作。", "target_word": "服务业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务业不做东西，主要是帮别人做事。", "target_word": "服务业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "理发店、饭店和商店都是服务业。", "target_word": "服务业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务业的人要对客人很客气。", "target_word": "服务业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我妈妈在服务业工作了十年。", "target_word": "服务业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的服务业很发达，饭店特别多。", "target_word": "服务业", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "服務業", "label": "繁体"}], "register": "中性", "sense_fingerprint": "帮别人做事而不做东西的行业，如饭店", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e5d9128-ce98-4150-aea3-14a63da0a28d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88213, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工业", "is_correct": false, "explanation": "语义：饭店和酒店不属于工业，这个说法与事实相反。"}, {"text": "服务业", "is_correct": true, "explanation": "正确：饭店和酒店是帮人做事、不做东西的行业，属于服务业。"}, {"text": "农业", "is_correct": false, "explanation": "语义：饭店和酒店不属于农业，与事实相反。"}, {"text": "工厂", "is_correct": false, "explanation": "搭配：“属于”后接行业类别，“工厂”是场所，不能作类别。"}], "explanations": {"工业": "语义：饭店和酒店不属于工业，这个说法与事实相反。", "服务业": "正确：饭店和酒店是帮人做事、不做东西的行业，属于服务业。", "农业": "语义：饭店和酒店不属于农业，与事实相反。", "工厂": "搭配：“属于”后接行业类别，“工厂”是场所，不能作类别。"}, "sentence_index": 0, "correct_answer": "服务业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家饭店的服务业很好，客人都很满意。", "explanation": "这里应该用〈服务〉。“服务业”是行业名称，说某家店的服务质量要用“服务”。"}, {"text": "饭店里的服务业很热情，一直招呼客人。", "explanation": "这里应该用〈服务员〉。“服务业”指行业，不指人，说站在那里招呼客人的人要用“服务员”。"}, {"text": "我的服务业是老师，在学校教书。", "explanation": "这里应该用〈职业〉。“服务业”指一类行业，不指个人的工作；说自己做什么工作要用“职业”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed880c2a-f0c2-4fac-8d1e-932e3919a069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88213, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "建筑业", "is_correct": false, "explanation": "语义：理发店、饭店和商店不属于建筑业，与事实相反。"}, {"text": "服务业", "is_correct": true, "explanation": "正确：理发店、饭店和商店都是帮人做事、不做东西的行业。"}, {"text": "矿业", "is_correct": false, "explanation": "语义：理发店、饭店和商店不属于矿业，与事实相反。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“汽车”是产品，不是行业，不能用“都是”来指类别。"}], "explanations": {"建筑业": "语义：理发店、饭店和商店不属于建筑业，与事实相反。", "服务业": "正确：理发店、饭店和商店都是帮人做事、不做东西的行业。", "矿业": "语义：理发店、饭店和商店不属于矿业，与事实相反。", "汽车": "搭配：“汽车”是产品，不是行业，不能用“都是”来指类别。"}, "sentence_index": 6, "correct_answer": "服务业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个城市的服务业很多，市民可以在那里办手续。", "explanation": "这里应该用〈服务中心〉。“服务业”指行业，不指可以办事的地方。"}, {"text": "机场的服务业就在一楼，可以帮你问路。", "explanation": "这里应该用〈服务台〉。“服务业”是行业，不能指设在一楼、可以问路的地方。"}, {"text": "这家健身房的服务业很多，有游泳和瑜伽。", "explanation": "这里应该用〈服务项目〉。“服务项目”指提供的具体项目，“服务业”是行业，不能列出游泳和瑜伽。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed880c2a-f0c2-4fac-8d1e-932e3919a069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88213, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个城市的服务业们很发达，年轻人很多。", "corrected_sentence": "这个城市的服务业很发达，年轻人很多。", "error_description": "错误形式“服务业们”，正确形式“服务业”。“服务业”是行业名称，不能加“们”表示复数；“们”一般只用于指人的名词后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed880c2a-f0c2-4fac-8d1e-932e3919a069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88213, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "表哥服务业工作了三年。", "corrected_sentence": "表哥在服务业工作了三年。", "error_description": "错误形式“服务业工作”，正确形式“在服务业工作”。“服务业”作工作的场所时要用介词“在”引出，缺“在”句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed880c2a-f0c2-4fac-8d1e-932e3919a069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88217, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "在野", "is_correct": true, "explanation": "正确：“在野”指不担任政府职务，与“执政”相对，如“在野党”与“执政党”相对。"}, {"text": "游泳", "is_correct": false, "explanation": "与“执政”没有反义关系，二者意思无关。"}, {"text": "思考", "is_correct": false, "explanation": "与“执政”没有反义关系，“思考”指用脑子考虑问题。"}, {"text": "旅行", "is_correct": false, "explanation": "与“执政”没有反义关系，“旅行”指外出游览。"}], "correct_answer": "在野", "explanations": {"在野": "正确：“在野”指不担任政府职务，与“执政”相对，如“在野党”与“执政党”相对。", "游泳": "与“执政”没有反义关系，二者意思无关。", "思考": "与“执政”没有反义关系，“思考”指用脑子考虑问题。", "旅行": "与“执政”没有反义关系，“旅行”指外出游览。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02715c0c-42fc-4b33-851a-a1d47916bb2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88217, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "在野", "is_correct": true, "explanation": "正确：“在野”指不担任政府职务，与“执政”相对，如“在野党”与“执政党”相对。"}, {"text": "出版", "is_correct": false, "explanation": "与“执政”没有反义关系，“出版”指印刷发行书刊。"}, {"text": "跳舞", "is_correct": false, "explanation": "与“执政”没有反义关系，二者意思无关。"}, {"text": "散步", "is_correct": false, "explanation": "与“执政”没有反义关系，“散步”指随意地走动。"}], "correct_answer": "在野", "explanations": {"在野": "正确：“在野”指不担任政府职务，与“执政”相对，如“在野党”与“执政党”相对。", "出版": "与“执政”没有反义关系，“出版”指印刷发行书刊。", "跳舞": "与“执政”没有反义关系，二者意思无关。", "散步": "与“执政”没有反义关系，“散步”指随意地走动。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02715c0c-42fc-4b33-851a-a1d47916bb2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88217, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "执政是管理一个国家，做主要的决定。", "primary_collocate": null, "pronunciation": "zhí zhèng", "ipa": "tʂɨ³⁵ tʂɤŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "这个党已经执政十年了。", "target_word": "执政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新总统执政以后，做了很多改变。", "target_word": "执政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他希望自己的党以后能执政。", "target_word": "执政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位领导人执政的时候，国家很安定。", "target_word": "执政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个政党想执政，就要得到人民的支持。", "target_word": "执政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个国家由一个政党长期执政。", "target_word": "执政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他执政五年，经济发展得很快。", "target_word": "执政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老百姓希望执政的人多为大家想想。", "target_word": "执政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的政党轮流执政。", "target_word": "执政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是在什么时候开始执政的？", "target_word": "执政", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "执政了", "label": "体标"}, {"form": "执政过", "label": "体标"}, {"form": "执政党", "label": "复合"}], "register": "书面", "sense_fingerprint": "执政：管理国家并做主要决定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2629cfaa-ecb6-48f0-80ae-066a0850e85a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88217, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "执政", "is_correct": true, "explanation": "正确：执政（zhí zhèng）是管理国家、做主要决定，就是这个词。"}, {"text": "指正", "is_correct": false, "explanation": "zhǐ（第三声）与 zhí（第二声）声调不同，意思是指出错误并加以改正。"}, {"text": "指证", "is_correct": false, "explanation": "zhǐ 与 zhí 声调不同，意思是指认并作证。"}, {"text": "持证", "is_correct": false, "explanation": "chí 与 zhí 声母不同（ch 与 zh），意思是持有证件。"}, {"text": "时政", "is_correct": false, "explanation": "shí 与 zhí 声母不同（sh 与 zh），意思是当前的政治事务。"}], "explanations": {"执政": "正确：执政（zhí zhèng）是管理国家、做主要决定，就是这个词。", "指正": "zhǐ（第三声）与 zhí（第二声）声调不同，意思是指出错误并加以改正。", "指证": "zhǐ 与 zhí 声调不同，意思是指认并作证。", "持证": "chí 与 zhí 声母不同（ch 与 zh），意思是持有证件。", "时政": "shí 与 zhí 声母不同（sh 与 zh），意思是当前的政治事务。"}, "sentence_index": null, "correct_answer": "执政"}, "level_3": {"options": [{"text": "执政", "is_correct": true, "explanation": "正确：“执政”指管理国家，与“已经……十年了”相符。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：党不能“游泳”，句意不通。"}, {"text": "出版", "is_correct": false, "explanation": "语义：党不能“出版”，句意不通。"}, {"text": "退役", "is_correct": false, "explanation": "搭配：“退役”多用于军人或装备，不说党“退役”。"}], "explanations": {"执政": "正确：“执政”指管理国家，与“已经……十年了”相符。", "游泳": "语义：党不能“游泳”，句意不通。", "出版": "语义：党不能“出版”，句意不通。", "退役": "搭配：“退役”多用于军人或装备，不说党“退役”。"}, "sentence_index": 0, "correct_answer": "执政"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在报社执政了十年。", "explanation": "这里应该用〈任职〉。执政指掌握国家政权、管理国家，报社的职务要说〈任职〉。"}, {"text": "他在这家公司执政了五年。", "explanation": "这里应该用〈工作〉。执政用于国家或政党，不用于公司。"}, {"text": "他在这所学校执政多年。", "explanation": "这里应该用〈掌权〉。执政指掌握国家政权，学校里的权力要说〈掌权〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02715c0c-42fc-4b33-851a-a1d47916bb2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88217, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "执政", "is_correct": true, "explanation": "正确：“执政”指管理国家，与“经济发展得很快”相符。"}, {"text": "绘画", "is_correct": false, "explanation": "语义：“绘画”与经济发展无关，句意不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "语域：“睡觉”是口语，与书面语的“执政”不协调，且与经济发展无关。"}, {"text": "失眠", "is_correct": false, "explanation": "语义：“失眠”不能带来经济的快速发展，句意不通。"}], "explanations": {"执政": "正确：“执政”指管理国家，与“经济发展得很快”相符。", "绘画": "语义：“绘画”与经济发展无关，句意不通。", "睡觉": "语域：“睡觉”是口语，与书面语的“执政”不协调，且与经济发展无关。", "失眠": "语义：“失眠”不能带来经济的快速发展，句意不通。"}, "sentence_index": 6, "correct_answer": "执政"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在这家饭店执政了十年。", "explanation": "这里应该用〈经营〉。执政指掌握国家政权，饭店的经营要说〈经营〉。"}, {"text": "他在会议上执政了一个下午。", "explanation": "这里应该用〈主持〉。执政用于国家，会议的主持要说〈主持〉。"}, {"text": "他在这个小区执政了三十年。", "explanation": "这里应该用〈管理〉。执政用于国家，小区的管理要说〈管理〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02715c0c-42fc-4b33-851a-a1d47916bb2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88217, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个党已经执政着五年了。", "corrected_sentence": "这个党已经执政五年了。", "error_description": "体标错误：表示已经执政的时长时，“执政”后不能加“着”，应说“执政五年了”。错误形式“执政着五年了”，正确形式“执政五年了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02715c0c-42fc-4b33-851a-a1d47916bb2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88217, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他被执政三年，经济发展得很快。", "corrected_sentence": "他执政三年，经济发展得很快。", "error_description": "被字句错误：“执政”不能用“被”字句，应直接说“他执政三年”，或用“由……执政”。错误形式“他被执政”，正确形式“他执政”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02715c0c-42fc-4b33-851a-a1d47916bb2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
