INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88231, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "夫人是别人对一个人妻子的客气叫法。", "primary_collocate": null, "pronunciation": "fū rén", "ipa": "fu˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "陈先生，您夫人身体好吗？", "target_word": "夫人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他介绍说，这是他的夫人。", "target_word": "夫人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总统夫人去医院看望了孩子们。", "target_word": "夫人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周教授的夫人在大学教书。", "target_word": "夫人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "李先生，您夫人最近身体怎么样？", "target_word": "夫人", "complexity_tier": "T3", "furigana": "Lǐ xiānsheng, nín fūrén zuìjìn shēntǐ zěnmeyàng?", "sentence_source": "generated"}, {"text": "我想请你和夫人来我家吃饭。", "target_word": "夫人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位夫人说话很客气。", "target_word": "夫人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长和他夫人坐在第一排。", "target_word": "夫人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "张经理的夫人做的菜很好吃。", "target_word": "夫人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宴会上，那位夫人一直笑着。", "target_word": "夫人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "总统夫人", "label": "复合"}, {"form": "第一夫人", "label": "复合"}], "register": "正式", "sense_fingerprint": "夫人：客气地称呼某人的妻子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b9365df-7ca4-49ba-9257-3e6a2a4f3384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88231, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "夫人", "is_correct": true, "explanation": "夫人是客气称呼别人妻子的词，“您夫人身体好吗”问的正是对方妻子，此处正合适。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑没有身体，“身体好吗”只能问人。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子没有身体，不能问它的“身体好吗”。"}, {"text": "公司", "is_correct": false, "explanation": "搭配：“身体好”通常只用于人，不能用于公司。"}], "explanations": {"夫人": "夫人是客气称呼别人妻子的词，“您夫人身体好吗”问的正是对方妻子，此处正合适。", "电脑": "语义：电脑没有身体，“身体好吗”只能问人。", "房子": "语义：房子没有身体，不能问它的“身体好吗”。", "公司": "搭配：“身体好”通常只用于人，不能用于公司。"}, "sentence_index": 0, "correct_answer": "夫人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周教授是一位夫人，在大学教书。", "explanation": "这里应该用〈先生〉。“夫人”指女性配偶，“周教授”是男性，应说“先生”。"}, {"text": "那位夫人刚满二十岁，还是学生。", "explanation": "这里应该用〈女士〉。“夫人”指已婚女子，二十岁的学生应称“女士”或“小姐”。"}, {"text": "我在车站遇到一只夫人。", "explanation": "这里应该用〈位〉。“夫人”指人，指人的量词用“位”，不用“只”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12a95067-003d-4c38-8b4f-542e1f4d664a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88231, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "夫人", "is_correct": true, "explanation": "夫人是对别人妻子的尊称，“这位夫人”是对陌生已婚女子的客气称呼，说话很客气，此处正合适。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫不会说话，“说话很客气”只能用于人。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：量词“位”只用于人，不能说“这位桌子”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有语言，“说话很客气”不成立。"}], "explanations": {"夫人": "夫人是对别人妻子的尊称，“这位夫人”是对陌生已婚女子的客气称呼，说话很客气，此处正合适。", "小猫": "语义：小猫不会说话，“说话很客气”只能用于人。", "桌子": "搭配：量词“位”只用于人，不能说“这位桌子”。", "石头": "语义：石头没有语言，“说话很客气”不成立。"}, "sentence_index": 6, "correct_answer": "夫人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那位夫人才五岁，还在幼儿园玩。", "explanation": "这里应该用〈小姑娘〉。“夫人”指已婚的成年女子，五岁的孩子不能称“夫人”。"}, {"text": "她每天在学校教书，是一名夫人。", "explanation": "这里应该用〈老师〉。“夫人”不是职业称呼，说职业要用“老师”。"}, {"text": "他是一位夫人，很有礼貌。", "explanation": "这里应该用〈先生〉。“夫人”指女性，“他”是男性，应说“先生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12a95067-003d-4c38-8b4f-542e1f4d664a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88231, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "王先生，他们夫人最近在忙什么？", "corrected_sentence": "王先生，您夫人最近在忙什么？", "error_description": "“他们”指多人，王先生是一个人，当面问候时应说“您夫人”，不能用“他们夫人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12a95067-003d-4c38-8b4f-542e1f4d664a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88231, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "展览会上站着三位夫人们。", "corrected_sentence": "展览会上站着三位夫人。", "error_description": "“们”不能跟在数词和量词之后，“三位夫人”已表示复数，应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12a95067-003d-4c38-8b4f-542e1f4d664a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
