INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88232, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "对别人妻子的尊称。", "primary_collocate": null, "pronunciation": "fū rén", "ipa": "fu˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "张先生和他的夫人一起来了。", "target_word": "夫人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，您夫人今天在家吗？", "target_word": "夫人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理的夫人给大家做了一桌菜。", "target_word": "夫人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位是李总的夫人，请多关照。", "target_word": "夫人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先生，请代我向您夫人问好。", "target_word": "夫人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大使和夫人参加了晚上的宴会。", "target_word": "夫人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他陪王教授的夫人去海边住了几天。", "target_word": "夫人", "complexity_tier": "T3", "furigana": "tā péi Wáng jiàoshòu de fūrén qù hǎibiān zhùle jǐ tiān.", "sentence_source": "generated"}, {"text": "校长夫人送给我们一些水果。", "target_word": "夫人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "欢迎各位先生和夫人来参加晚会。", "target_word": "夫人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板的夫人穿着一件红色的衣服。", "target_word": "夫人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "总统夫人", "label": "复合"}, {"form": "第一夫人", "label": "复合"}], "register": "正式", "sense_fingerprint": "夫人：尊称别人的妻子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b9365df-7ca4-49ba-9257-3e6a2a4f3384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88232, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "夫人", "is_correct": true, "explanation": "夫人是对别人妻子的尊称，“他的夫人”指张先生的妻子，此处正合适。"}, {"text": "女士", "is_correct": false, "explanation": "语义：“女士”是对女性的通称，不指配偶，“他的女士”说不通。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“一起来”的主语应是人，“房子”不能与人并列来到这里。"}, {"text": "书", "is_correct": false, "explanation": "搭配：“书”不会自己“来”，“他的书一起来了”不成立。"}], "explanations": {"夫人": "夫人是对别人妻子的尊称，“他的夫人”指张先生的妻子，此处正合适。", "女士": "语义：“女士”是对女性的通称，不指配偶，“他的女士”说不通。", "房子": "搭配：“一起来”的主语应是人，“房子”不能与人并列来到这里。", "书": "搭配：“书”不会自己“来”，“他的书一起来了”不成立。"}, "sentence_index": 0, "correct_answer": "夫人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的女儿是一位夫人，才上小学。", "explanation": "这里应该用〈小姑娘〉。“夫人”指已婚的成年女子，孩子不能称“夫人”。"}, {"text": "那位夫人还没有结婚。", "explanation": "这里应该用〈女士〉。“夫人”指已婚女子，对未婚女性应称“女士”或“小姐”。"}, {"text": "我在门口看见一只夫人。", "explanation": "这里应该用〈位〉。“夫人”指人，指人的量词用“位”，“只”多用于动物等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12a95067-003d-4c38-8b4f-542e1f4d664a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88232, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "夫人", "is_correct": true, "explanation": "夫人是对别人妻子的尊称，“王教授的夫人”指王教授的妻子，此处正合适。"}, {"text": "论文", "is_correct": false, "explanation": "语义：“陪”的对象是人，“论文”不能跟着人去海边住。"}, {"text": "照相机", "is_correct": false, "explanation": "语义：照相机是器材，不能被“陪”着去海边住几天。"}, {"text": "行李", "is_correct": false, "explanation": "搭配：“陪”一般用于人，不能说“陪行李去海边”。"}], "explanations": {"夫人": "夫人是对别人妻子的尊称，“王教授的夫人”指王教授的妻子，此处正合适。", "论文": "语义：“陪”的对象是人，“论文”不能跟着人去海边住。", "照相机": "语义：照相机是器材，不能被“陪”着去海边住几天。", "行李": "搭配：“陪”一般用于人，不能说“陪行李去海边”。"}, "sentence_index": 6, "correct_answer": "夫人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是一位夫人，很有礼貌。", "explanation": "这里应该用〈先生〉。“夫人”指女性配偶，“他”是男性，应说“先生”。"}, {"text": "这位夫人才五岁，还在上幼儿园。", "explanation": "这里应该用〈小姑娘〉。“夫人”指已婚的成年女子，五岁的孩子不能称“夫人”。"}, {"text": "她在医院工作，是一名夫人。", "explanation": "这里应该用〈护士〉。“夫人”是对妻子的尊称，不是职业称呼，说职业要用“护士”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12a95067-003d-4c38-8b4f-542e1f4d664a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88232, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "王经理和他们的夫人下周去北京。", "corrected_sentence": "王经理和他的夫人下周去北京。", "error_description": "“他们”指多人，“王经理”是一个人，应说“他的夫人”，不能用“他们的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12a95067-003d-4c38-8b4f-542e1f4d664a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88232, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会议室里坐着三位夫人们。", "corrected_sentence": "会议室里坐着三位夫人。", "error_description": "“们”不能跟在数词和量词之后，“三位夫人”已表示复数，应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12a95067-003d-4c38-8b4f-542e1f4d664a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
