INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88240, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "有指挥作战才能的人。", "primary_collocate": null, "pronunciation": "jiàng cái", "ipa": "tɕjɑŋ˥˩ tsʰaɪ˧˥", "syllable_count": 2, "sentences": [{"text": "他有指挥的本事，是个将才。", "target_word": "将才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都觉得年轻的小王是将才。", "target_word": "将才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争时期，国家最缺的是将才。", "target_word": "将才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他指挥作战很聪明，是真正的将才。", "target_word": "将才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，这位古代的将才从没输过。", "target_word": "将才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将才不一定是最强壮的人。", "target_word": "将才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书写了很多古代将才的故事。", "target_word": "将才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王给将才送去了一匹好马。", "target_word": "将才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要成为将才，要先学会看地图。", "target_word": "将才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他指挥得很好，大家夸他是将才。", "target_word": "将才", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位将才", "label": "量词"}, {"form": "一个将才", "label": "量词"}], "register": "书面语", "sense_fingerprint": "有指挥作战才能的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476bafa-4a1b-4403-b163-44a07b2b0ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88240, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "将才", "is_correct": true, "explanation": "正确：将才指有指挥作战才能的人，与“有指挥的本事”相合。"}, {"text": "园丁", "is_correct": false, "explanation": "语义：“园丁”指照料花木的人，与“有指挥的本事”不相合。"}, {"text": "诗人", "is_correct": false, "explanation": "语义：“诗人”指写诗的人，与“指挥的本事”不相合。"}, {"text": "路灯", "is_correct": false, "explanation": "语义：“路灯”是器物，不能说人“有指挥的本事”，句子读不通。"}], "explanations": {"将才": "正确：将才指有指挥作战才能的人，与“有指挥的本事”相合。", "园丁": "语义：“园丁”指照料花木的人，与“有指挥的本事”不相合。", "诗人": "语义：“诗人”指写诗的人，与“指挥的本事”不相合。", "路灯": "语义：“路灯”是器物，不能说人“有指挥的本事”，句子读不通。"}, "sentence_index": 0, "correct_answer": "将才"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是球队的将才，很会训练队员。", "explanation": "这里应该用〈教练〉。将才指统兵作战的人，不用于体育队伍的训练者。"}, {"text": "他是一位很会做饭的将才，菜做得又快又好。", "explanation": "这里应该用〈厨师〉。将才指有指挥作战才能的人，不能用来指做饭的人。"}, {"text": "这把伞是个将才，遇到雨天很灵。", "explanation": "这里是把将才用成了“好用、顶用”的意思，但将才只指有指挥作战才能的人，不能用来指伞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b2f6d0-4009-4c46-a64f-4bf1effb2f7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88240, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "将才", "is_correct": true, "explanation": "正确：将才指有指挥作战才能的人，与“古代”“故事”的语境相合。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：古代没有电脑，“古代电脑的故事”与语境不合。"}, {"text": "手机", "is_correct": false, "explanation": "语义：古代没有手机，“古代手机的故事”与语境不合。"}, {"text": "飞机", "is_correct": false, "explanation": "语义：古代没有飞机，“古代飞机的故事”与语境不合。"}], "explanations": {"将才": "正确：将才指有指挥作战才能的人，与“古代”“故事”的语境相合。", "电脑": "语义：古代没有电脑，“古代电脑的故事”与语境不合。", "手机": "语义：古代没有手机，“古代手机的故事”与语境不合。", "飞机": "语义：古代没有飞机，“古代飞机的故事”与语境不合。"}, "sentence_index": 6, "correct_answer": "将才"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部电影的将才很会拍戏，大家都夸他。", "explanation": "这里应该用〈导演〉。将才专指指挥作战的人，不能用来指电影的导演。"}, {"text": "这位将才很会带乐队，大家都很佩服。", "explanation": "这里应该用〈指挥家〉。将才指统兵作战的人，不能用来指乐队的指挥。"}, {"text": "这间屋子是个将才，很会保暖。", "explanation": "这里是把将才用成了“本领高强、顶用”的意思，但将才只指有指挥作战才能的人，不能用来指房屋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b2f6d0-4009-4c46-a64f-4bf1effb2f7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88240, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从小就很有谋略，将来一定是只将才。", "corrected_sentence": "他从小就很有谋略，将来一定是个将才。", "error_description": "量词错误：将才指人，应用“个”或“位”，不能用“只”（“只”多用于动物）。应改为“是个将才”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b2f6d0-4009-4c46-a64f-4bf1effb2f7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88240, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他指挥作战很有一套，是一把难得的将才。", "corrected_sentence": "他指挥作战很有一套，是一位难得的将才。", "error_description": "量词错误：将才指人，应用“位”或“个”，不能用“把”。应改为“一位难得的将才”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b2f6d0-4009-4c46-a64f-4bf1effb2f7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
