INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88247, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "妻子是结了婚的女人,是她丈夫的家人。", "primary_collocate": null, "pronunciation": "qī zi", "ipa": "t͡ɕʰi˥ tsɨ", "syllable_count": 2, "sentences": [{"text": "他妻子是一位老师。", "target_word": "妻子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "张先生每天送妻子去上班。", "target_word": "妻子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妻子生病了，他请假在家照顾她。", "target_word": "妻子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位妻子对家人非常好。", "target_word": "妻子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我妻子喜欢看电影。", "target_word": "妻子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对妻子说了一声谢谢。", "target_word": "妻子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末，他陪妻子去超市买东西。", "target_word": "妻子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妻子笑着说：“你回来了。”", "target_word": "妻子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有一个很好的妻子。", "target_word": "妻子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的妻子来自南方。", "target_word": "妻子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "结了婚的女人，丈夫的家人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b9c7047-c41d-4dd6-a29e-9eca3dfeee0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88247, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "妻子", "is_correct": true, "explanation": "正确：妻子 qī zi，指结了婚的女性。"}, {"text": "棋子", "is_correct": false, "explanation": "qí（第二声）与 qī（第一声）声调不同，意思是棋子。"}, {"text": "起子", "is_correct": false, "explanation": "qǐ（第三声）与 qī（第一声）声调不同，意思是起子（开瓶器）。"}, {"text": "旗子", "is_correct": false, "explanation": "qí（第二声）与 qī（第一声）声调不同，意思是旗子。"}, {"text": "机子", "is_correct": false, "explanation": "jī 与 qī 声母不同（j 与 q），口语中指机器。"}], "explanations": {"妻子": "正确：妻子 qī zi，指结了婚的女性。", "棋子": "qí（第二声）与 qī（第一声）声调不同，意思是棋子。", "起子": "qǐ（第三声）与 qī（第一声）声调不同，意思是起子（开瓶器）。", "旗子": "qí（第二声）与 qī（第一声）声调不同，意思是旗子。", "机子": "jī 与 qī 声母不同（j 与 q），口语中指机器。"}, "sentence_index": null, "correct_answer": "妻子"}, "level_3": {"options": [{"text": "妻子", "is_correct": true, "explanation": "正确：“妻子”指丈夫的配偶，与句中的“他”相符，可以作“是一位老师”的主语。"}, {"text": "学校", "is_correct": false, "explanation": "搭配：“是一位老师”要求主语是人，不能用“学校”。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：鱼不能是老师，句意不通。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不能是老师，句意不通。"}], "explanations": {"妻子": "正确：“妻子”指丈夫的配偶，与句中的“他”相符，可以作“是一位老师”的主语。", "学校": "搭配：“是一位老师”要求主语是人，不能用“学校”。", "鱼": "语义：鱼不能是老师，句意不通。", "天空": "语义：天空不能是老师，句意不通。"}, "sentence_index": 0, "correct_answer": "妻子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我姐姐的妻子是我的哥哥。", "explanation": "这里应该用〈丈夫〉。“妻子”指女性配偶，“哥哥”是男性亲属，不能同时是“妻子”。"}, {"text": "这座房子是我朋友的妻子。", "explanation": "这里应该用〈人〉。“妻子”指人，不能用于房子。"}, {"text": "这位妻子是他的母亲。", "explanation": "这里应该用〈母亲〉。“妻子”指丈夫的配偶，不能同时是“他的母亲”；换成“母亲”即可。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e180dd-508b-4434-8fa4-cf412f9f8831') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88247, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "妻子", "is_correct": true, "explanation": "正确：“妻子”是可以被“陪”去超市的人，与“去超市买东西”相符。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不是可以被“陪”去超市的对象，句意不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能被“陪”去超市，句意不通。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“陪”的宾语应是人或有生命的对象，不能说“陪空气”。"}], "explanations": {"妻子": "正确：“妻子”是可以被“陪”去超市的人，与“去超市买东西”相符。", "汽车": "语义：汽车不是可以被“陪”去超市的对象，句意不通。", "桌子": "语义：桌子不能被“陪”去超市，句意不通。", "空气": "搭配：“陪”的宾语应是人或有生命的对象，不能说“陪空气”。"}, "sentence_index": 6, "correct_answer": "妻子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那只小狗是他的妻子。", "explanation": "这里应该用〈宠物〉。“妻子”指人，不能用来指小狗。"}, {"text": "她还没结婚，却是他的妻子。", "explanation": "这里应该用〈女朋友〉。“妻子”指已经结婚的女性，“还没结婚”的人应说“女朋友”。"}, {"text": "他的妻子只有三岁。", "explanation": "这里应该用〈孩子〉。“妻子”指成年的已婚女性，三岁的小孩应说“孩子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e180dd-508b-4434-8fa4-cf412f9f8831') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88247, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我朋友的一只妻子是律师。", "corrected_sentence": "我朋友的一位妻子是律师。", "error_description": "量词错误。“妻子”指人，应用“位”或“个”，写作“一位妻子”；“只”用于动物或成对的东西，不能用于指人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e180dd-508b-4434-8fa4-cf412f9f8831') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88247, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的妻子的喜欢养花。", "corrected_sentence": "我的妻子喜欢养花。", "error_description": "多写“的”。“我的妻子”已是完整主语，其后再加“的”接“喜欢”，句子不通；应删去多余的“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e180dd-508b-4434-8fa4-cf412f9f8831') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
