INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88255, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "接着是一件事做完了，下一件事马上来。", "primary_collocate": null, "pronunciation": "jiē zhe", "ipa": "tɕjɛ˥ ʈʂɤ", "syllable_count": 2, "sentences": [{"text": "他先吃了饭，接着去洗碗。", "target_word": "接着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师读了一遍，接着让我们读。", "target_word": "接着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下完雨，接着出了太阳。", "target_word": "接着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她唱完一首歌，接着又唱了一首。", "target_word": "接着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先打开书，接着写上你的名字。", "target_word": "接着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家鼓掌，接着他走上台。", "target_word": "接着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我洗了澡，接着就睡觉了。", "target_word": "接着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟做完作业，接着看电视。", "target_word": "接着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理说完话，接着大家开始工作。", "target_word": "接着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先放盐，接着放一点水。", "target_word": "接着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "接着：一件事之后紧跟着下一件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b9365df-7ca4-49ba-9257-3e6a2a4f3384') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88255, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "接着", "is_correct": true, "explanation": "正确。接着（jiē zhe）表示一件事之后紧接着下一件事。"}, {"text": "结着", "is_correct": false, "explanation": "jié zhe（第二声）与 jiē zhe（第一声）声调不同，意思是“结”，如“树上结着果子”。"}, {"text": "借着", "is_correct": false, "explanation": "jiè zhe（第四声）与 jiē zhe（第一声）声调不同，意思是“凭借”，如“借着这个机会”。"}, {"text": "接住", "is_correct": false, "explanation": "第二音节 zhù（第四声）与 zhe（轻声）声调不同，意思是“接下并拿住”。"}, {"text": "歇着", "is_correct": false, "explanation": "xiē 与 jiē 声母不同（x 与 j），意思是“休息”。"}], "explanations": {"接着": "正确。接着（jiē zhe）表示一件事之后紧接着下一件事。", "结着": "jié zhe（第二声）与 jiē zhe（第一声）声调不同，意思是“结”，如“树上结着果子”。", "借着": "jiè zhe（第四声）与 jiē zhe（第一声）声调不同，意思是“凭借”，如“借着这个机会”。", "接住": "第二音节 zhù（第四声）与 zhe（轻声）声调不同，意思是“接下并拿住”。", "歇着": "xiē 与 jiē 声母不同（x 与 j），意思是“休息”。"}, "sentence_index": null, "correct_answer": "接着"}, "level_3": {"options": [{"text": "接着", "is_correct": true, "explanation": "接着表示紧随其后，“他先吃了饭，接着去洗碗”语气顺畅。"}, {"text": "反而", "is_correct": false, "explanation": "语义：“反而”表示与预期相反，与先后相继的动作不合。"}, {"text": "却", "is_correct": false, "explanation": "语义：“却”表示转折，此处只是前后顺承，不应转折。"}, {"text": "竟", "is_correct": false, "explanation": "语域：“竟”属书面语，口语的先后叙述中一般不用。"}], "explanations": {"接着": "接着表示紧随其后，“他先吃了饭，接着去洗碗”语气顺畅。", "反而": "语义：“反而”表示与预期相反，与先后相继的动作不合。", "却": "语义：“却”表示转折，此处只是前后顺承，不应转折。", "竟": "语域：“竟”属书面语，口语的先后叙述中一般不用。"}, "sentence_index": 0, "correct_answer": "接着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一边看书，接着听音乐。", "explanation": "这里应该用〈同时〉。“接着”只表示先后相继，不能表示同时。"}, {"text": "我以为他走了，接着他还在屋里。", "explanation": "这里应该用〈原来〉。“原来”表示发现真相，“接着”只表示先后，不能表示“没想到”。"}, {"text": "我们接着先去买票，再进场。", "explanation": "这里应该用〈首先〉。“接着”表示紧随前一动作，没有前文时不能用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12a95067-003d-4c38-8b4f-542e1f4d664a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88255, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "接着", "is_correct": true, "explanation": "接着表示紧接着，“我洗了澡，接着就睡觉了”前后衔接自然。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”表示一贯如此，与“洗了澡”这一次的动作不合。"}, {"text": "一直", "is_correct": false, "explanation": "语义：“一直”表示持续，与“洗了澡”这一已完成的动作不合。"}, {"text": "仍", "is_correct": false, "explanation": "语域：“仍”是书面语，口语中“仍就睡觉”不自然。"}], "explanations": {"接着": "接着表示紧接着，“我洗了澡，接着就睡觉了”前后衔接自然。", "从来": "语义：“从来”表示一贯如此，与“洗了澡”这一次的动作不合。", "一直": "语义：“一直”表示持续，与“洗了澡”这一已完成的动作不合。", "仍": "语域：“仍”是书面语，口语中“仍就睡觉”不自然。"}, "sentence_index": 6, "correct_answer": "接着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大学毕业后过了十年，他接着去了美国。", "explanation": "这里应该用〈后来〉。“接着”表示紧接着，前后没有间隔；隔了很长时间要用“后来”。"}, {"text": "因为路上堵车很严重，接着他迟到了。", "explanation": "这里应该用〈所以〉。“因为”已引出原因，“接着”只表示先后，不能表示结果。"}, {"text": "虽然他很累，接着还在工作。", "explanation": "这里应该用〈却〉。“虽然”需要与“却”呼应，“接着”只表示先后，不能表示转折。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12a95067-003d-4c38-8b4f-542e1f4d664a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88255, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他吃完饭，接着了去超市。", "corrected_sentence": "他吃完饭，接着去超市。", "error_description": "错误形式：「他吃完饭，接着了去超市。」正确形式：「他吃完饭，接着去超市。」“接着”是副词，后面不能直接加“了”，“了”应放在动词之后或句末，这里多出的“了”使句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12a95067-003d-4c38-8b4f-542e1f4d664a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88255, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她写完信，接着的寄了出去。", "corrected_sentence": "她写完信，接着寄了出去。", "error_description": "“接着”是副词，后面不能加“的”，应说“接着寄了出去”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12a95067-003d-4c38-8b4f-542e1f4d664a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
