INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88262, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "依法取得执业资格,接受委托为当事人提供法律服务的专业人员。", "primary_collocate": null, "pronunciation": "lǜ shī", "ipa": "ly˥˩ ʂʅ˥", "syllable_count": 2, "sentences": [{"text": "律师接受了这家公司的委托。", "target_word": "律师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位律师为当事人写了一封信。", "target_word": "律师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是公司请来的律师。", "target_word": "律师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "律师在会议上讲了合同的问题。", "target_word": "律师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她做律师已经十年了。", "target_word": "律师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "律师要先看合同，再给意见。", "target_word": "律师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的律师正在检查这份合同。", "target_word": "律师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想打官司，你要先找律师。", "target_word": "律师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "律师说，这个合同有两个问题。", "target_word": "律师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位律师为客户提供法律服务。", "target_word": "律师", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "律師", "label": "繁体"}], "register": "中性", "sense_fingerprint": "律师|名词|依法执业、接受委托提供法律服务的专业人员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7b718ac-c4e5-459d-b8b0-a4e451916030') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88262, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "律师", "is_correct": true, "explanation": "正确：「律师」是依法执业、接受委托的专业人员，与「接受了委托」相符。"}, {"text": "桌子", "is_correct": false, "explanation": "配价：「接受委托」需要能接受的人或机构作主语，「桌子」不能。"}, {"text": "教室", "is_correct": false, "explanation": "语义：「教室」是场所，不是接受委托的人。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：「窗户」是物品，不能接受委托。"}], "explanations": {"律师": "正确：「律师」是依法执业、接受委托的专业人员，与「接受了委托」相符。", "桌子": "配价：「接受委托」需要能接受的人或机构作主语，「桌子」不能。", "教室": "语义：「教室」是场所，不是接受委托的人。", "窗户": "语义：「窗户」是物品，不能接受委托。"}, "sentence_index": 0, "correct_answer": "律师"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "律师依法提起了公诉。", "explanation": "这里应该用〈检察官〉。提起公诉是检察机关的职权，律师不能提起公诉。"}, {"text": "律师判了这起官司，当事人很满意。", "explanation": "这里应该用〈法官〉。律师替当事人辩护，不负责判案。"}, {"text": "律师给病人开了三天的药。", "explanation": "这里应该用〈医生〉。律师不开药，给病人开药的是医生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac88911d-0e7f-4e56-9f4e-77105f58f5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88262, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "律师", "is_correct": true, "explanation": "正确：「公司的律师」指公司聘请的法律人员，正在检查合同，句意相符。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师的工作与检查合同无关，句子不通。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：「厨房」是场所，不能检查合同。"}, {"text": "钢琴", "is_correct": false, "explanation": "配价：「检查」需要人作主语，「钢琴」不能。"}], "explanations": {"律师": "正确：「公司的律师」指公司聘请的法律人员，正在检查合同，句意相符。", "厨师": "语义：厨师的工作与检查合同无关，句子不通。", "厨房": "语义：「厨房」是场所，不能检查合同。", "钢琴": "配价：「检查」需要人作主语，「钢琴」不能。"}, "sentence_index": 6, "correct_answer": "律师"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "律师每天在饭店里炒菜。", "explanation": "这里应该用〈厨师〉。炒菜是厨师的工作，律师不做饭。"}, {"text": "律师带队训练了一个星期。", "explanation": "这里应该用〈教练〉。律师不带队训练运动员，带队训练的是教练。"}, {"text": "律师在路口指挥交通。", "explanation": "这里应该用〈警察〉。律师不指挥交通，指挥交通的是警察。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac88911d-0e7f-4e56-9f4e-77105f58f5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88262, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们请了三位律师们来处理这件事。", "corrected_sentence": "我们请了三位律师来处理这件事。", "error_description": "「律师们」不能与数词连用。「三位」后应直接用「律师」，写成「三位律师们」是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac88911d-0e7f-4e56-9f4e-77105f58f5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88262, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他请了一只律师，帮公司看合同。", "corrected_sentence": "他请了一位律师，帮公司看合同。", "error_description": "“一只律师”错误，“只”用于动物等，指人的“律师”应用“位”（或“个”）。应改为“一位律师”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac88911d-0e7f-4e56-9f4e-77105f58f5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88265, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d1a9c34-0345-46ff-8cb2-0810e91fa327') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88265, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d1a9c34-0345-46ff-8cb2-0810e91fa327') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88265, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "战斗就是两边的人拿着东西,互相打,想打赢对方。", "primary_collocate": null, "pronunciation": "zhàn dòu", "ipa": "ʈʂan˥˩ tou˥˩", "syllable_count": 2, "sentences": [{"text": "两队士兵在山上战斗了一整天。", "target_word": "战斗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们为了保护家人，勇敢地战斗。", "target_word": "战斗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵们拿着枪，在河边战斗。", "target_word": "战斗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个骑士拿着长剑，在城门前战斗。", "target_word": "战斗", "complexity_tier": "T3", "furigana": "liǎng gè qíshì názhe chángjiàn, zài chéngmén qián zhàndòu.", "sentence_source": "generated"}, {"text": "战士们已经战斗了三天三夜。", "target_word": "战斗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在雨中战斗，没有人后退。", "target_word": "战斗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了保护城市，大家一起战斗。", "target_word": "战斗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人来了，我们必须战斗。", "target_word": "战斗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游戏里，我们和怪物战斗了很久。", "target_word": "战斗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老兵说，他曾经在这里战斗过。", "target_word": "战斗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "战斗了", "label": "完成体"}, {"form": "战斗过", "label": "经历体"}, {"form": "战斗着", "label": "进行体"}], "register": "通用", "sense_fingerprint": "双方拿着武器互相打，想打赢对方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '410cbcc6-88e5-4dbf-9766-d970c97f3598') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88265, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "战斗", "is_correct": true, "explanation": "正确：战斗指双方持械对打，符合“两队士兵”的句意。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：山上没有水，士兵不能在山上游泳。"}, {"text": "进入", "is_correct": false, "explanation": "配价：“进入”后要带处所宾语，不能直接跟“一整天”。"}, {"text": "出生", "is_correct": false, "explanation": "语义：出生是一次性的事件，不能持续一整天。"}], "explanations": {"战斗": "正确：战斗指双方持械对打，符合“两队士兵”的句意。", "游泳": "语义：山上没有水，士兵不能在山上游泳。", "进入": "配价：“进入”后要带处所宾语，不能直接跟“一整天”。", "出生": "语义：出生是一次性的事件，不能持续一整天。"}, "sentence_index": 0, "correct_answer": "战斗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两个孩子在公园里跑步比赛，战斗得很激烈。", "explanation": "这里应该用〈比赛〉。战斗指双方拿着东西互相打，跑步比赛不是对打，不能用战斗。"}, {"text": "他坐在沙发上战斗了一下午，看完了一本书。", "explanation": "这里不能用“战斗”。战斗指双方对打、想打赢对方，安静地看书不是对抗，应说〈看书〉。"}, {"text": "两个小朋友在教室里战斗了一下午，都在认真地画画。", "explanation": "这里应该用〈画画〉。战斗指双方拿着东西互相打，认真画画不是对打，不能用战斗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d1a9c34-0345-46ff-8cb2-0810e91fa327') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88265, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "战斗", "is_correct": true, "explanation": "正确：为了保护城市，大家一起与敌人对抗，战斗合乎句意。"}, {"text": "投降", "is_correct": false, "explanation": "语义：投降与“为了保护城市”的目的正相反。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：为了保护城市，大家不会一起去睡觉。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：“为了保护城市”后接的行动应是防守或抗击，“散步”不能与之搭配。"}], "explanations": {"战斗": "正确：为了保护城市，大家一起与敌人对抗，战斗合乎句意。", "投降": "语义：投降与“为了保护城市”的目的正相反。", "睡觉": "语义：为了保护城市，大家不会一起去睡觉。", "散步": "搭配：“为了保护城市”后接的行动应是防守或抗击，“散步”不能与之搭配。"}, "sentence_index": 6, "correct_answer": "战斗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两人在屋里战斗了很久，一直在互相夸奖。", "explanation": "这里不能用“战斗”。战斗指双方拿着东西互相打，互相夸奖不是对打。"}, {"text": "我们在图书馆里战斗，安静地看书。", "explanation": "这里不能用“战斗”。战斗指双方对打、想打赢对方，安静看书是另一种活动，不是对抗。"}, {"text": "他们在咖啡馆里战斗，聊得很开心。", "explanation": "这里应该用〈聊天〉。战斗指武力对打，聊天不能说战斗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d1a9c34-0345-46ff-8cb2-0810e91fa327') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88265, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们在城墙下战斗了过一个晚上。", "corrected_sentence": "他们在城墙下战斗了一个晚上。", "error_description": "错误：动词后的“了”和“过”不能同时使用。正确：“他们在城墙下战斗了一个晚上。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d1a9c34-0345-46ff-8cb2-0810e91fa327') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88265, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "士兵们在河边战斗的很激烈。", "corrected_sentence": "士兵们在河边战斗得很激烈。", "error_description": "错误：战斗后的补语标记应用结构助词“得”，不能用“的”。正确：“士兵们在河边战斗得很激烈。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d1a9c34-0345-46ff-8cb2-0810e91fa327') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
