INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88266, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d1a9c34-0345-46ff-8cb2-0810e91fa327') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88266, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "敌对双方使用武力进行的对抗;也指为达到目的而进行斗争。", "primary_collocate": null, "pronunciation": "zhàn dòu", "ipa": "ʈʂan˥˩ tou˥˩", "syllable_count": 2, "sentences": [{"text": "这场战斗从早上打到了晚上。", "target_word": "战斗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战斗结束后，士兵们都很累。", "target_word": "战斗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那是一场非常激烈的战斗。", "target_word": "战斗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在战斗中受了伤。", "target_word": "战斗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战斗开始前，大家都很紧张。", "target_word": "战斗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生每天都在和疾病进行战斗。", "target_word": "战斗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一场没有枪声的战斗。", "target_word": "战斗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爷爷参加过很多次战斗。", "target_word": "战斗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战斗打响了，山上到处是枪声。", "target_word": "战斗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场战斗让我们学会了不放弃。", "target_word": "战斗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场战斗", "label": "量词"}, {"form": "一次战斗", "label": "量词"}], "register": "通用", "sense_fingerprint": "敌对双方用武力进行的一次对抗，也比喻为目标而斗争", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '410cbcc6-88e5-4dbf-9766-d970c97f3598') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88266, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "战斗", "is_correct": true, "explanation": "正确：战斗是一次具体的对抗，“这场”指一次战斗，“打到晚上”符合句意。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：“打到晚上”不能用于考试，考试应说“考”。"}, {"text": "婚礼", "is_correct": false, "explanation": "搭配：婚礼要说“办”，不能说“打”。"}, {"text": "会议", "is_correct": false, "explanation": "搭配：会议要说“开”，不说“打”。"}], "explanations": {"战斗": "正确：战斗是一次具体的对抗，“这场”指一次战斗，“打到晚上”符合句意。", "考试": "搭配：“打到晚上”不能用于考试，考试应说“考”。", "婚礼": "搭配：婚礼要说“办”，不能说“打”。", "会议": "搭配：会议要说“开”，不说“打”。"}, "sentence_index": 0, "correct_answer": "战斗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只战斗从早上打到了晚上。", "explanation": "这里应该用〈场〉。“战斗”用“场、次”计量，“只”通常用于动物，不能用来数战斗。"}, {"text": "两位好朋友在公园里战斗，一起去喝了奶茶。", "explanation": "这里应该用〈玩〉。战斗指敌对双方的对抗，好朋友之间友好玩耍不能说战斗。"}, {"text": "这张战斗很精彩。", "explanation": "这里应该用〈场〉。“张”用于平面的东西，不能用来数战斗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d1a9c34-0345-46ff-8cb2-0810e91fa327') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88266, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "战斗", "is_correct": true, "explanation": "正确：“没有枪声”的对抗正是一场无声的战斗，符合句意。"}, {"text": "晚会", "is_correct": false, "explanation": "语义：晚会是欢聚活动，不是双方对抗，与“战斗”的所指不符。"}, {"text": "派对", "is_correct": false, "explanation": "语义：派对是聚会，与句中指的对抗不相符。"}, {"text": "地震", "is_correct": false, "explanation": "搭配：“没有枪声”多用于战事或对抗，地震不能这样描述。"}], "explanations": {"战斗": "正确：“没有枪声”的对抗正是一场无声的战斗，符合句意。", "晚会": "语义：晚会是欢聚活动，不是双方对抗，与“战斗”的所指不符。", "派对": "语义：派对是聚会，与句中指的对抗不相符。", "地震": "搭配：“没有枪声”多用于战事或对抗，地震不能这样描述。"}, "sentence_index": 6, "correct_answer": "战斗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这根战斗很激烈。", "explanation": "这里应该用〈场〉。“根”用于细长的东西，战斗应用“场”计量。"}, {"text": "这场战斗从早上睡到了晚上。", "explanation": "这里不能用“战斗”。战斗指敌对双方的对抗，“睡到晚上”说的是睡觉，属于另一种意思。"}, {"text": "这首战斗很动听。", "explanation": "这里应该用〈场〉。“首”多用于诗歌、歌曲，不能用来数战斗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d1a9c34-0345-46ff-8cb2-0810e91fa327') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88266, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只很大的战斗已经结束了。", "corrected_sentence": "一场很大的战斗已经结束了。", "error_description": "错误：量词用错。“战斗”应用“场”计量，“只”用于动物。正确：“一场很大的战斗已经结束了。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d1a9c34-0345-46ff-8cb2-0810e91fa327') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88266, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在战斗了中失去了一位朋友。", "corrected_sentence": "她在战斗中失去了一位朋友。", "error_description": "错误：“战斗”后不能加“了”再接“中”，“在……中”的结构中不能插入“了”。正确：“她在战斗中失去了一位朋友。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d1a9c34-0345-46ff-8cb2-0810e91fa327') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
