INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88268, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "介词，表示动作的方向，对着；向。", "primary_collocate": null, "pronunciation": "cháo", "ipa": "ʈʂʰɑʊ̯˧˥", "syllable_count": 1, "sentences": [{"text": "他朝我笑了笑。", "target_word": "朝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请朝前走，不要回头。", "target_word": "朝", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小狗朝门口跑去。", "target_word": "朝", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她朝老师点了点头。", "target_word": "朝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子朝妈妈跑去，很高兴。", "target_word": "朝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他朝窗外看了一会儿。", "target_word": "朝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师朝我们走来，笑着说话。", "target_word": "朝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生气地朝我喊了一声。", "target_word": "朝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "汽车朝北边开去了。", "target_word": "朝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她朝大家挥着手，说再见。", "target_word": "朝", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "朝着", "label": "带体标形式"}], "register": "中性", "sense_fingerprint": "介词：朝+对象或方向+动词，表示动作面向某个方向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e0c221-b8bd-4749-8a15-ebb972445d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88268, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "朝", "is_correct": true, "explanation": "正确答案：朝，表示动作的方向，对着；向。"}, {"text": "抄", "is_correct": false, "explanation": "chāo（第一声）与 cháo 的声调不同，意思是抄写。"}, {"text": "炒", "is_correct": false, "explanation": "chǎo（第三声）与 cháo 的声调不同，意思是翻炒。"}, {"text": "长", "is_correct": false, "explanation": "cháng 与 cháo 的韵母不同（ang 与 ao），意思是长短的长。"}], "explanations": {"朝": "正确答案：朝，表示动作的方向，对着；向。", "抄": "chāo（第一声）与 cháo 的声调不同，意思是抄写。", "炒": "chǎo（第三声）与 cháo 的声调不同，意思是翻炒。", "长": "cháng 与 cháo 的韵母不同（ang 与 ao），意思是长短的长。"}, "sentence_index": null, "correct_answer": "朝"}, "level_3": {"options": [{"text": "朝", "is_correct": true, "explanation": "正确：“朝我”表示笑的方向，符合语境。"}, {"text": "从", "is_correct": false, "explanation": "语义：“从”表示起点，与“笑”的对象不符。"}, {"text": "按", "is_correct": false, "explanation": "搭配：“按”后面接依据或标准，不接“我”作笑的对象。"}, {"text": "在", "is_correct": false, "explanation": "配价：“在”引出动作发生的场所，“我”不是笑的场所。"}], "explanations": {"朝": "正确：“朝我”表示笑的方向，符合语境。", "从": "语义：“从”表示起点，与“笑”的对象不符。", "按": "搭配：“按”后面接依据或标准，不接“我”作笑的对象。", "在": "配价：“在”引出动作发生的场所，“我”不是笑的场所。"}, "sentence_index": 0, "correct_answer": "朝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书朝我很重要。", "explanation": "这里应该用〈对〉。“对”可以表示对待，如“对我很重要”，“朝”不能表示对事物的态度。"}, {"text": "他朝我很好。", "explanation": "这里应该用〈对〉。“对”可以表示对待，如“对我很好”，“朝”不表示态度。"}, {"text": "他朝我买了一本书。", "explanation": "这里应该用〈给〉。“给”引出受益的人，“朝”不能引出受益的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e2401e-2f59-4ebb-9d07-980fe50a58c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88268, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "朝", "is_correct": true, "explanation": "正确答案：朝，表示动作的方向，对着；向。"}, {"text": "着", "is_correct": false, "explanation": "zháo 与 cháo 的声母不同（zh 与 ch），意思是着急。"}, {"text": "柴", "is_correct": false, "explanation": "chái 与 cháo 的韵母不同（ai 与 ao），意思是柴火。"}, {"text": "槽", "is_correct": false, "explanation": "cáo 与 cháo 的声母不同（c 与 ch），意思是水槽。"}, {"text": "绸", "is_correct": false, "explanation": "chóu 与 cháo 的韵母不同（ou 与 ao），意思是丝绸。"}], "explanations": {"朝": "正确答案：朝，表示动作的方向，对着；向。", "着": "zháo 与 cháo 的声母不同（zh 与 ch），意思是着急。", "柴": "chái 与 cháo 的韵母不同（ai 与 ao），意思是柴火。", "槽": "cáo 与 cháo 的声母不同（c 与 ch），意思是水槽。", "绸": "chóu 与 cháo 的韵母不同（ou 与 ao），意思是丝绸。"}, "sentence_index": null, "correct_answer": "朝"}, "level_3": {"options": [{"text": "朝", "is_correct": true, "explanation": "正确：“朝我们走来”表示走的方向，符合语境。"}, {"text": "给", "is_correct": false, "explanation": "语义：“给”表示给予，不表示走的方向。"}, {"text": "替", "is_correct": false, "explanation": "配价：“替”后面接替人做事的对象，不能与“走来”搭配。"}, {"text": "把", "is_correct": false, "explanation": "语义：“把”引出被处置的对象，与“走来”的方向不合。"}], "explanations": {"朝": "正确：“朝我们走来”表示走的方向，符合语境。", "给": "语义：“给”表示给予，不表示走的方向。", "替": "配价：“替”后面接替人做事的对象，不能与“走来”搭配。", "把": "语义：“把”引出被处置的对象，与“走来”的方向不合。"}, "sentence_index": 6, "correct_answer": "朝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她朝我们打扫了教室。", "explanation": "这里应该用〈替〉。“替”表示替别人做事，“朝”只表示动作的方向。"}, {"text": "她朝大家做了饭。", "explanation": "这里应该用〈为〉。“为”表示为了某人做某事，“朝”不能这样用。"}, {"text": "我家朝公园很近，每天傍晚都去散步。", "explanation": "这里应该用〈离〉。“离”表示两地之间的距离，“朝”只表示动作的方向，不能表示距离。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e2401e-2f59-4ebb-9d07-980fe50a58c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88268, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小猫朝走去了。", "corrected_sentence": "小猫朝门口走去了。", "error_description": "错误：介词“朝”后面漏掉了方向宾语“门口”，“朝走去”不成句。应说“小猫朝门口走去了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e2401e-2f59-4ebb-9d07-980fe50a58c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88268, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "球朝飞过去了。", "corrected_sentence": "球朝他飞过去了。", "error_description": "错误：介词“朝”后面漏掉了方向宾语“他”，“朝飞过去”不成句。应说“球朝他飞过去了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e2401e-2f59-4ebb-9d07-980fe50a58c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88269, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "坚持", "is_correct": true, "explanation": "正确：“坚持”与“放弃”构成反义，指一直做下去，与“放弃了画画”的意思相反。"}, {"text": "散步", "is_correct": false, "explanation": "无反义关系：“散步”指慢慢走路，与停止学画没有对立。"}, {"text": "烧", "is_correct": false, "explanation": "无反义关系：“烧”指加热或燃烧，与放弃学习没有对立。"}, {"text": "翻译", "is_correct": false, "explanation": "无反义关系：“翻译”指转换语言，与放弃学习不构成对立。"}], "correct_answer": "坚持", "explanations": {"坚持": "正确：“坚持”与“放弃”构成反义，指一直做下去，与“放弃了画画”的意思相反。", "散步": "无反义关系：“散步”指慢慢走路，与停止学画没有对立。", "烧": "无反义关系：“烧”指加热或燃烧，与放弃学习没有对立。", "翻译": "无反义关系：“翻译”指转换语言，与放弃学习不构成对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b2f6d0-4009-4c46-a64f-4bf1effb2f7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88269, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "坚持", "is_correct": true, "explanation": "正确：“坚持”与“放弃”构成反义，指不停地做下去，与“不要放弃学中文”的意思相反。"}, {"text": "查询", "is_correct": false, "explanation": "无反义关系：“查询”指查找信息，与放弃学习没有对立。"}, {"text": "打印", "is_correct": false, "explanation": "无反义关系：“打印”指把文件印出来，与放弃学习不构成对立。"}, {"text": "打扫", "is_correct": false, "explanation": "无反义关系：“打扫”指清理环境，与放弃学习没有对立。"}], "correct_answer": "坚持", "explanations": {"坚持": "正确：“坚持”与“放弃”构成反义，指不停地做下去，与“不要放弃学中文”的意思相反。", "查询": "无反义关系：“查询”指查找信息，与放弃学习没有对立。", "打印": "无反义关系：“打印”指把文件印出来，与放弃学习不构成对立。", "打扫": "无反义关系：“打扫”指清理环境，与放弃学习没有对立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b2f6d0-4009-4c46-a64f-4bf1effb2f7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88269, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "放弃就是不要了,不再做了。", "primary_collocate": null, "pronunciation": "fàng qì", "ipa": "fɑŋ˥˩ tɕʰi˥˩", "syllable_count": 2, "sentences": [{"text": "学了一年，他就放弃了画画。", "target_word": "放弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏太难，我想放弃。", "target_word": "放弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别放弃，再试一次。", "target_word": "放弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跑到一半就放弃了。", "target_word": "放弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟拼了一半就放弃了那个拼图。", "target_word": "放弃", "complexity_tier": "T3", "furigana": "dì dì pīn le yí bàn jiù fàng qì le nà ge pīn tú", "sentence_source": "generated"}, {"text": "她学钢琴学了三天就放弃了。", "target_word": "放弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然很累，但是我不会放弃。", "target_word": "放弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天考试，我决定放弃看电影。", "target_word": "放弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说做事不能轻易放弃。", "target_word": "放弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈劝我不要放弃学中文。", "target_word": "放弃", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "放弃了", "label": "体标"}, {"form": "放弃过", "label": "体标"}], "register": "中性", "sense_fingerprint": "不要了，不再做了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476bafa-4a1b-4403-b163-44a07b2b0ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88269, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "放弃", "is_correct": true, "explanation": "正确：“放弃”指不再做下去，与“学了一年…就”的语境相合。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”不能与“画画”构成动宾，句子读不通。"}, {"text": "拥有", "is_correct": false, "explanation": "搭配：“拥有”一般不说“拥有画画”，搭配不当。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”的对象是器物，不能用于“画画”。"}], "explanations": {"放弃": "正确：“放弃”指不再做下去，与“学了一年…就”的语境相合。", "吃": "语义：“吃”不能与“画画”构成动宾，句子读不通。", "拥有": "搭配：“拥有”一般不说“拥有画画”，搭配不当。", "修": "语义：“修”的对象是器物，不能用于“画画”。"}, "sentence_index": 0, "correct_answer": "放弃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把脏衣服放弃了，然后去洗澡。", "explanation": "这里应该用〈扔掉〉。放弃指不再做下去，不用于丢弃具体的物品。"}, {"text": "妈妈把烂掉的水果放弃了。", "explanation": "这里应该用〈丢掉〉。放弃用于计划或做法，不用于丢弃食物。"}, {"text": "他放弃了一整个夏天，去了北方。", "explanation": "这里是把放弃用成了“离开”的意思，但放弃指不再做下去，不用于指一段时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b2f6d0-4009-4c46-a64f-4bf1effb2f7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88269, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放弃", "is_correct": true, "explanation": "正确：“放弃”指不再坚持，与“虽然很累，但是”的语境相合。"}, {"text": "讨论", "is_correct": false, "explanation": "语义：“讨论”需要议题，这里没有可讨论的对象，句子读不通。"}, {"text": "统计", "is_correct": false, "explanation": "语义：“统计”指计数，与“虽然很累”的语境不相合。"}, {"text": "吟诗", "is_correct": false, "explanation": "语义：“吟诗”指诵读诗歌，与“虽然很累，但是我不会”的语境不相合。"}], "explanations": {"放弃": "正确：“放弃”指不再坚持，与“虽然很累，但是”的语境相合。", "讨论": "语义：“讨论”需要议题，这里没有可讨论的对象，句子读不通。", "统计": "语义：“统计”指计数，与“虽然很累”的语境不相合。", "吟诗": "语义：“吟诗”指诵读诗歌，与“虽然很累，但是我不会”的语境不相合。"}, "sentence_index": 6, "correct_answer": "放弃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把旧书放弃了，换了点钱。", "explanation": "这里应该用〈卖〉。放弃指舍弃权利或计划，不用于卖书。"}, {"text": "妹妹放弃了那只打碎的杯子，准备去买新的。", "explanation": "这里应该用〈处理掉〉。放弃指不再做下去，不用于处理打碎的杯子。"}, {"text": "爸爸放弃了那把用坏的椅子，准备换一把新的。", "explanation": "这里应该用〈换掉〉。放弃指不再做下去，不用于更换家具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b2f6d0-4009-4c46-a64f-4bf1effb2f7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88269, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他学了一年，最后还是把放弃了画画。", "corrected_sentence": "他学了一年，最后还是放弃了画画。", "error_description": "把字句错误：“放弃”后直接带宾语，前面不能加“把”。应改为“放弃了画画”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b2f6d0-4009-4c46-a64f-4bf1effb2f7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88269, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他学了几个月，觉得太难，但我劝他不要放弃了学习。", "corrected_sentence": "他学了几个月，觉得太难，但我劝他不要放弃学习。", "error_description": "“了”用错：“不要”表示劝阻，“放弃”后面不能直接加“了”。应改为“不要放弃学习”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b2f6d0-4009-4c46-a64f-4bf1effb2f7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88270, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "坚持", "is_correct": true, "explanation": "正确：“坚持”与“放弃”构成反义，指不停地做下去，与“放弃了…机会”的意思相反。"}, {"text": "参观", "is_correct": false, "explanation": "无反义关系：“参观”指到某地去看，与舍弃权利或计划没有对立。"}, {"text": "购买", "is_correct": false, "explanation": "无反义关系：“购买”指付钱获得物品，与舍弃机会没有对立。"}, {"text": "讨论", "is_correct": false, "explanation": "无反义关系：“讨论”指交流意见，与舍弃机会不构成对立。"}], "correct_answer": "坚持", "explanations": {"坚持": "正确：“坚持”与“放弃”构成反义，指不停地做下去，与“放弃了…机会”的意思相反。", "参观": "无反义关系：“参观”指到某地去看，与舍弃权利或计划没有对立。", "购买": "无反义关系：“购买”指付钱获得物品，与舍弃机会没有对立。", "讨论": "无反义关系：“讨论”指交流意见，与舍弃机会不构成对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b2f6d0-4009-4c46-a64f-4bf1effb2f7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88270, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "坚持", "is_correct": true, "explanation": "正确：“坚持”与“放弃”构成反义，指不停地做下去，与“放弃了…”的意思相反。"}, {"text": "旅行", "is_correct": false, "explanation": "无反义关系：“旅行”指出外游览，与舍弃权利或计划没有对立。"}, {"text": "搬运", "is_correct": false, "explanation": "无反义关系：“搬运”指把东西从一处移到另一处，与舍弃计划没有对立。"}, {"text": "记录", "is_correct": false, "explanation": "无反义关系：“记录”指把内容写下来，与舍弃权利不构成对立。"}], "correct_answer": "坚持", "explanations": {"坚持": "正确：“坚持”与“放弃”构成反义，指不停地做下去，与“放弃了…”的意思相反。", "旅行": "无反义关系：“旅行”指出外游览，与舍弃权利或计划没有对立。", "搬运": "无反义关系：“搬运”指把东西从一处移到另一处，与舍弃计划没有对立。", "记录": "无反义关系：“记录”指把内容写下来，与舍弃权利不构成对立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b2f6d0-4009-4c46-a64f-4bf1effb2f7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88270, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "舍弃原有的权利、主张或打算,不再继续。", "primary_collocate": null, "pronunciation": "fàng qì", "ipa": "fɑŋ˥˩ tɕʰi˥˩", "syllable_count": 2, "sentences": [{"text": "他放弃了去国外工作的打算。", "target_word": "放弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为生病，她放弃了比赛。", "target_word": "放弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不要放弃自己的想法。", "target_word": "放弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他放弃了留在大城市的机会。", "target_word": "放弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李放弃了考研究生的计划。", "target_word": "放弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司放弃了原来的方案。", "target_word": "放弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能放弃自己的权利。", "target_word": "放弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想了很久，还是放弃了这笔钱。", "target_word": "放弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，大家放弃了爬山的计划。", "target_word": "放弃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她放弃过出国的机会，现在有点后悔。", "target_word": "放弃", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "放弃了", "label": "体标"}, {"form": "放弃过", "label": "体标"}], "register": "中性", "sense_fingerprint": "舍弃原有的权利、想法或计划，不再继续", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5476bafa-4a1b-4403-b163-44a07b2b0ef2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88270, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "放弃", "is_correct": true, "explanation": "正确：“放弃”指舍弃打算，与“去国外工作的打算”相合。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”不能与“打算”搭配，句子读不通。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”不能与“打算”搭配，句子读不通。"}, {"text": "爬", "is_correct": false, "explanation": "语义：“爬”的对象是高处或地面，与“打算”不相合。"}], "explanations": {"放弃": "正确：“放弃”指舍弃打算，与“去国外工作的打算”相合。", "吃": "语义：“吃”不能与“打算”搭配，句子读不通。", "喝": "语义：“喝”不能与“打算”搭配，句子读不通。", "爬": "语义：“爬”的对象是高处或地面，与“打算”不相合。"}, "sentence_index": 0, "correct_answer": "放弃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把门口的旧椅子放弃了。", "explanation": "这里应该用〈扔掉〉。放弃指舍弃权利、想法或计划，不能用来说丢掉具体的物件。"}, {"text": "妈妈把发霉的饼干放弃了。", "explanation": "这里应该用〈丢〉。放弃用于权利、想法或计划，不能用来说丢弃食物。"}, {"text": "他放弃了春天，去了南方。", "explanation": "这里是把放弃用成了“离开”的意思，但放弃指舍弃权利、主张或打算，不能用于一个季节。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b2f6d0-4009-4c46-a64f-4bf1effb2f7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88270, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "放弃", "is_correct": true, "explanation": "正确：“放弃”指舍弃权利，与“我们不能…自己的权利”的语境相合。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”的对象是食物，不能用在“权利”上。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”不能与“权利”搭配，句子读不通。"}, {"text": "装", "is_correct": false, "explanation": "搭配：“装”指假装，不能说“装自己的权利”。"}], "explanations": {"放弃": "正确：“放弃”指舍弃权利，与“我们不能…自己的权利”的语境相合。", "煮": "语义：“煮”的对象是食物，不能用在“权利”上。", "唱": "语义：“唱”不能与“权利”搭配，句子读不通。", "装": "搭配：“装”指假装，不能说“装自己的权利”。"}, "sentence_index": 6, "correct_answer": "放弃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把旧车放弃了，换了辆新车。", "explanation": "这里应该用〈卖掉〉。放弃指舍弃权利或计划，不用于卖东西。"}, {"text": "哥哥放弃了那只打碎的花瓶，准备去买新的。", "explanation": "这里应该用〈处理掉〉。放弃指舍弃权利、主张或打算，不用于处理打碎的花瓶。"}, {"text": "姐姐放弃了那张旧床垫，准备换一张新的。", "explanation": "这里应该用〈换掉〉。放弃指舍弃权利、主张或打算，不用于更换家具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b2f6d0-4009-4c46-a64f-4bf1effb2f7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88270, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他因为家里有事，把放弃了这次出差。", "corrected_sentence": "他因为家里有事，放弃了这次出差。", "error_description": "把字句错误：“放弃”后直接带宾语，前面不能加“把”。应改为“放弃了这次出差”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b2f6d0-4009-4c46-a64f-4bf1effb2f7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88270, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个计划很难，但我不会放弃了。", "corrected_sentence": "这个计划很难，但我不会放弃。", "error_description": "时态错误：“不会放弃”是表示将来或意愿的否定，后面不能加“了”。应改为“我不会放弃”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81b2f6d0-4009-4c46-a64f-4bf1effb2f7d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
