INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88278, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容词，好；强。", "primary_collocate": null, "pronunciation": "bàng", "ipa": "pɑŋ˥˩", "syllable_count": 1, "sentences": [{"text": "他游泳游得很棒。", "target_word": "棒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说我写的字很棒。", "target_word": "棒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子学习特别棒。", "target_word": "棒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们的球队真棒！", "target_word": "棒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的钢琴弹得很棒。", "target_word": "棒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她唱的歌太棒了。", "target_word": "棒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的篮球打得比我更棒。", "target_word": "棒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个医生很棒，大家都相信他。", "target_word": "棒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的比赛太棒了。", "target_word": "棒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的英语棒得让我吃惊。", "target_word": "棒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "好；强，水平高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78bd22d5-58b2-46ac-bd58-f8a4351aa496') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88278, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "棒", "is_correct": true, "explanation": "正确答案。棒 bàng 意思是好、强，水平高。"}, {"text": "帮", "is_correct": false, "explanation": "bāng（第一声）与 bàng（第四声）声调不同，意思是帮助。"}, {"text": "胖", "is_correct": false, "explanation": "pàng（第四声）与 bàng 声母不同（p 与 b），意思是胖。"}, {"text": "榜", "is_correct": false, "explanation": "bǎng（第三声）与 bàng 声调不同，意思是榜样或名单。"}], "explanations": {"棒": "正确答案。棒 bàng 意思是好、强，水平高。", "帮": "bāng（第一声）与 bàng（第四声）声调不同，意思是帮助。", "胖": "pàng（第四声）与 bàng 声母不同（p 与 b），意思是胖。", "榜": "bǎng（第三声）与 bàng 声调不同，意思是榜样或名单。"}, "sentence_index": null, "correct_answer": "棒"}, "level_3": {"options": [{"text": "棒", "is_correct": true, "explanation": "正确。“游得”后接补语“很棒”，表示游得好。"}, {"text": "硬", "is_correct": false, "explanation": "语义：“硬”指质地坚实，不能用来形容游泳的水平。"}, {"text": "亮", "is_correct": false, "explanation": "语义：“亮”指光线或声音，不能说明游泳的水平。"}, {"text": "厚", "is_correct": false, "explanation": "语义：“厚”指物体的厚度，与游泳的水平无关。"}], "explanations": {"棒": "正确。“游得”后接补语“很棒”，表示游得好。", "硬": "语义：“硬”指质地坚实，不能用来形容游泳的水平。", "亮": "语义：“亮”指光线或声音，不能说明游泳的水平。", "厚": "语义：“厚”指物体的厚度，与游泳的水平无关。"}, "sentence_index": 0, "correct_answer": "棒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他疼得棒，额头直冒汗。", "explanation": "这里应该用〈厉害〉。棒是称赞用语，表示好或强，不能形容疼痛的程度；疼得剧烈要用“厉害”。"}, {"text": "这次事故很棒，有三个人受伤。", "explanation": "这里应该用〈严重〉。棒用于称赞，不能形容事故的危害程度；描述危害大要用“严重”。"}, {"text": "地震很棒，房子倒了很多。", "explanation": "这里应该用〈可怕〉。棒表示好、强，不能形容灾难令人害怕；描述令人害怕的灾难要用“可怕”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bdfd8fd-3c6f-42b0-8fce-715d5e9632d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88278, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "棒", "is_correct": true, "explanation": "正确答案。棒 bàng 意思是好、强，水平高。"}, {"text": "报", "is_correct": false, "explanation": "bào（第四声）与 bàng 韵母不同（ao 与 ang），意思是报纸或报告。"}, {"text": "办", "is_correct": false, "explanation": "bàn（第四声）与 bàng 韵母不同（an 与 ang），意思是办理。"}, {"text": "膀", "is_correct": false, "explanation": "bǎng（第三声）与 bàng 只差声调，意思是翅膀。"}, {"text": "蹦", "is_correct": false, "explanation": "bèng（第四声）与 bàng 韵母不同（eng 与 ang），意思是跳跃。"}], "explanations": {"棒": "正确答案。棒 bàng 意思是好、强，水平高。", "报": "bào（第四声）与 bàng 韵母不同（ao 与 ang），意思是报纸或报告。", "办": "bàn（第四声）与 bàng 韵母不同（an 与 ang），意思是办理。", "膀": "bǎng（第三声）与 bàng 只差声调，意思是翅膀。", "蹦": "bèng（第四声）与 bàng 韵母不同（eng 与 ang），意思是跳跃。"}, "sentence_index": null, "correct_answer": "棒"}, "level_3": {"options": [{"text": "棒", "is_correct": true, "explanation": "正确。棒表示水平高；“更”表示比较，棒本身不含比较义。"}, {"text": "脆", "is_correct": false, "explanation": "语义：“脆”形容食物或物体易断的特点，不能用来比较打篮球的水平。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”指味道，不能用来比较打篮球的水平。"}, {"text": "圆", "is_correct": false, "explanation": "语义：“圆”指形状，与打篮球的水平高低无关。"}], "explanations": {"棒": "正确。棒表示水平高；“更”表示比较，棒本身不含比较义。", "脆": "语义：“脆”形容食物或物体易断的特点，不能用来比较打篮球的水平。", "甜": "语义：“甜”指味道，不能用来比较打篮球的水平。", "圆": "语义：“圆”指形状，与打篮球的水平高低无关。"}, "sentence_index": 6, "correct_answer": "棒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他咳嗽得很棒，整夜睡不着。", "explanation": "这里应该用〈剧烈〉。棒是称赞用语，不能形容咳嗽等症状的程度；描述症状强烈要用“剧烈”。"}, {"text": "伤口很棒，需要消毒。", "explanation": "这里应该用〈红肿〉。棒是称赞用语，不能用来描述伤口。"}, {"text": "他这次输得很棒。", "explanation": "这里应该用〈惨〉。棒表示称赞，不能描述失败的结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bdfd8fd-3c6f-42b0-8fce-715d5e9632d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88278, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她唱歌唱很棒。", "corrected_sentence": "她唱歌唱得很棒。", "error_description": "错误：动词后带程度补语时漏掉“得”。正确：应说“唱得很棒”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bdfd8fd-3c6f-42b0-8fce-715d5e9632d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88278, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的英语真很棒。", "corrected_sentence": "他的英语真棒。", "error_description": "错误：“真”和“棒”之间多出了“很”。正确：形容词前已有“真”表示程度，不再加“很”，应说“真棒”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bdfd8fd-3c6f-42b0-8fce-715d5e9632d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
