INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88279, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4458b0e9-2ef5-428a-8c1e-3b89dfc44717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88279, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "父母是爸爸和妈妈,他们生下我们,养大我们。", "primary_collocate": null, "pronunciation": "fù mǔ", "ipa": "fu˥˩ mu˨˩˦", "syllable_count": 2, "sentences": [{"text": "我的父母都很爱我。", "target_word": "父母", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母每天早上六点起床。", "target_word": "父母", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我常回家看父母。", "target_word": "父母", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母养大了我们三个孩子。", "target_word": "父母", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把这个好消息告诉父母。", "target_word": "父母", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的父母住在南京。", "target_word": "父母", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母辛苦工作，是为了让我们好好学习。", "target_word": "父母", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子生病时，父母特别着急。", "target_word": "父母", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谢谢父母给我买的新书包。", "target_word": "父母", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我父母每年都带我去旅游。", "target_word": "父母", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "父母亲", "label": "复合词"}, {"form": "祖父母", "label": "复合词"}], "register": "中性", "sense_fingerprint": "生下并养大自己的爸爸和妈妈", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b14ed482-1297-4790-a8d0-57fd5bb1c971') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88279, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "父母", "is_correct": true, "explanation": "正确：“父母”指爸爸和妈妈，与“都”搭配，表示两人都爱我。"}, {"text": "父亲", "is_correct": false, "explanation": "搭配：“都”要求复数，只指父亲一人时不能用“都”。"}, {"text": "树", "is_correct": false, "explanation": "语义：树不会爱人，句子说的是有感情的人。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不会爱我，句子说的是有感情的人。"}], "explanations": {"父母": "正确：“父母”指爸爸和妈妈，与“都”搭配，表示两人都爱我。", "父亲": "搭配：“都”要求复数，只指父亲一人时不能用“都”。", "树": "语义：树不会爱人，句子说的是有感情的人。", "书": "语义：书不会爱我，句子说的是有感情的人。"}, "sentence_index": 0, "correct_answer": "父母"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天在车站遇到了一个父母。", "explanation": "这里应该用〈对〉。父母指两个人，量词要用“对”，说“一对父母”。"}, {"text": "我爷爷奶奶是我的父母。", "explanation": "这里应该用〈祖父母〉。“父母”指生下我们、养大我们的爸爸和妈妈，爷爷奶奶是父母的父母，不能说是“父母”。"}, {"text": "我的同学是我的父母。", "explanation": "这里应该用〈朋友〉。“父母”指生下我们、养大我们的爸爸和妈妈，同学不能说是父母，只能说是同学或朋友。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4458b0e9-2ef5-428a-8c1e-3b89dfc44717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88279, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "父母", "is_correct": true, "explanation": "正确：父母辛苦工作，是为了孩子好好学习，符合句意。"}, {"text": "花", "is_correct": false, "explanation": "语义：花不会辛苦工作，也不会为了让我们学习而工作。"}, {"text": "水", "is_correct": false, "explanation": "语义：水不会辛苦工作，句子说的是有感情的人。"}, {"text": "机器", "is_correct": false, "explanation": "搭配：“辛苦”一般用于人，不说机器辛苦，也不说机器为了让我们学习而工作。"}], "explanations": {"父母": "正确：父母辛苦工作，是为了孩子好好学习，符合句意。", "花": "语义：花不会辛苦工作，也不会为了让我们学习而工作。", "水": "语义：水不会辛苦工作，句子说的是有感情的人。", "机器": "搭配：“辛苦”一般用于人，不说机器辛苦，也不说机器为了让我们学习而工作。"}, "sentence_index": 6, "correct_answer": "父母"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们小区的父母每天都打太极拳。", "explanation": "这里应该用〈长辈〉。“父母”只指孩子自己的爸爸和妈妈，泛指小区里的老年人要用“长辈”。"}, {"text": "学校的父母都很用功。", "explanation": "这里应该用〈学生〉。“父母”指生下、养大孩子的爸爸和妈妈，不能指学生，学生用功要说“学生”。"}, {"text": "他的父母还在上幼儿园。", "explanation": "这里应该用〈孩子〉。“父母”指爸爸和妈妈，不能指还在上幼儿园的小孩，这里要用“孩子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4458b0e9-2ef5-428a-8c1e-3b89dfc44717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88279, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我一个父母都是工人。", "corrected_sentence": "我父母都是工人。", "error_description": "错误：“父母”前多加了数量词“一个”。“父母”指两人，不能用“个”计量，应直接说“我父母都是工人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4458b0e9-2ef5-428a-8c1e-3b89dfc44717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88279, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们的父母的很关心我们。", "corrected_sentence": "我们的父母很关心我们。", "error_description": "错误：“父母”后多加了“的”。“的”用在定语后面，这里“父母”直接作主语，后面接“很关心”，应说“我们的父母很关心我们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4458b0e9-2ef5-428a-8c1e-3b89dfc44717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
