INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88280, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "父亲和母亲的合称。", "primary_collocate": null, "pronunciation": "fù mǔ", "ipa": "fu˥˩ mu˨˩˦", "syllable_count": 2, "sentences": [{"text": "请把这张表交给父母签字。", "target_word": "父母", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位同学的父母是医生。", "target_word": "父母", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校请所有学生的父母来开会。", "target_word": "父母", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母和孩子应该多说话。", "target_word": "父母", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的父母都是老师。", "target_word": "父母", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你父母身体好吗？", "target_word": "父母", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人的父母都不一样，但都很爱自己的孩子。", "target_word": "父母", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母不在家，他一个人吃饭。", "target_word": "父母", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小就听父母的话。", "target_word": "父母", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这对父母有两个女儿。", "target_word": "父母", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "父母亲", "label": "复合词"}, {"form": "祖父母", "label": "复合词"}], "register": "中性", "sense_fingerprint": "父亲和母亲的合称，指双亲", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b14ed482-1297-4790-a8d0-57fd5bb1c971') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88280, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "父母", "is_correct": true, "explanation": "正确：“请把这张表交给父母签字”，父母是需要签字的家长。"}, {"text": "树", "is_correct": false, "explanation": "语义：树不能在表上签字，句子需要一个能签字的人。"}, {"text": "狗", "is_correct": false, "explanation": "语义：狗不能在表上签字，句子说的是能签字的家长。"}, {"text": "书", "is_correct": false, "explanation": "搭配：“签字”需要签名的人，书不能与“签字”搭配。"}], "explanations": {"父母": "正确：“请把这张表交给父母签字”，父母是需要签字的家长。", "树": "语义：树不能在表上签字，句子需要一个能签字的人。", "狗": "语义：狗不能在表上签字，句子说的是能签字的家长。", "书": "搭配：“签字”需要签名的人，书不能与“签字”搭配。"}, "sentence_index": 0, "correct_answer": "父母"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这对父母都是女孩。", "explanation": "这里应该用〈双胞胎〉。“父母”指父亲和母亲，不能指两个女孩；这句话应说“这对双胞胎都是女孩”。"}, {"text": "这对父母还在上小学。", "explanation": "这里应该用〈孩子〉。“父母”指父亲和母亲，不能指还在上小学的孩子，这里要用“孩子”。"}, {"text": "这个父母有两个女儿。", "explanation": "这里应该用〈对〉。“父母”指两个人，量词要用“对”，不能用“这个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4458b0e9-2ef5-428a-8c1e-3b89dfc44717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88280, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "父母", "is_correct": true, "explanation": "正确：“每个人的父母都不一样”，指每个人自己的爸爸和妈妈，符合句意。"}, {"text": "太阳", "is_correct": false, "explanation": "搭配：“每个人的太阳”不是常见搭配，句子要指有父母的人。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮没有父母，句子说的是人的父母。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有父母，句子说的是人的父母。"}], "explanations": {"父母": "正确：“每个人的父母都不一样”，指每个人自己的爸爸和妈妈，符合句意。", "太阳": "搭配：“每个人的太阳”不是常见搭配，句子要指有父母的人。", "月亮": "语义：月亮没有父母，句子说的是人的父母。", "石头": "语义：石头没有父母，句子说的是人的父母。"}, "sentence_index": 6, "correct_answer": "父母"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这对父母在决赛中获得了金牌。", "explanation": "这里应该用〈选手〉。“父母”指父亲和母亲，不能指比赛中的选手，决赛拿金牌的是一对选手。"}, {"text": "这对父母明天要参加高考。", "explanation": "这里应该用〈考生〉。“父母”指父亲和母亲，不能指要参加高考的人，要参加高考的是考生。"}, {"text": "这对父母是我的同桌。", "explanation": "这里应该用〈同学〉。“父母”指父亲和母亲，不能是同桌；同桌是同学，要说“同学”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4458b0e9-2ef5-428a-8c1e-3b89dfc44717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88280, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个父母辛苦工作了一辈子。", "corrected_sentence": "那对父母辛苦工作了一辈子。", "error_description": "错误：量词用错了。“父母”指两人，应用量词“对”，说“那对父母”，不能说“那个父母”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4458b0e9-2ef5-428a-8c1e-3b89dfc44717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88280, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个父母都很忙。", "corrected_sentence": "这对父母都很忙。", "error_description": "错误：量词用错了。“父母”指两人，应用量词“对”，说“这对父母”，不能说“这个父母”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4458b0e9-2ef5-428a-8c1e-3b89dfc44717') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
