INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88287, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "组是几个人在一起,做同一件事,就叫一组。", "primary_collocate": null, "pronunciation": "zǔ", "ipa": "tsu˨˩˦", "syllable_count": 1, "sentences": [{"text": "老师把我们分成了三组。", "target_word": "组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们组一共有五个人。", "target_word": "组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上课时，我们四个人一组做练习。", "target_word": "组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想和哪一组一起去？", "target_word": "组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第一组的同学先唱歌。", "target_word": "组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们那一组做得最快。", "target_word": "组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们这组今天要做一个小游戏。", "target_word": "组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让每组选一个人说话。", "target_word": "组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我跟朋友分在同一组。", "target_word": "组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哪个组先做完，哪个组就可以回家。", "target_word": "组", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "組", "label": "繁体"}], "register": "口语", "sense_fingerprint": "组|名词|几个人在一起做同一件事的一组人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7b718ac-c4e5-459d-b8b0-a4e451916030') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88287, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "组", "is_correct": true, "explanation": "正确答案。组 zǔ（第三声）指几个人在一起做同一件事的一组人。"}, {"text": "族", "is_correct": false, "explanation": "族 zú（第二声）与 zǔ（第三声）声调不同，意思是家族、民族，不指一组人。"}, {"text": "主", "is_correct": false, "explanation": "主 zhǔ 与 zǔ 声母不同（zh 与 z），意思是主人、主要，与人群无关。"}, {"text": "走", "is_correct": false, "explanation": "走 zǒu 与 zǔ 韵母不同（ou 与 u），意思是行走，与人群无关。"}], "explanations": {"组": "正确答案。组 zǔ（第三声）指几个人在一起做同一件事的一组人。", "族": "族 zú（第二声）与 zǔ（第三声）声调不同，意思是家族、民族，不指一组人。", "主": "主 zhǔ 与 zǔ 声母不同（zh 与 z），意思是主人、主要，与人群无关。", "走": "走 zǒu 与 zǔ 韵母不同（ou 与 u），意思是行走，与人群无关。"}, "sentence_index": null, "correct_answer": "组"}, "level_3": {"options": [{"text": "组", "is_correct": true, "explanation": "正确：“三组”指分成的三个小组，符合句意。"}, {"text": "页", "is_correct": false, "explanation": "语义：“页”指书本或纸张的一面，不能用来分人。"}, {"text": "节", "is_correct": false, "explanation": "搭配：“节”多与“课”连用，人群不说“分成三节”。"}, {"text": "段", "is_correct": false, "explanation": "语义：“段”指文章或时间的一段，不指人群。"}], "explanations": {"组": "正确：“三组”指分成的三个小组，符合句意。", "页": "语义：“页”指书本或纸张的一面，不能用来分人。", "节": "搭配：“节”多与“课”连用，人群不说“分成三节”。", "段": "语义：“段”指文章或时间的一段，不指人群。"}, "sentence_index": 0, "correct_answer": "组"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑是他自己组的。", "explanation": "这里的组是动词，指拼装、装配，与指几个人一起做同一件事的名词义不同，这里不指那一组人。"}, {"text": "老师组了一支足球队，准备去比赛。", "explanation": "这里的组是动词，指组建，与指几个人一起做同一件事的名词义不同，这里不指那一组人。"}, {"text": "他想组一支乐队，每天都练习。", "explanation": "这里的组是动词，指组建乐队，与名词义不同，这里不指那一组人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac88911d-0e7f-4e56-9f4e-77105f58f5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88287, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "组", "is_correct": true, "explanation": "正确答案。组 zǔ（第三声）指几个人在一起做同一件事的一组人。"}, {"text": "足", "is_correct": false, "explanation": "足 zú（第二声）与 zǔ（第三声）声调不同，意思是脚或充足，与人群无关。"}, {"text": "租", "is_correct": false, "explanation": "租 zū（第一声）与 zǔ 声调不同，意思是租用，与人群无关。"}, {"text": "总", "is_correct": false, "explanation": "总 zǒng 与 zǔ 韵母不同（ong 与 u），意思是总是、总共，与人群无关。"}], "explanations": {"组": "正确答案。组 zǔ（第三声）指几个人在一起做同一件事的一组人。", "足": "足 zú（第二声）与 zǔ（第三声）声调不同，意思是脚或充足，与人群无关。", "租": "租 zū（第一声）与 zǔ 声调不同，意思是租用，与人群无关。", "总": "总 zǒng 与 zǔ 韵母不同（ong 与 u），意思是总是、总共，与人群无关。"}, "sentence_index": null, "correct_answer": "组"}, "level_3": {"options": [{"text": "组", "is_correct": true, "explanation": "正确：“这组”指我们这个小组，句意通顺。"}, {"text": "书", "is_correct": false, "explanation": "语义：“书”指书籍，不能指一起做游戏的人群。"}, {"text": "套", "is_correct": false, "explanation": "搭配：“套”指成套的物件，不用来指人群。"}, {"text": "字", "is_correct": false, "explanation": "语义：“字”指文字，不能指做游戏的人。"}], "explanations": {"组": "正确：“这组”指我们这个小组，句意通顺。", "书": "语义：“书”指书籍，不能指一起做游戏的人群。", "套": "搭配：“套”指成套的物件，不用来指人群。", "字": "语义：“字”指文字，不能指做游戏的人。"}, "sentence_index": 6, "correct_answer": "组"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这组饭馆的菜都很好吃。", "explanation": "这里应该用〈家〉。饭馆用“家”来数；组是几个人一起做同一件事的集体，不用来数店铺。"}, {"text": "这组城市都很大。", "explanation": "这里应该用〈座〉。城市用“座”来数；组是几个人一起做同一件事的集体，不用来指城市。"}, {"text": "我们自己组了一台电脑，很快就做好了。", "explanation": "这里的组是动词，指组装，与指几个人一起做同一件事的名词义不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac88911d-0e7f-4e56-9f4e-77105f58f5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warning