INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88287, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只组的人都很热情。", "corrected_sentence": "那个组的人都很热情。", "error_description": "错误：“那只组”；正确：“那个组”。组是集体名词，量词用“个”，“只”用于动物或成对物品中的一件。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac88911d-0e7f-4e56-9f4e-77105f58f5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88287, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这根组同学都很努力。", "corrected_sentence": "这组同学都很努力。", "error_description": "错误：“这根组”；正确：“这组”。“根”用于细长的物件，不能用来数同学组；直接说“这组同学”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac88911d-0e7f-4e56-9f4e-77105f58f5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
