INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88288, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "由若干人或事物结合成的集体或单位。", "primary_collocate": null, "pronunciation": "zǔ", "ipa": "tsu˨˩˦", "syllable_count": 1, "sentences": [{"text": "我们公司的每个组都有一个经理。", "target_word": "组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我们组年纪最大的人。", "target_word": "组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个组负责做新产品。", "target_word": "组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下个月我要换到别的组工作。", "target_word": "组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理说我们组这个月做得很好。", "target_word": "组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司新来了一个组，在三楼工作。", "target_word": "组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们组每星期一开会。", "target_word": "组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们组的同事都很热情。", "target_word": "组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们组今天谁值班？", "target_word": "组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司成立了一个新组，专门做网站。", "target_word": "组", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "組", "label": "繁体"}], "register": "口语", "sense_fingerprint": "组|名词|工作中由若干人结合成的单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7b718ac-c4e5-459d-b8b0-a4e451916030') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88288, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "组", "is_correct": true, "explanation": "正确答案。组 zǔ（第三声）此义指工作中由若干人结合成的单位。"}, {"text": "足", "is_correct": false, "explanation": "足 zú（第二声）与 zǔ 声调不同，意思是脚或充足，与工作单位无关。"}, {"text": "主", "is_correct": false, "explanation": "主 zhǔ 与 zǔ 声母不同（zh 与 z），意思是主人、主要，与工作单位无关。"}, {"text": "走", "is_correct": false, "explanation": "走 zǒu 与 zǔ 韵母不同（ou 与 u），意思是行走，与工作单位无关。"}], "explanations": {"组": "正确答案。组 zǔ（第三声）此义指工作中由若干人结合成的单位。", "足": "足 zú（第二声）与 zǔ 声调不同，意思是脚或充足，与工作单位无关。", "主": "主 zhǔ 与 zǔ 声母不同（zh 与 z），意思是主人、主要，与工作单位无关。", "走": "走 zǒu 与 zǔ 韵母不同（ou 与 u），意思是行走，与工作单位无关。"}, "sentence_index": null, "correct_answer": "组"}, "level_3": {"options": [{"text": "组", "is_correct": true, "explanation": "正确：“每个组”指公司里的工作单位，符合句意。"}, {"text": "页", "is_correct": false, "explanation": "语义：“页”指纸张的一面，不能指公司的工作单位。"}, {"text": "套", "is_correct": false, "explanation": "搭配：“套”指成套的物件，不说“每个套”指公司的单位。"}, {"text": "段", "is_correct": false, "explanation": "语义：“段”指文章或时间的一段，不指工作单位。"}], "explanations": {"组": "正确：“每个组”指公司里的工作单位，符合句意。", "页": "语义：“页”指纸张的一面，不能指公司的工作单位。", "套": "搭配：“套”指成套的物件，不说“每个套”指公司的单位。", "段": "语义：“段”指文章或时间的一段，不指工作单位。"}, "sentence_index": 0, "correct_answer": "组"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个组的校长是我的老同学。", "explanation": "这里应该用〈学校〉。校长是学校的负责人；组是公司里的工作单位，不设校长。"}, {"text": "这组货物的质量都很好。", "explanation": "这里应该用〈批〉。一批货物用“批”来数；组指工作中的人员单位，不用来指成批的货物。"}, {"text": "这组木头在仓库里放了十年。", "explanation": "这里应该用〈堆〉。木头是按堆放置的；组指工作中的人员单位，不用来指木头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac88911d-0e7f-4e56-9f4e-77105f58f5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88288, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "组", "is_correct": true, "explanation": "正确答案。组 zǔ（第三声）此义指工作中由若干人结合成的单位。"}, {"text": "族", "is_correct": false, "explanation": "族 zú（第二声）与 zǔ 声调不同，意思是家族、民族，不是工作单位。"}, {"text": "租", "is_correct": false, "explanation": "租 zū（第一声）与 zǔ 声调不同，意思是租用，与工作单位无关。"}, {"text": "总", "is_correct": false, "explanation": "总 zǒng 与 zǔ 韵母不同（ong 与 u），意思是总是、总共，与工作单位无关。"}], "explanations": {"组": "正确答案。组 zǔ（第三声）此义指工作中由若干人结合成的单位。", "族": "族 zú（第二声）与 zǔ 声调不同，意思是家族、民族，不是工作单位。", "租": "租 zū（第一声）与 zǔ 声调不同，意思是租用，与工作单位无关。", "总": "总 zǒng 与 zǔ 韵母不同（ong 与 u），意思是总是、总共，与工作单位无关。"}, "sentence_index": null, "correct_answer": "组"}, "level_3": {"options": [{"text": "组", "is_correct": true, "explanation": "正确：“我们组”指我们这个工作单位，句意通顺。"}, {"text": "桌", "is_correct": false, "explanation": "语义：“桌”是家具，不能开会。"}, {"text": "字", "is_correct": false, "explanation": "语义：“字”指文字，不能开会。"}, {"text": "盘", "is_correct": false, "explanation": "搭配：“盘”指盘状物或棋局，不指人群。"}], "explanations": {"组": "正确：“我们组”指我们这个工作单位，句意通顺。", "桌": "语义：“桌”是家具，不能开会。", "字": "语义：“字”指文字，不能开会。", "盘": "搭配：“盘”指盘状物或棋局，不指人群。"}, "sentence_index": 6, "correct_answer": "组"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这组葡萄今年一共卖了五百斤。", "explanation": "这里应该用〈批〉。葡萄按批出售；组指工作中的人员单位，不用来指葡萄。"}, {"text": "他们组了一张大床。", "explanation": "这里的组是动词，指拼装、装配，与指工作单位的名词义不同。"}, {"text": "这组钥匙是我昨天刚配的，挂在一起很方便。", "explanation": "这里应该用〈串〉。钥匙挂成一串；组指工作中的人员单位，不用来指钥匙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac88911d-0e7f-4e56-9f4e-77105f58f5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88288, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只组最近特别忙。", "corrected_sentence": "这个组最近特别忙。", "error_description": "错误：“这只组”；正确：“这个组”。组指工作中的单位，量词用“个”，“只”用于动物或成对物品中的一件。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac88911d-0e7f-4e56-9f4e-77105f58f5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88288, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把组同事都很年轻。", "corrected_sentence": "这组同事都很年轻。", "error_description": "错误：“这把组”；正确：“这组”。“把”用于有柄的物件，不用来数工作单位；直接说“这组同事”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac88911d-0e7f-4e56-9f4e-77105f58f5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
