INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88291, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "法官是在法庭里判断谁对谁错的人。", "primary_collocate": null, "pronunciation": "fǎ guān", "ipa": "fa˨˩˦ kuan˥", "syllable_count": 2, "sentences": [{"text": "法官在法庭上问了很多问题。", "target_word": "法官", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的叔叔是一位法官。", "target_word": "法官", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "法官听完两个人的话，才做决定。", "target_word": "法官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个法官很公平，大家都相信他。", "target_word": "法官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官让小李站起来回答。", "target_word": "法官", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她想长大以后当法官。", "target_word": "法官", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "法官穿着黑色的衣服坐在前面。", "target_word": "法官", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官看了看桌上的文件。", "target_word": "法官", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法官说：“请大家安静。”", "target_word": "法官", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位法官工作了二十年。", "target_word": "法官", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "女法官", "label": "复合"}, {"form": "大法官", "label": "复合"}], "register": "中性", "sense_fingerprint": "在法庭里判断谁对谁错的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e1a0300-a4d2-44ca-8527-0106e0d41547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88291, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "法官", "is_correct": true, "explanation": "正确：句中指在法庭上提问的人，只有“法官”符合。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是地方，不能在法庭上提问。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是物品，不能在法庭上提问。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园不是人，不能提问。"}], "explanations": {"法官": "正确：句中指在法庭上提问的人，只有“法官”符合。", "厨房": "语义：厨房是地方，不能在法庭上提问。", "黑板": "语义：黑板是物品，不能在法庭上提问。", "花园": "语义：花园不是人，不能提问。"}, "sentence_index": 0, "correct_answer": "法官"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "法官在法庭上向被告提出了指控。", "explanation": "这里应该用〈检察官〉。指控由检察官提出，法官负责裁决，不提出指控。"}, {"text": "法官为被告辩护，希望法院减轻处罚。", "explanation": "这里应该用〈律师〉。替被告辩护是律师的工作，法官应保持中立，不替任何一方辩护。"}, {"text": "足球比赛中，法官吹响了终场哨。", "explanation": "这里应该用〈裁判〉。足球比赛中吹哨、判罚的是裁判，法官只在法庭上审理案件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af0a8f65-c4a0-4894-a994-ad30f7815c4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88291, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "法官", "is_correct": true, "explanation": "正确：指穿黑色衣服坐在前面的人，只有“法官”符合。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会穿衣服，也不会坐。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不会穿衣服，也不会坐。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器，不会穿衣服坐在前面。"}], "explanations": {"法官": "正确：指穿黑色衣服坐在前面的人，只有“法官”符合。", "石头": "语义：石头不会穿衣服，也不会坐。", "书包": "语义：书包不会穿衣服，也不会坐。", "钢琴": "语义：钢琴是乐器，不会穿衣服坐在前面。"}, "sentence_index": 6, "correct_answer": "法官"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的叔叔在法官工作，每天早上九点上班。", "explanation": "这里应该用〈法院〉。“在……工作”的地点要用法院，法官是审判案件的人，不是工作的地方。"}, {"text": "法官在医院给病人检查身体，还开了药。", "explanation": "这里应该用〈医生〉。给病人检查身体、开药的是医生，法官在法院审理案件。"}, {"text": "法官在厨房做了一顿饭，味道很好。", "explanation": "这里应该用〈厨师〉。做饭的是厨师，法官在法院审理案件，不做饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af0a8f65-c4a0-4894-a994-ad30f7815c4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88291, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只年轻的法官很认真。", "corrected_sentence": "这位年轻的法官很认真。", "error_description": "量词错误：指人的“法官”应用“位”，不用“只”（“只”多用于动物）。应改为“这位年轻的法官很认真”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af0a8f65-c4a0-4894-a994-ad30f7815c4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88291, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那支法官是我的老朋友。", "corrected_sentence": "那位法官是我的老朋友。", "error_description": "量词错误：“法官”指人，应用“位”，不能用“支”（“支”多用于笔、蜡烛等细长的东西）。应改为“那位法官是我的老朋友”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af0a8f65-c4a0-4894-a994-ad30f7815c4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
