INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88300, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把有关事项写在册子上，以备查考。", "primary_collocate": null, "pronunciation": "dēng jì", "ipa": "təŋ⁵⁵ tɕi⁵¹", "syllable_count": 2, "sentences": [{"text": "请先在这里登记名字。", "target_word": "登记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住旅馆要登记身份证。", "target_word": "登记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在本子上登记了客人的电话。", "target_word": "登记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你登记了吗？", "target_word": "登记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来参加会议的人都要登记。", "target_word": "登记", "complexity_tier": "T3", "furigana": "lái cān jiā huì yì de rén dōu yào dēng jì", "sentence_source": "generated"}, {"text": "老师让我们把书的名字登记下来。", "target_word": "登记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她正在登记新来的学生。", "target_word": "登记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你先登记，再进去。", "target_word": "登记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去医院看病，要先登记。", "target_word": "登记", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王把每天的花费都登记在本子上。", "target_word": "登记", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "登记了", "label": "体标"}, {"form": "登记过", "label": "体标"}, {"form": "登记登记", "label": "重叠"}], "register": "中性", "sense_fingerprint": "登记：把事项写进册子备查", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2629cfaa-ecb6-48f0-80ae-066a0850e85a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88300, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "登记", "is_correct": true, "explanation": "登记：把有关事项写在册子上，以备查考。正确答案。"}, {"text": "等级", "is_correct": false, "explanation": "děngjí（第三声、第二声）与 dēngjì（第一声、第四声）声调不同，意思是等级。"}, {"text": "等价", "is_correct": false, "explanation": "děngjià（第三声、第四声）与 dēngjì 第一个音节声调不同（děng 与 dēng），意思是价值相等。"}, {"text": "登机", "is_correct": false, "explanation": "dēngjī 第二个音节 jī（第一声）与 jì（第四声）声调不同，意思是上飞机。"}], "explanations": {"登记": "登记：把有关事项写在册子上，以备查考。正确答案。", "等级": "děngjí（第三声、第二声）与 dēngjì（第一声、第四声）声调不同，意思是等级。", "等价": "děngjià（第三声、第四声）与 dēngjì 第一个音节声调不同（děng 与 dēng），意思是价值相等。", "登机": "dēngjī 第二个音节 jī（第一声）与 jì（第四声）声调不同，意思是上飞机。"}, "sentence_index": null, "correct_answer": "登记"}, "level_3": {"options": [{"text": "登记", "is_correct": true, "explanation": "登记：把名字写在册子上，符合“请先在这里……”的语境。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的宾语是物品，不能说“洗名字”。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”是加热，名字不能被烧，与句意不合。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”是舍去，与“请先在这里……名字”的要求相反。"}], "explanations": {"登记": "登记：把名字写在册子上，符合“请先在这里……”的语境。", "洗": "搭配：“洗”的宾语是物品，不能说“洗名字”。", "烧": "语义：“烧”是加热，名字不能被烧，与句意不合。", "放弃": "语义：“放弃”是舍去，与“请先在这里……名字”的要求相反。"}, "sentence_index": 0, "correct_answer": "登记"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想把这个生词登记在脑子里。", "explanation": "这里应该用〈记住〉。登记指把事项写在册子上备查，记在脑子里要用〈记住〉。"}, {"text": "医生登记了他的心脏。", "explanation": "这里应该用〈检查〉。登记指把事项写在册子上备查，给病人做身体检查要用〈检查〉。"}, {"text": "他在比赛中登记了冠军。", "explanation": "这里应该用〈获得〉。登记指把事项写在册子上备查，表示拿到名次要用〈获得〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02715c0c-42fc-4b33-851a-a1d47916bb2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88300, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "登记", "is_correct": true, "explanation": "登记：把名字写在册子上，符合“她正在……新来的学生”的语境。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：“咬”的宾语多是食物或物体，不能用于学生。"}, {"text": "切", "is_correct": false, "explanation": "语义：''切''是切割，学生不能被切开，与句意不合。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢弃，学生不能被丢弃，句意不合理。"}], "explanations": {"登记": "登记：把名字写在册子上，符合“她正在……新来的学生”的语境。", "咬": "搭配：“咬”的宾语多是食物或物体，不能用于学生。", "切": "语义：''切''是切割，学生不能被切开，与句意不合。", "扔": "语义：“扔”是丢弃，学生不能被丢弃，句意不合理。"}, "sentence_index": 6, "correct_answer": "登记"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这篇论文终于登记在报纸上了。", "explanation": "这里应该用〈发表〉。登记指把事项写在册子上备查，文章公开刊出要用〈发表〉。"}, {"text": "他一生气就登记脾气。", "explanation": "这里应该用〈发〉（发脾气）。登记指写下事项备查，不能用来表示发泄情绪。"}, {"text": "他登记了一个笑话，大家都笑了。", "explanation": "这里应该用〈讲〉（讲笑话）。登记指写下事项，不能用于讲笑话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02715c0c-42fc-4b33-851a-a1d47916bb2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88300, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我已经把名字登记了好。", "corrected_sentence": "我已经把名字登记好了。", "error_description": "错误：“登记了好”。正确：“登记好了”。结果补语“好”应紧跟动词“登记”，“了”放在句末。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02715c0c-42fc-4b33-851a-a1d47916bb2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88300, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我明天要去派出所登记了。", "corrected_sentence": "我明天要去派出所登记。", "error_description": "错误：“登记了”。正确：“登记”。“明天”指未来，动作尚未发生，不能用“了”表示完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02715c0c-42fc-4b33-851a-a1d47916bb2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
