INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88301, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "过来是从那边走到我这边来。", "primary_collocate": null, "pronunciation": "guò lái", "ipa": "kuɔ˥˩ lai̯˧˥", "syllable_count": 2, "sentences": [{"text": "你从那边过来，我在这边等你。", "target_word": "过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桥那边的人慢慢过来了。", "target_word": "过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说他马上就过来。", "target_word": "过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路那边有一个人正在过来。", "target_word": "过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们什么时候过来？", "target_word": "过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在这边，你过来吧。", "target_word": "过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你过来的时候，请给我买杯水。", "target_word": "过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对面的孩子都过来了。", "target_word": "过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河那边的老人慢慢地过来。", "target_word": "过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从学校过来，要二十分钟。", "target_word": "过来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "过来了", "label": "体标"}, {"form": "过来过", "label": "体标"}, {"form": "過來", "label": "繁体"}], "register": "口语", "sense_fingerprint": "过来|动词|从那边走到我这边来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7b718ac-c4e5-459d-b8b0-a4e451916030') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88301, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "过来", "is_correct": true, "explanation": "正确：“过来”指朝说话人这边移动，符合句意。"}, {"text": "扔", "is_correct": false, "explanation": "配价：“扔”必须带受事宾语，“从那边扔”不成句。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与“我在这边等你”的语境矛盾。"}, {"text": "生气", "is_correct": false, "explanation": "语义：“生气”不能表示移动，句意不通。"}], "explanations": {"过来": "正确：“过来”指朝说话人这边移动，符合句意。", "扔": "配价：“扔”必须带受事宾语，“从那边扔”不成句。", "睡觉": "语义：“睡觉”与“我在这边等你”的语境矛盾。", "生气": "语义：“生气”不能表示移动，句意不通。"}, "sentence_index": 0, "correct_answer": "过来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我要过来郊外玩。", "explanation": "这里应该用〈去〉。去郊外是离开说话人所在的地方，“过来”只表示朝说话人所在处移动。"}, {"text": "我一听就明白过来了。", "explanation": "这里的“过来”是“醒悟、明白”的义项，不指朝说话人方向移动。"}, {"text": "这件事我想了很久才想过来。", "explanation": "这里的“过来”是“想通、领悟”的义项，不指位置移动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac88911d-0e7f-4e56-9f4e-77105f58f5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88301, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "过来", "is_correct": true, "explanation": "正确：“你过来的时候”指对方来到说话人处，符合句意。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭的时候”与“请给我买水”的语境不合。"}, {"text": "滚", "is_correct": false, "explanation": "语域：“滚”是粗鲁的说法，不适合用于请人帮忙的句子。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔的时候”与请人买水的语境矛盾。"}], "explanations": {"过来": "正确：“你过来的时候”指对方来到说话人处，符合句意。", "哭": "语义：“哭的时候”与“请给我买水”的语境不合。", "滚": "语域：“滚”是粗鲁的说法，不适合用于请人帮忙的句子。", "摔": "语义：“摔的时候”与请人买水的语境矛盾。"}, "sentence_index": 6, "correct_answer": "过来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这么难的题，他一下子想不过来。", "explanation": "这里的“过来”构成可能补语“想不过来”，表示想不清、想不完，不指朝说话人方向移动。"}, {"text": "那个孩子的情绪终于缓过来了。", "explanation": "这里的“过来”是“恢复平静、缓和”的义项，不指朝说话人方向移动。"}, {"text": "这个词翻译过来，就是“朋友”的意思。", "explanation": "这里的“过来”是“转换、译成”的义项，不指朝说话人方向移动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac88911d-0e7f-4e56-9f4e-77105f58f5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88301, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶听到消息，就哭起过来了。", "corrected_sentence": "奶奶听到消息，就哭起来了。", "error_description": "错误：“哭起过来”；正确：“哭起来”。“起来”是固定的趋向补语，中间不能插入“过”，应改为“哭起来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac88911d-0e7f-4e56-9f4e-77105f58f5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88301, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你过来地时候，我正在做饭。", "corrected_sentence": "你过来的时候，我正在做饭。", "error_description": "错误：「过来地时候」；正确：「过来的时候」。「地」用于修饰动词或形容词作状语，「时候」是名词，前面的修饰语须用「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac88911d-0e7f-4e56-9f4e-77105f58f5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88302, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "过去", "is_correct": true, "explanation": "过去：与“过来”方向相反，指向离开说话人所在处的方向移动，是此义的反义词。"}, {"text": "睡觉", "is_correct": false, "explanation": "睡觉：动词，与“过来”的移动方向无关，不是它的反义词。"}, {"text": "唱歌", "is_correct": false, "explanation": "唱歌：动词，与移动方向无关，不构成反义关系。"}, {"text": "写字", "is_correct": false, "explanation": "写字：动词，与移动方向无关，不是“过来”的反义词。"}], "correct_answer": "过去", "explanations": {"过去": "过去：与“过来”方向相反，指向离开说话人所在处的方向移动，是此义的反义词。", "睡觉": "睡觉：动词，与“过来”的移动方向无关，不是它的反义词。", "唱歌": "唱歌：动词，与移动方向无关，不构成反义关系。", "写字": "写字：动词，与移动方向无关，不是“过来”的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac88911d-0e7f-4e56-9f4e-77105f58f5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88302, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "过去", "is_correct": true, "explanation": "过去：与“过来”方向相反，指向离开说话人所在处的方向移动，是此义的反义词。"}, {"text": "读书", "is_correct": false, "explanation": "读书：动词，与移动方向无关，不是“过来”的反义词。"}, {"text": "跑步", "is_correct": false, "explanation": "跑步：动词，描述的是动作方式，不表示与“过来”相反的移动方向。"}, {"text": "散步", "is_correct": false, "explanation": "散步：动词，与“过来”的方向意义无关，不构成反义关系。"}], "correct_answer": "过去", "explanations": {"过去": "过去：与“过来”方向相反，指向离开说话人所在处的方向移动，是此义的反义词。", "读书": "读书：动词，与移动方向无关，不是“过来”的反义词。", "跑步": "跑步：动词，描述的是动作方式，不表示与“过来”相反的移动方向。", "散步": "散步：动词，与“过来”的方向意义无关，不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac88911d-0e7f-4e56-9f4e-77105f58f5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88302, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从别处向说话人所在的位置移动。", "primary_collocate": null, "pronunciation": "guò lái", "ipa": "kuɔ˥˩ lai̯˧˥", "syllable_count": 2, "sentences": [{"text": "你快过来，我给你看一个东西。", "target_word": "过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你过来一下，我有话要说。", "target_word": "过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师叫我过来。", "target_word": "过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从那边过来了。", "target_word": "过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗看见我，就过来了。", "target_word": "过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能过来帮我拿一下吗？", "target_word": "过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在门口叫我：“过来吃饭！”", "target_word": "过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别站在那里，过来坐吧。", "target_word": "过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想过来看看我们的新家。", "target_word": "过来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你一个人过来，不要带别人。", "target_word": "过来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "过来了", "label": "体标"}, {"form": "过来过", "label": "体标"}, {"form": "過來", "label": "繁体"}], "register": "口语", "sense_fingerprint": "过来|动词|从别处向说话人所在的位置移动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7b718ac-c4e5-459d-b8b0-a4e451916030') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88302, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "过来", "is_correct": true, "explanation": "正确：“过来”表示朝说话人所在处移动，符合句意。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”与“给你看东西”的语境不合，句意不通。"}, {"text": "滚", "is_correct": false, "explanation": "语域：“滚”是粗鲁的驱赶语，与请对方过来看东西的语气不合。"}, {"text": "扔", "is_correct": false, "explanation": "配价：“扔”必须带受事宾语，“你快扔”不成句。"}], "explanations": {"过来": "正确：“过来”表示朝说话人所在处移动，符合句意。", "哭": "语义：“哭”与“给你看东西”的语境不合，句意不通。", "滚": "语域：“滚”是粗鲁的驱赶语，与请对方过来看东西的语气不合。", "扔": "配价：“扔”必须带受事宾语，“你快扔”不成句。"}, "sentence_index": 0, "correct_answer": "过来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我明天过来北京出差。", "explanation": "这里应该用〈去〉。去北京是离开说话人所在的地方，“过来”只表示朝说话人所在处移动。"}, {"text": "他一听就反应过来了。", "explanation": "这里的“过来”是“醒悟、明白”的义项，不指朝说话人方向移动。"}, {"text": "他把头转过来，看了我一眼。", "explanation": "这里的“过来”是“转动、改变朝向”的义项，不指朝说话人方向移动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac88911d-0e7f-4e56-9f4e-77105f58f5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88302, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "过来", "is_correct": true, "explanation": "正确：“过来吃饭”是叫对方到说话人处吃饭，符合句意。"}, {"text": "走开", "is_correct": false, "explanation": "语义：“走开”是让人离开，与叫人吃饭的语境矛盾。"}, {"text": "发呆", "is_correct": false, "explanation": "语义：“发呆”与叫人吃饭的语境不合。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”不能直接与“吃饭”组成动词短语，“喝吃饭”不成句。"}], "explanations": {"过来": "正确：“过来吃饭”是叫对方到说话人处吃饭，符合句意。", "走开": "语义：“走开”是让人离开，与叫人吃饭的语境矛盾。", "发呆": "语义：“发呆”与叫人吃饭的语境不合。", "喝": "搭配：“喝”不能直接与“吃饭”组成动词短语，“喝吃饭”不成句。"}, "sentence_index": 6, "correct_answer": "过来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把这篇英文翻译过来，发给了大家。", "explanation": "这里的“过来”是“转换、译成”的义项，不指朝说话人方向移动。"}, {"text": "他的病终于好过来了。", "explanation": "这里的“过来”是“恢复、好转”的义项，不指朝说话人方向移动。"}, {"text": "这么多人，我一下子记不过来。", "explanation": "这里的“过来”是“记得全、顾得上”的义项，不指位置移动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac88911d-0e7f-4e56-9f4e-77105f58f5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88302, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他看到我们，就哭起过来了。", "corrected_sentence": "他看到我们，就哭起来了。", "error_description": "错误：“哭起过来”；正确：“哭起来”。“起来”是固定的趋向补语，中间不能插入“过”，应改为“哭起来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac88911d-0e7f-4e56-9f4e-77105f58f5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88302, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "快过来过，我在这儿等你。", "corrected_sentence": "快过来，我在这儿等你。", "error_description": "错误：“过来过”；正确：“过来”。“快”后是祈使句，不能加“过”表示经历，应直接说“快过来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac88911d-0e7f-4e56-9f4e-77105f58f5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
