INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88311, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "等第是东西好坏的一级一级的名次。", "primary_collocate": null, "pronunciation": "děng dì", "ipa": "təŋ²¹⁴ ti⁵¹", "syllable_count": 2, "sentences": [{"text": "这些苹果分好几个等第。", "target_word": "等第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店家公布了每批茶叶的等第。", "target_word": "等第", "complexity_tier": "T3", "furigana": "diàn jiā gōng bù le měi pī chá yè de děng dì", "sentence_source": "generated"}, {"text": "他的作文得到了很好的等第。", "target_word": "等第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买东西前先看看等第。", "target_word": "等第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个等第比那个等第高。", "target_word": "等第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批茶按品质分成三个等第，价钱各不相同。", "target_word": "等第", "complexity_tier": "T3", "furigana": "zhè pī chá àn pǐn zhì fēn chéng sān gè děng dì, jià qian gè bù xiāng tóng", "sentence_source": "generated"}, {"text": "商店里的米按等第卖，价格不一样。", "target_word": "等第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想知道这批苹果的等第吗？", "target_word": "等第", "complexity_tier": "T3", "furigana": "nǐ xiǎng zhī dào zhè pī píng guǒ de děng dì ma", "sentence_source": "generated"}, {"text": "这批货的等第不太好。", "target_word": "等第", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好茶的等第是怎么分的？", "target_word": "等第", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "书面", "sense_fingerprint": "等第：好坏一级一级的名次", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2629cfaa-ecb6-48f0-80ae-066a0850e85a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88311, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "等第", "is_correct": true, "explanation": "等第：按好坏分出的一级一级的名次，符合“这些苹果分好几个……”的语境。"}, {"text": "名字", "is_correct": false, "explanation": "语义：苹果是按质量分级的，不能分出“名字”。"}, {"text": "颜色", "is_correct": false, "explanation": "量词与语义：''颜色''与量词''个''不搭（应为''种''），且苹果是按质量分级的，不是按颜色分。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”不是苹果分级的依据，句意不通。"}], "explanations": {"等第": "等第：按好坏分出的一级一级的名次，符合“这些苹果分好几个……”的语境。", "名字": "语义：苹果是按质量分级的，不能分出“名字”。", "颜色": "量词与语义：''颜色''与量词''个''不搭（应为''种''），且苹果是按质量分级的，不是按颜色分。", "体重": "语义：“体重”不是苹果分级的依据，句意不通。"}, "sentence_index": 0, "correct_answer": "等第"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的等第比你大。", "explanation": "这里应该用〈年龄〉。等第是好坏的级别，不能用来比较人的年龄。"}, {"text": "这只猫的等第很重。", "explanation": "这里应该用〈体重〉。等第表示级别，不能用来说猫的轻重。"}, {"text": "这个名字的等第很好听。", "explanation": "这里应该用〈名称〉。等第指东西好坏的一级一级的名次，不能用来指事物的名称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02715c0c-42fc-4b33-851a-a1d47916bb2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88311, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "等第", "is_correct": true, "explanation": "等第：按质量划分的级别，符合“商店里的米按……卖”的语境。"}, {"text": "身高", "is_correct": false, "explanation": "语义：米没有身高，不能按身高卖。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：米没有脾气，不能作为卖价的依据。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“按”后的依据应是质量或种类，不说“按性格卖”。"}], "explanations": {"等第": "等第：按质量划分的级别，符合“商店里的米按……卖”的语境。", "身高": "语义：米没有身高，不能按身高卖。", "脾气": "语义：米没有脾气，不能作为卖价的依据。", "性格": "搭配：“按”后的依据应是质量或种类，不说“按性格卖”。"}, "sentence_index": 6, "correct_answer": "等第"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这根绳子的等第很长。", "explanation": "这里应该用〈长度〉。等第表示级别，不能用来说绳子的长短。"}, {"text": "她的等第很漂亮。", "explanation": "这里应该用〈容貌〉。等第表示级别，不能用来形容人的外貌。"}, {"text": "这首歌的等第很响亮。", "explanation": "这里应该用〈音量〉。等第表示级别，不能用来形容声音的大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02715c0c-42fc-4b33-851a-a1d47916bb2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88311, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些苹果分成了几只等第。", "corrected_sentence": "这些苹果分成了几个等第。", "error_description": "错误：“几只等第”。正确：“几个等第”。“等第”是抽象名词，计量用“个”，“只”不能用于等第。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02715c0c-42fc-4b33-851a-a1d47916bb2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88311, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这批茶的等第很高地。", "corrected_sentence": "这批茶的等第很高。", "error_description": "错误：''很高地''。正确：''很高''。作谓语的形容词后不加''地''，''地''用于修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02715c0c-42fc-4b33-851a-a1d47916bb2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
