INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88317, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "重大就是特别大,特别要紧。", "primary_collocate": null, "pronunciation": "zhòng dà", "ipa": "ʈʂʊŋ˥˩ ta˥˩", "syllable_count": 2, "sentences": [{"text": "这是一个重大的消息。", "target_word": "重大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事情非常重大，我们必须马上告诉校长。", "target_word": "重大", "complexity_tier": "T3", "furigana": "zhòng dà", "sentence_source": "generated"}, {"text": "公司今天做出了一个重大决定。", "target_word": "重大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在比赛中犯了重大错误。", "target_word": "重大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的计划出现了重大问题。", "target_word": "重大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天城里发生了一起重大事故。", "target_word": "重大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是我一生中最重大的选择。", "target_word": "重大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "结婚是人生中一件重大的事。", "target_word": "重大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项重大任务要在周五前完成。", "target_word": "重大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次会议有重大的变化吗？", "target_word": "重大", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "重大:特别大、特别要紧(事情的程度)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b078f6bf-921d-40ec-bb52-91d878751ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88317, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "重大", "is_correct": true, "explanation": "正确答案。zhòng dà，指特别大、特别要紧。"}, {"text": "重达", "is_correct": false, "explanation": "dá（第二声）与 dà（第四声）声调不同，意思是分量达到某个数量。"}, {"text": "肿大", "is_correct": false, "explanation": "zhǒng（第三声）与 zhòng（第四声）声调不同，意思是肿起变大。"}, {"text": "胀大", "is_correct": false, "explanation": "zhàng 与 zhòng 韵母不同（ang 与 ong），意思是膨胀变大。"}], "explanations": {"重大": "正确答案。zhòng dà，指特别大、特别要紧。", "重达": "dá（第二声）与 dà（第四声）声调不同，意思是分量达到某个数量。", "肿大": "zhǒng（第三声）与 zhòng（第四声）声调不同，意思是肿起变大。", "胀大": "zhàng 与 zhòng 韵母不同（ang 与 ong），意思是膨胀变大。"}, "sentence_index": null, "correct_answer": "重大"}, "level_3": {"options": [{"text": "重大", "is_correct": true, "explanation": "正确。“重大的消息”指特别要紧的消息，符合句意。"}, {"text": "红色", "is_correct": false, "explanation": "语义：颜色不能修饰消息，“红色的消息”句意不通。"}, {"text": "高", "is_correct": false, "explanation": "体貌：“高”形容人或物的体形，不能用来修饰消息。"}, {"text": "圆", "is_correct": false, "explanation": "语义：“圆”描述形状，消息没有形状，句意不通。"}], "explanations": {"重大": "正确。“重大的消息”指特别要紧的消息，符合句意。", "红色": "语义：颜色不能修饰消息，“红色的消息”句意不通。", "高": "体貌：“高”形容人或物的体形，不能用来修饰消息。", "圆": "语义：“圆”描述形状，消息没有形状，句意不通。"}, "sentence_index": 0, "correct_answer": "重大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是公司里很重大的人。", "explanation": "这里应该用〈重要〉。重要可以形容人的地位，重大多用于事情、问题、变化，不用于形容人。"}, {"text": "这个笑话很重大，大家都笑了。", "explanation": "这里应该用〈好笑〉。重大不能用来形容笑话的好笑程度。"}, {"text": "他对这件事的印象很重大，一直记得。", "explanation": "这里应该用〈深刻〉。重大指事情的影响或规模大，不能用来形容印象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b84136e5-6a12-4d26-a4f5-7e2fd0c4690a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88317, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重大", "is_correct": true, "explanation": "正确。“最重大的选择”指对人生影响最大的选择，符合句意。"}, {"text": "甜", "is_correct": false, "explanation": "语义：口味不能用来修饰选择，“最甜的选择”句意不通。"}, {"text": "湿", "is_correct": false, "explanation": "语义：“湿”形容含水分的状态，不能修饰选择，句意不通。"}, {"text": "硬", "is_correct": false, "explanation": "语义：质地不能用来修饰选择，句意不通。"}], "explanations": {"重大": "正确。“最重大的选择”指对人生影响最大的选择，符合句意。", "甜": "语义：口味不能用来修饰选择，“最甜的选择”句意不通。", "湿": "语义：“湿”形容含水分的状态，不能修饰选择，句意不通。", "硬": "语义：质地不能用来修饰选择，句意不通。"}, "sentence_index": 6, "correct_answer": "重大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他做事很重大，从不马虎。", "explanation": "这里应该用〈认真〉。重大不能用来形容做事的态度，形容态度应用“认真”。"}, {"text": "她的性格很重大，总是让人难以接近。", "explanation": "这里应该用〈温柔〉。重大不能用来形容人的性格。"}, {"text": "她的笑容很重大，大家都很喜欢。", "explanation": "这里应该用〈灿烂〉。重大不能用来形容笑容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b84136e5-6a12-4d26-a4f5-7e2fd0c4690a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88317, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事比那件事很重大，需要大家共同处理。", "corrected_sentence": "这件事比那件事更重大，需要大家共同处理。", "error_description": "错误在于“比”字句中用了程度副词“很”。比较句中应使用“更”，应说“这件事比那件事更重大”，不能说“这件事比那件事很重大”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b84136e5-6a12-4d26-a4f5-7e2fd0c4690a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88317, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次会议的结果比上次很重大。", "corrected_sentence": "这次会议的结果比上次更重大。", "error_description": "错误在于“比”字句中用了程度副词“很”。比较句中应使用“更”，应说“这次会议的结果比上次更重大”，不能说“这次会议的结果比上次很重大”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b84136e5-6a12-4d26-a4f5-7e2fd0c4690a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88318, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "轻微", "is_correct": true, "explanation": "正确。轻微与重大构成反义，指程度轻、影响小，与“意义深远”相对。"}, {"text": "漂亮", "is_correct": false, "explanation": "漂亮与“重大”没有反义关系，只形容外貌或事物美观。"}, {"text": "热闹", "is_correct": false, "explanation": "热闹与“重大”没有反义关系，只形容场面喧闹。"}, {"text": "安静", "is_correct": false, "explanation": "安静与“重大”没有反义关系，只形容没有声响或情绪平和。"}], "correct_answer": "轻微", "explanations": {"轻微": "正确。轻微与重大构成反义，指程度轻、影响小，与“意义深远”相对。", "漂亮": "漂亮与“重大”没有反义关系，只形容外貌或事物美观。", "热闹": "热闹与“重大”没有反义关系，只形容场面喧闹。", "安静": "安静与“重大”没有反义关系，只形容没有声响或情绪平和。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b84136e5-6a12-4d26-a4f5-7e2fd0c4690a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88318, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "轻微", "is_correct": true, "explanation": "正确。轻微与重大构成反义，指程度轻、影响小，与“意义深远”相对。"}, {"text": "普通", "is_correct": false, "explanation": "普通与“重大”没有反义关系，只表示一般、平常。"}, {"text": "复杂", "is_correct": false, "explanation": "复杂与“重大”没有反义关系，只表示情况繁多、不简单。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚与“重大”没有反义关系，只表示明白、不模糊。"}], "correct_answer": "轻微", "explanations": {"轻微": "正确。轻微与重大构成反义，指程度轻、影响小，与“意义深远”相对。", "普通": "普通与“重大”没有反义关系，只表示一般、平常。", "复杂": "复杂与“重大”没有反义关系，只表示情况繁多、不简单。", "清楚": "清楚与“重大”没有反义关系，只表示明白、不模糊。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b84136e5-6a12-4d26-a4f5-7e2fd0c4690a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88318, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "分量大,意义深远,关系重要的。", "primary_collocate": null, "pronunciation": "zhòng dà", "ipa": "ʈʂʊŋ˥˩ ta˥˩", "syllable_count": 2, "sentences": [{"text": "这项发明对世界有重大影响。", "target_word": "重大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说这次手术关系重大。", "target_word": "重大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一个关系到国家未来的重大问题。", "target_word": "重大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家做出了重大贡献。", "target_word": "重大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次会议作出了重大决定。", "target_word": "重大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是历史上的一次重大变化。", "target_word": "重大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在工作中取得了重大进展。", "target_word": "重大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次改革意义重大，影响很深。", "target_word": "重大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说这件事责任重大。", "target_word": "重大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个重大发现改变了我们的生活。", "target_word": "重大", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "重大:分量大、意义深远、关系重要", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b078f6bf-921d-40ec-bb52-91d878751ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88318, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "重大", "is_correct": true, "explanation": "正确答案。zhòng dà，指分量大、意义深远、关系重要。"}, {"text": "重达", "is_correct": false, "explanation": "dá（第二声）与 dà（第四声）声调不同，意思是分量达到某个数量。"}, {"text": "肿大", "is_correct": false, "explanation": "zhǒng（第三声）与 zhòng（第四声）声调不同，意思是肿起变大。"}, {"text": "胀大", "is_correct": false, "explanation": "zhàng 与 zhòng 韵母不同（ang 与 ong），意思是膨胀变大。"}], "explanations": {"重大": "正确答案。zhòng dà，指分量大、意义深远、关系重要。", "重达": "dá（第二声）与 dà（第四声）声调不同，意思是分量达到某个数量。", "肿大": "zhǒng（第三声）与 zhòng（第四声）声调不同，意思是肿起变大。", "胀大": "zhàng 与 zhòng 韵母不同（ang 与 ong），意思是膨胀变大。"}, "sentence_index": null, "correct_answer": "重大"}, "level_3": {"options": [{"text": "重大", "is_correct": true, "explanation": "正确。“重大影响”指意义深远的影响，符合句意。"}, {"text": "慢", "is_correct": false, "explanation": "语义：“慢”形容速度，不能用来修饰影响，句意不通。"}, {"text": "厚", "is_correct": false, "explanation": "搭配：影响没有厚薄，不能说“厚影响”。"}, {"text": "脆", "is_correct": false, "explanation": "语义：“脆”形容食物或物体的质地，不能修饰影响。"}], "explanations": {"重大": "正确。“重大影响”指意义深远的影响，符合句意。", "慢": "语义：“慢”形容速度，不能用来修饰影响，句意不通。", "厚": "搭配：影响没有厚薄，不能说“厚影响”。", "脆": "语义：“脆”形容食物或物体的质地，不能修饰影响。"}, "sentence_index": 0, "correct_answer": "重大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位老师在学校里很重大。", "explanation": "这里应该用〈重要〉。重大多用于事情、问题、变化，不用于形容人的地位。"}, {"text": "这幅画的颜色很重大，看起来很暗。", "explanation": "这里应该用〈深〉。重大形容事情或问题的分量，不能形容颜色；颜色的深浅要用“深”。"}, {"text": "街上很重大，人来人往。", "explanation": "这里应该用〈热闹〉。重大不能用来形容地方的热闹程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b84136e5-6a12-4d26-a4f5-7e2fd0c4690a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88318, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重大", "is_correct": true, "explanation": "正确。“取得了重大进展”指取得了意义重大的进步，符合句意。"}, {"text": "方", "is_correct": false, "explanation": "语义：形状不能用来修饰进展，句意不通。"}, {"text": "甜", "is_correct": false, "explanation": "语义：口味不能用来修饰进展，句意不通。"}, {"text": "窄", "is_correct": false, "explanation": "搭配：“窄”形容空间，“进展”不能说窄。"}], "explanations": {"重大": "正确。“取得了重大进展”指取得了意义重大的进步，符合句意。", "方": "语义：形状不能用来修饰进展，句意不通。", "甜": "语义：口味不能用来修饰进展，句意不通。", "窄": "搭配：“窄”形容空间，“进展”不能说窄。"}, "sentence_index": 6, "correct_answer": "重大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只小猫很重大，大家都喜欢它。", "explanation": "这里应该用〈可爱〉。重大不能用来形容小动物的样子。"}, {"text": "他走路时脚步很重大，大家都能听见。", "explanation": "这里应该用〈重〉。重大形容事情的分量或意义，不能形容脚步的轻重；脚步的轻重要用“重”。"}, {"text": "这颗星星很重大，夜里特别显眼。", "explanation": "这里应该用〈亮〉。重大不能用来形容星星的亮度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b84136e5-6a12-4d26-a4f5-7e2fd0c4690a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88318, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这项改革的意义十分的重大。", "corrected_sentence": "这项改革的意义十分重大。", "error_description": "错误在于“十分”和“重大”之间多加了“的”。“十分”修饰形容词时直接接形容词，应说“十分重大”，不能说“十分的重大”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b84136e5-6a12-4d26-a4f5-7e2fd0c4690a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88318, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的研究成果非常的重大。", "corrected_sentence": "他的研究成果非常重大。", "error_description": "错误在于“非常”和“重大”之间多加了“的”。“非常”修饰形容词时直接接形容词，应说“非常重大”，不能说“非常的重大”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b84136e5-6a12-4d26-a4f5-7e2fd0c4690a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
