INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88330, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "尝试；为了检验而做。", "primary_collocate": null, "pronunciation": "shì", "ipa": "ʂɻ̩˥˩", "syllable_count": 1, "sentences": [{"text": "工人先试一下机器能不能开。", "target_word": "试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "洗澡以前，先用手试水温。", "target_word": "试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师在台上试了试麦克风。", "target_word": "试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想试一试自己的力气有多大。", "target_word": "试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新手机买回来，先试一试好不好用。", "target_word": "试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这支笔能不能写，你试一试。", "target_word": "试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈用手试了试杯子热不热。", "target_word": "试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我把灯打开试了试，还是不亮。", "target_word": "试", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨师伸手试一下锅热不热。", "target_word": "试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他试着推了推门，门是锁着的。", "target_word": "试", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "试试", "label": "重叠"}, {"form": "试了", "label": "体标"}, {"form": "试着", "label": "体标"}, {"form": "试用", "label": "复合"}, {"form": "試", "label": "繁体"}], "register": "中性", "sense_fingerprint": "为了检验东西好不好用、热不热、能不能行而做一做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9239f1d7-ff0d-4c60-a806-0b26eef92068') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88330, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "试", "is_correct": true, "explanation": "试 shì（第四声），意思是为了检验东西好不好用而做一做。"}, {"text": "四", "is_correct": false, "explanation": "sì 与 shì 声母不同（s 与 sh），意思是数字四。"}, {"text": "时", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是时间。"}, {"text": "十", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是数字十。"}, {"text": "失", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，意思是失去。"}, {"text": "社", "is_correct": false, "explanation": "shè 与 shì 韵母不同（è 与 ì），意思是社会、团体。"}, {"text": "诗", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，意思是诗歌。"}], "explanations": {"试": "试 shì（第四声），意思是为了检验东西好不好用而做一做。", "四": "sì 与 shì 声母不同（s 与 sh），意思是数字四。", "时": "shí（第二声）与 shì（第四声）声调不同，意思是时间。", "十": "shí（第二声）与 shì（第四声）声调不同，意思是数字十。", "失": "shī（第一声）与 shì（第四声）声调不同，意思是失去。", "社": "shè 与 shì 韵母不同（è 与 ì），意思是社会、团体。", "诗": "shī（第一声）与 shì（第四声）声调不同，意思是诗歌。"}, "sentence_index": null, "correct_answer": "试"}, "level_3": {"options": [{"text": "试", "is_correct": true, "explanation": "试：为了检验机器能不能开而先做一做，与“一下”搭配。"}, {"text": "咬", "is_correct": false, "explanation": "语义：咬的对象多是食物，不能说“咬机器”，这里语义不通。"}, {"text": "睡", "is_correct": false, "explanation": "配价：睡是不及物动词，不能带“机器”作宾语。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：穿多用于衣物、鞋袜，不能说“穿机器”。"}], "explanations": {"试": "试：为了检验机器能不能开而先做一做，与“一下”搭配。", "咬": "语义：咬的对象多是食物，不能说“咬机器”，这里语义不通。", "睡": "配价：睡是不及物动词，不能带“机器”作宾语。", "穿": "搭配：穿多用于衣物、鞋袜，不能说“穿机器”。"}, "sentence_index": 0, "correct_answer": "试"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次旅行让我试到了很多乐趣。", "explanation": "这里应该用〈体验〉。试表示尝试或为检验而做，不表示亲身体会到某种乐趣，这里要用“体验”。"}, {"text": "他试到了妈妈的爱。", "explanation": "这里应该用〈感受〉。试表示尝试，不表示感受到，感受到爱要用“感受”。"}, {"text": "我试了很长时间的困难。", "explanation": "这里应该用〈经历〉。试不能表示遇到并承受困难，经历困难要用“经历”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0daa5daa-5bbd-4018-b8e4-a2d70022759f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88330, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "试", "is_correct": true, "explanation": "试 shì（第四声），意思是为了检验东西好不好用而做一做。"}, {"text": "石", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是石头。"}, {"text": "师", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，意思是老师。"}, {"text": "似", "is_correct": false, "explanation": "sì 与 shì 声母不同（s 与 sh），意思是像、似乎。"}, {"text": "使", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）声调不同，意思是使用、让。"}, {"text": "射", "is_correct": false, "explanation": "shè 与 shì 韵母不同（è 与 ì），意思是射击。"}], "explanations": {"试": "试 shì（第四声），意思是为了检验东西好不好用而做一做。", "石": "shí（第二声）与 shì（第四声）声调不同，意思是石头。", "师": "shī（第一声）与 shì（第四声）声调不同，意思是老师。", "似": "sì 与 shì 声母不同（s 与 sh），意思是像、似乎。", "使": "shǐ（第三声）与 shì（第四声）声调不同，意思是使用、让。", "射": "shè 与 shì 韵母不同（è 与 ì），意思是射击。"}, "sentence_index": null, "correct_answer": "试"}, "level_3": {"options": [{"text": "试", "is_correct": true, "explanation": "试：这里是用手检验杯子热不热，与“试了试”的用法相符。"}, {"text": "喝", "is_correct": false, "explanation": "语义：喝的对象是液体或食物，不能说“喝杯子”，这里语义不通。"}, {"text": "撕", "is_correct": false, "explanation": "语义：撕是把东西扯开，与“检验杯子热不热”的意思矛盾。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：摘多用于花果、叶子，不能与“杯子”搭配。"}], "explanations": {"试": "试：这里是用手检验杯子热不热，与“试了试”的用法相符。", "喝": "语义：喝的对象是液体或食物，不能说“喝杯子”，这里语义不通。", "撕": "语义：撕是把东西扯开，与“检验杯子热不热”的意思矛盾。", "摘": "搭配：摘多用于花果、叶子，不能与“杯子”搭配。"}, "sentence_index": 6, "correct_answer": "试"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这门试我复习了三天。", "explanation": "这里的“试”作“考试”解，是另一个义项，不是本义项“为了检验而做”。"}, {"text": "老师说这次试很难。", "explanation": "这里的“试”作“考试”解，是另一个义项，不是本义项“为了检验而做”。"}, {"text": "他的试考得很好，老师很高兴。", "explanation": "这里的“试”不能和“考”连用来指考试成绩，应说“他考得很好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0daa5daa-5bbd-4018-b8e4-a2d70022759f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88330, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他先试过一下门能不能开。", "corrected_sentence": "他先试一下门能不能开。", "error_description": "错误在体标：“试一下”已表示先试一试，后面不能再加“过”，应说“先试一下门”，不能说“先试过一下门”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0daa5daa-5bbd-4018-b8e4-a2d70022759f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88330, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈用手试得水热不热。", "corrected_sentence": "妈妈用手试了试水热不热。", "error_description": "错误在“试得”：表示先试一试的意思应说“试了试”（动词重叠加“了”），不能用“试得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0daa5daa-5bbd-4018-b8e4-a2d70022759f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
