INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88331, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "头是长在脖子上面的身体部分,上面有眼睛和嘴。", "primary_collocate": null, "pronunciation": "tóu", "ipa": "tʰou˧˥", "syllable_count": 1, "sentences": [{"text": "他的头很大，帽子都戴不上。", "target_word": "头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我一站起来，头就有点儿晕。", "target_word": "头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他转过头，看了我一眼。", "target_word": "头", "complexity_tier": "T3", "furigana": "tóu", "sentence_source": "generated"}, {"text": "孩子抬起头，笑着看妈妈。", "target_word": "头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把头靠在妈妈的肩膀上。", "target_word": "头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸用手摸了摸我的头。", "target_word": "头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他晕倒后，头磕在了桌角上。", "target_word": "头", "complexity_tier": "T3", "furigana": "tóu", "sentence_source": "generated"}, {"text": "他听了笑话，头往后一仰大笑起来。", "target_word": "头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我睡觉的时候喜欢把头放在左边。", "target_word": "头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的头撞在了窗户上，疼得叫起来。", "target_word": "头", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "頭", "label": "繁体"}, {"form": "头发", "label": "复合"}], "register": "中性", "sense_fingerprint": "头:长在脖子上面、有眼睛和嘴的身体部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T1: 3 words above tier T1 (max 2): 晕倒 (Zipf 3.57), 磕 (Zipf 3.67), 桌 (Zipf 3.79)','sentence 7 above tier T1: 3 words above tier T1 (max 2): 往后 (Zipf 3.85), 仰 (Zipf 3.21), 大笑 (Zipf 3.79)']::text[], 'b078f6bf-921d-40ec-bb52-91d878751ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88331, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "头", "is_correct": true, "explanation": "正确答案。tóu，指长在脖子上面、有眼睛和嘴的身体部分。"}, {"text": "偷", "is_correct": false, "explanation": "tōu（第一声）与 tóu（第二声）声调不同，意思是偷。"}, {"text": "透", "is_correct": false, "explanation": "tòu（第四声）与 tóu（第二声）声调不同，意思是透过、透明。"}, {"text": "楼", "is_correct": false, "explanation": "lóu 与 tóu 声母不同（l 与 t），意思是楼房。"}, {"text": "愁", "is_correct": false, "explanation": "chóu 与 tóu 声母不同（ch 与 t），意思是忧愁。"}], "explanations": {"头": "正确答案。tóu，指长在脖子上面、有眼睛和嘴的身体部分。", "偷": "tōu（第一声）与 tóu（第二声）声调不同，意思是偷。", "透": "tòu（第四声）与 tóu（第二声）声调不同，意思是透过、透明。", "楼": "lóu 与 tóu 声母不同（l 与 t），意思是楼房。", "愁": "chóu 与 tóu 声母不同（ch 与 t），意思是忧愁。"}, "sentence_index": null, "correct_answer": "头"}, "level_3": {"options": [{"text": "头", "is_correct": true, "explanation": "正确。“头很大”指头部的大小，帽子才戴不上。"}, {"text": "手", "is_correct": false, "explanation": "语义：帽子戴在头上，手的大小不影响戴帽子，句意不通。"}, {"text": "脚", "is_correct": false, "explanation": "语义：脚的大小与戴帽子无关，句意不通。"}, {"text": "书包", "is_correct": false, "explanation": "配价：“戴不上”的承受者是人的头部，书包不能被戴在身上，句意不通。"}], "explanations": {"头": "正确。“头很大”指头部的大小，帽子才戴不上。", "手": "语义：帽子戴在头上，手的大小不影响戴帽子，句意不通。", "脚": "语义：脚的大小与戴帽子无关，句意不通。", "书包": "配价：“戴不上”的承受者是人的头部，书包不能被戴在身上，句意不通。"}, "sentence_index": 0, "correct_answer": "头"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家养了两头鸭。", "explanation": "这里应该用〈只〉。“头”用于牛、猪等大牲畜，鸭要用“只”计数，不能用“头”。"}, {"text": "我买了三头鸡蛋。", "explanation": "这里应该用〈个〉。“头”作量词多用于牛、猪等大牲畜，鸡蛋要用“个”计数。"}, {"text": "墙角放着一只头。", "explanation": "这里应该用〈个〉。“头”作整体计数时用“个”，“只”多用于小动物或成对的东西，不能搭配“头”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b84136e5-6a12-4d26-a4f5-7e2fd0c4690a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88331, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "头", "is_correct": true, "explanation": "正确答案。tóu，指长在脖子上面、有眼睛和嘴的身体部分。"}, {"text": "仇", "is_correct": false, "explanation": "chóu 与 tóu 声母不同（ch 与 t），意思是仇恨、仇人。"}, {"text": "稠", "is_correct": false, "explanation": "chóu 与 tóu 声母不同（ch 与 t），意思是浓稠、稠密。"}, {"text": "绸", "is_correct": false, "explanation": "chóu 与 tóu 声母不同（ch 与 t），意思是丝绸。"}, {"text": "筹", "is_correct": false, "explanation": "chóu 与 tóu 声母不同（ch 与 t），意思是筹备、筹划。"}], "explanations": {"头": "正确答案。tóu，指长在脖子上面、有眼睛和嘴的身体部分。", "仇": "chóu 与 tóu 声母不同（ch 与 t），意思是仇恨、仇人。", "稠": "chóu 与 tóu 声母不同（ch 与 t），意思是浓稠、稠密。", "绸": "chóu 与 tóu 声母不同（ch 与 t），意思是丝绸。", "筹": "chóu 与 tóu 声母不同（ch 与 t），意思是筹备、筹划。"}, "sentence_index": null, "correct_answer": "头"}, "level_3": {"options": [{"text": "头", "is_correct": true, "explanation": "正确。“磕在了桌角上”的是人的头部，符合晕倒后的情境。"}, {"text": "心", "is_correct": false, "explanation": "语义：心脏在胸腔里，不会磕在桌角上，与“晕倒后”的情境不符。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子没有实体，不会磕碰桌角。"}, {"text": "灵魂", "is_correct": false, "explanation": "配价：“磕”需要有形的身体部位或物体作主语，灵魂不能磕碰。"}], "explanations": {"头": "正确。“磕在了桌角上”的是人的头部，符合晕倒后的情境。", "心": "语义：心脏在胸腔里，不会磕在桌角上，与“晕倒后”的情境不符。", "影子": "语义：影子没有实体，不会磕碰桌角。", "灵魂": "配价：“磕”需要有形的身体部位或物体作主语，灵魂不能磕碰。"}, "sentence_index": 6, "correct_answer": "头"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这次考试考了一头好成绩。", "explanation": "这里应该用〈个〉。“头”作量词多用于牛、猪等大牲畜，成绩要用“个”计数。"}, {"text": "我的眼镜一直放在一头桌子上。", "explanation": "这里应该用〈张〉。“头”不能用来计数桌子，桌子要用“张”计数。"}, {"text": "他买了一头苹果，准备明天吃。", "explanation": "这里应该用〈个〉。“头”不用于计数苹果，苹果要用“个”计数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b84136e5-6a12-4d26-a4f5-7e2fd0c4690a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88331, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他点了点头了，同意了我的建议。", "corrected_sentence": "他点了点头，同意了我的建议。", "error_description": "错误在于“点了点头”后多加了一个“了”。“点了点头”已带完成的意思，句中不需要再加“了”，应说“他点了点头，同意了我的建议。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b84136e5-6a12-4d26-a4f5-7e2fd0c4690a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88331, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他摇了摇头了，表示不同意。", "corrected_sentence": "他摇了摇头，表示不同意。", "error_description": "错误在于“摇了摇头”后多加了一个“了”。“摇了摇头”已带完成的意思，句中不需要再加“了”，应说“他摇了摇头，表示不同意。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b84136e5-6a12-4d26-a4f5-7e2fd0c4690a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
