INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88343, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "低分是考试得到的分数很少。", "primary_collocate": null, "pronunciation": "dī fēn", "ipa": "ti˥ fən˥", "syllable_count": 2, "sentences": [{"text": "这次考试我只得了低分。", "target_word": "低分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数学考了低分，我不想回家。", "target_word": "低分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他考了低分，妈妈没有生气。", "target_word": "低分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试得低分的同学要多复习。", "target_word": "低分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "低分不是失败，是学习的开始。", "target_word": "低分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟拿着低分的试卷回家了。", "target_word": "低分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说低分的同学可以再考一次。", "target_word": "低分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为没复习，他才考了低分。", "target_word": "低分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到试卷上的低分，她哭了。", "target_word": "低分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我希望英语不再考低分。", "target_word": "低分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "低分段", "label": "复合"}], "register": "口语", "sense_fingerprint": "考试中得到的很少的分数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccf90837-6f53-4998-80b9-e0ed350bbcb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88343, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "白眼", "is_correct": false, "explanation": "语义：“白眼”是别人冷淡的态度，不是考试能得到的结果。"}, {"text": "低分", "is_correct": true, "explanation": "正确：“只得了低分”指考试分数很少，与语境相合。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“得”不与“脾气”搭配，“得了脾气”句子不通。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨不是考试能得到的分数，“只得了雨”语义不合。"}], "explanations": {"白眼": "语义：“白眼”是别人冷淡的态度，不是考试能得到的结果。", "低分": "正确：“只得了低分”指考试分数很少，与语境相合。", "脾气": "搭配：“得”不与“脾气”搭配，“得了脾气”句子不通。", "雨": "语义：雨不是考试能得到的分数，“只得了雨”语义不合。"}, "sentence_index": 0, "correct_answer": "低分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我这次低分很高，妈妈很开心。", "explanation": "这里应该用〈考分〉。“考分”可以说高，“低分”本身表示分数低，不能说“很高”。"}, {"text": "我这次考了一条低分。", "explanation": "这里应该用〈个〉。“低分”是考试分数，计量用“个”；“条”用于细长的东西。"}, {"text": "我这次考了一座低分。", "explanation": "这里应该用〈个〉。“座”用于山、楼等大型固定的东西，不能计量分数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c3ca9f6-1c4f-477a-bb5a-7e1bcdade1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88343, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "饭菜", "is_correct": false, "explanation": "搭配：“老师说……的同学”要求修饰语是表示成绩的词，“饭菜”不能这样修饰。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器，“钢琴的同学可以再考一次”语义不合。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发是家具，与考试无关，句意不通。"}, {"text": "低分", "is_correct": true, "explanation": "正确：“低分的同学可以再考一次”指考试成绩低的同学，符合语境。"}], "explanations": {"饭菜": "搭配：“老师说……的同学”要求修饰语是表示成绩的词，“饭菜”不能这样修饰。", "钢琴": "语义：钢琴是乐器，“钢琴的同学可以再考一次”语义不合。", "沙发": "语义：沙发是家具，与考试无关，句意不通。", "低分": "正确：“低分的同学可以再考一次”指考试成绩低的同学，符合语境。"}, "sentence_index": 6, "correct_answer": "低分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的英语低分一直很好，妈妈很骄傲。", "explanation": "这里应该用〈成绩〉。“成绩”可以说好或坏，“低分”表示分数低，不能说“很好”。"}, {"text": "我的英语低分很喜欢唱歌。", "explanation": "这里应该用〈同学〉。低分是分数，不能“喜欢唱歌”，这个动作的主语须是人。"}, {"text": "他这次的低分很高，同学们都很佩服。", "explanation": "这里应该用〈得分〉。“得分”可以说高，“低分”表示分数低，与“很高”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c3ca9f6-1c4f-477a-bb5a-7e1bcdade1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
