INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88344, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "较低的分数。", "primary_collocate": null, "pronunciation": "dī fēn", "ipa": "ti˥ fən˥", "syllable_count": 2, "sentences": [{"text": "这个电影在网上只得了低分。", "target_word": "低分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛里裁判给他打了低分。", "target_word": "低分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "低分和高分只差几分。", "target_word": "低分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店得了低分，客人很少。", "target_word": "低分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的跳水动作得了低分。", "target_word": "低分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "低分不一定是坏事，可以让人进步。", "target_word": "低分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选手们看到低分，都很吃惊。", "target_word": "低分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次的低分让他很难过。", "target_word": "低分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "评委给这首歌打了低分。", "target_word": "低分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "低分的作品不能参加下一轮。", "target_word": "低分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "低分段", "label": "复合"}], "register": "中性", "sense_fingerprint": "评比、打分中较低的分数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccf90837-6f53-4998-80b9-e0ed350bbcb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88344, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "名字", "is_correct": false, "explanation": "搭配：“得”后接的应是可获得的评分，“得了名字”不成立。"}, {"text": "低分", "is_correct": true, "explanation": "正确：“只得了低分”指评分较低，与语境相合。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨不是评分，“只得了雨”不能表示任何评价，语义不合。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“得”不与“脾气”搭配，“得了脾气”句子不通。"}], "explanations": {"名字": "搭配：“得”后接的应是可获得的评分，“得了名字”不成立。", "低分": "正确：“只得了低分”指评分较低，与语境相合。", "雨": "语义：雨不是评分，“只得了雨”不能表示任何评价，语义不合。", "脾气": "搭配：“得”不与“脾气”搭配，“得了脾气”句子不通。"}, "sentence_index": 0, "correct_answer": "低分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的数学低分很喜欢跑步。", "explanation": "这里应该用〈同学〉。低分是分数，不能“喜欢跑步”，这个动作的主语须是人。"}, {"text": "裁判给他打了一条低分。", "explanation": "这里应该用〈个〉。“低分”是分数，计量用“个”；“条”用于细长的东西，不能计量分数。"}, {"text": "裁判给他打了一座低分。", "explanation": "这里应该用〈个〉。“座”用于山、楼等大型固定的东西，不能计量分数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c3ca9f6-1c4f-477a-bb5a-7e1bcdade1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88344, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "空气", "is_correct": false, "explanation": "语义：空气看不见，不能作为“看到”的对象。"}, {"text": "蚂蚁", "is_correct": false, "explanation": "语义：蚂蚁不会让选手都感到吃惊，句意不合语境。"}, {"text": "低分", "is_correct": true, "explanation": "正确：“看到低分”指看到评比中较低的分数，与语境相合。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道不能被看到，“看到味道”句意不通。"}], "explanations": {"空气": "语义：空气看不见，不能作为“看到”的对象。", "蚂蚁": "语义：蚂蚁不会让选手都感到吃惊，句意不合语境。", "低分": "正确：“看到低分”指看到评比中较低的分数，与语境相合。", "味道": "语义：味道不能被看到，“看到味道”句意不通。"}, "sentence_index": 6, "correct_answer": "低分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部电影得到了很高的低分，网上都在夸。", "explanation": "这里应该用〈评价〉。“评价”可以说高或低，“低分”本身表示分数低，不能与“很高”搭配。"}, {"text": "他这次的低分很好，老师很高兴。", "explanation": "这里应该用〈成绩〉。“成绩”可以说好或坏，“低分”表示分数低，不能说“很好”。"}, {"text": "他的低分很高，队友都很兴奋。", "explanation": "这里应该用〈得分〉。“得分”可以说高，“低分”指分数低，与“很高”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c3ca9f6-1c4f-477a-bb5a-7e1bcdade1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88344, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位选手拿到了一条低分。", "corrected_sentence": "这位选手拿到了一个低分。", "error_description": "错误：“低分”的量词用了“条”。正确应用“个”，“条”多用于细长的东西，不能计量分数。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c3ca9f6-1c4f-477a-bb5a-7e1bcdade1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88344, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我这次只了低分，很难过。", "corrected_sentence": "我这次只得了低分，很难过。", "error_description": "错误：“低分”前漏了动词“得”，写成“只了低分”。正确应为“只得了低分”，“得”与“低分”构成动宾，不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c3ca9f6-1c4f-477a-bb5a-7e1bcdade1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88347, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad91384-eeef-4b89-8621-5184273b70af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88347, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad91384-eeef-4b89-8621-5184273b70af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88347, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "其它是除了说过的这些以外,别的东西。", "primary_collocate": null, "pronunciation": "qí tā", "ipa": "tɕʰi˧˥ tʰa˥", "syllable_count": 2, "sentences": [{"text": "我只买了苹果，其它的东西明天再买。", "target_word": "其它", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上有书和笔，其它的都是妈妈的。", "target_word": "其它", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服太贵了，我想看看其它的。", "target_word": "其它", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "除了红色的，其它颜色我都不喜欢。", "target_word": "其它", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我先做作业，其它的事情等一下再说。", "target_word": "其它", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这三道菜很好吃，其它的我没有吃。", "target_word": "其它", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天只学这十个字，其它的下次再学。", "target_word": "其它", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你拿这本书吧，其它的留在这里。", "target_word": "其它", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他只喝水，不喝咖啡和其它饮料。", "target_word": "其它", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里只有一张床，其它东西都没有。", "target_word": "其它", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "其他", "label": "异形词"}], "register": "中性", "sense_fingerprint": "代词；指已说过的东西之外的别的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8be650e-3146-4abd-abb3-7556cce2575d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88347, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "其它", "is_correct": true, "explanation": "代词，指苹果之外的别的东西，与“只买了苹果”相合。"}, {"text": "别人", "is_correct": false, "explanation": "语义：“别人”指他人，句中的“我”买了东西，说“别人的东西明天再买”不通。"}, {"text": "大家", "is_correct": false, "explanation": "搭配：“只”限定范围，与“大家”的全体义不能搭配。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”是疑问代词，不表示“其余的”，无法承接“只买了苹果”。"}], "explanations": {"其它": "代词，指苹果之外的别的东西，与“只买了苹果”相合。", "别人": "语义：“别人”指他人，句中的“我”买了东西，说“别人的东西明天再买”不通。", "大家": "搭配：“只”限定范围，与“大家”的全体义不能搭配。", "谁": "语义：“谁”是疑问代词，不表示“其余的”，无法承接“只买了苹果”。"}, "sentence_index": 0, "correct_answer": "其它"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想要其它一杯咖啡。", "explanation": "这里应该用〈另一杯〉。其它指所说之外的事物，不能与“一杯”直接组合表示再添一个，应说“另一杯”。"}, {"text": "我会游泳，其它一项运动我还会跳舞。", "explanation": "这里应该用〈另外〉。其它是代词，不能直接与数量短语“一项运动”组合表示再加一项，应说“另外一项运动”。"}, {"text": "首先我们吃饭，其它我们去散步。", "explanation": "这里应该用〈其次〉。其它只指所说之外的别的事物，不表示先后顺序，此处应用“其次”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad91384-eeef-4b89-8621-5184273b70af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88347, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "其它", "is_correct": true, "explanation": "代词，指“这十个字”之外的别的字，与“下次再学”相合。"}, {"text": "自己", "is_correct": false, "explanation": "语义：“自己”指说话人自身，与“这十个字”之外的其余字不构成对照。"}, {"text": "人家", "is_correct": false, "explanation": "语域：“人家”口语色彩浓，且专指他人，不指学习的字，与书面语境不合。"}, {"text": "它们", "is_correct": false, "explanation": "语义：“它们”会指向“这十个字”，说今天学过的字下次再学，与句意相反。"}], "explanations": {"其它": "代词，指“这十个字”之外的别的字，与“下次再学”相合。", "自己": "语义：“自己”指说话人自身，与“这十个字”之外的其余字不构成对照。", "人家": "语域：“人家”口语色彩浓，且专指他人，不指学习的字，与书面语境不合。", "它们": "语义：“它们”会指向“这十个字”，说今天学过的字下次再学，与句意相反。"}, "sentence_index": 6, "correct_answer": "其它"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "其它一课我们要学汉字，语法以后再学。", "explanation": "这里应该用〈首先〉。其它不能直接与数量短语“一课”组合，也不表示先后顺序，此处应用“首先”。"}, {"text": "我想去公园，其它今天下雨了。", "explanation": "这里应该用〈可是〉。其它只指所说之外的别的事物，不能表示转折，两个分句的对比要用“可是”。"}, {"text": "这次考试我考得不错，其它一次我还得了奖。", "explanation": "这里应该用〈另外〉。其它是代词，不能直接与“一次”组合表示再添一件，补充时应用“另外”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad91384-eeef-4b89-8621-5184273b70af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88347, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我先做完作业，其它们的事情明天再做。", "corrected_sentence": "我先做完作业，其它的事情明天再做。", "error_description": "错误形式：“其它们”；正确形式：“其它”。“其它”是代词，后面不能加“们”表示复数，应直接说“其它的事情”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad91384-eeef-4b89-8621-5184273b70af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88347, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋里有一张桌子和两把椅子，其它地家具都是旧的。", "corrected_sentence": "屋里有一张桌子和两把椅子，其它的家具都是旧的。", "error_description": "错误形式：“其它地家具”；正确形式：“其它的家具”。“地”是状语标记，用于修饰动词、形容词；“其它”修饰名词“家具”，应用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad91384-eeef-4b89-8621-5184273b70af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
