INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88370, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed880c2a-f0c2-4fac-8d1e-932e3919a069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88370, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种黄色、质软、价值高的贵重金属。", "primary_collocate": null, "pronunciation": "huáng jīn", "ipa": "xwɑŋ˧˥ tɕin˥˥", "syllable_count": 2, "sentences": [{"text": "黄金是黄色的，很软，也很贵。", "target_word": "黄金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条项链是用黄金做的。", "target_word": "黄金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黄金的价格今年又涨了。", "target_word": "黄金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了一块黄金放在银行里。", "target_word": "黄金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黄金不容易生锈，所以可以放很多年。", "target_word": "黄金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金店里卖黄金，也卖银和玉。", "target_word": "黄金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的山里有很多黄金。", "target_word": "黄金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黄金比铁贵得多，也软得多。", "target_word": "黄金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黄金的密度很大，所以一小块也很重。", "target_word": "黄金", "complexity_tier": "T3", "furigana": "huáng jīn de mì dù hěn dà, suǒ yǐ yì xiǎo kuài yě hěn zhòng。", "sentence_source": "generated"}, {"text": "古时候的人常用黄金做钱。", "target_word": "黄金", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "黃金", "label": "繁体"}, {"form": "一块黄金", "label": "量词"}, {"form": "黄金时间", "label": "复合"}], "register": "中性", "sense_fingerprint": "黄色、质软、价值高的贵重金属", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e5d9128-ce98-4150-aea3-14a63da0a28d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88370, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "黄金", "is_correct": true, "explanation": "正确：黄金是黄色、质软、价值高的贵重金属，与句中的描述相符。"}, {"text": "白银", "is_correct": false, "explanation": "体貌：白银是银白色的，与句中“黄色”不符。"}, {"text": "铁", "is_correct": false, "explanation": "语义：铁坚硬而且便宜，与“很软，也很贵”不符。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃坚硬易碎，也不贵，与“很软，也很贵”相矛盾。"}], "explanations": {"黄金": "正确：黄金是黄色、质软、价值高的贵重金属，与句中的描述相符。", "白银": "体貌：白银是银白色的，与句中“黄色”不符。", "铁": "语义：铁坚硬而且便宜，与“很软，也很贵”不符。", "玻璃": "语义：玻璃坚硬易碎，也不贵，与“很软，也很贵”相矛盾。"}, "sentence_index": 0, "correct_answer": "黄金"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "阳光是黄金的，很温暖。", "explanation": "这里应该用〈金色〉。“黄金”是金属名词，不能用来形容颜色，描述颜色要用“金色”。"}, {"text": "这个保险箱里放着一只黄金。", "explanation": "这里应该用〈块〉。“黄金”作为贵重材料，量词用“块”；“只”多用于动物或成对物品中的一个，不能用来计量黄金。"}, {"text": "秋天的树叶是黄金的。", "explanation": "这里应该用〈金黄〉。“黄金”是金属名词，形容树叶的颜色要用“金黄”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed880c2a-f0c2-4fac-8d1e-932e3919a069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88370, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "黄金", "is_correct": true, "explanation": "正确：句中指黄色的贵重金属，山里可以出产黄金。"}, {"text": "大海", "is_correct": false, "explanation": "语义：山里不会有大海，与“山里”的语境相矛盾。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空在山的上方，不能说“山里有很多天空”。"}, {"text": "月亮", "is_correct": false, "explanation": "搭配：月亮只有一个，不能用“很多”来修饰。"}], "explanations": {"黄金": "正确：句中指黄色的贵重金属，山里可以出产黄金。", "大海": "语义：山里不会有大海，与“山里”的语境相矛盾。", "天空": "语义：天空在山的上方，不能说“山里有很多天空”。", "月亮": "搭配：月亮只有一个，不能用“很多”来修饰。"}, "sentence_index": 6, "correct_answer": "黄金"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "晚上八点是电视台的黄金时间。", "explanation": "此处“黄金”取比喻义“最好、最宝贵的”（如黄金时间），不是指金属，与本题的词义不符。"}, {"text": "他的人生正处在黄金时期。", "explanation": "此处“黄金”取比喻义“最好、最宝贵的”（如黄金时期），不是指金属，与本题的词义不符。"}, {"text": "这个月是我们店里的黄金季节。", "explanation": "此处“黄金”取比喻义“最好、最宝贵的”（如黄金季节），不是指金属，与本题的词义不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed880c2a-f0c2-4fac-8d1e-932e3919a069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88370, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "箱子里装着很多黄金们。", "corrected_sentence": "箱子里装着很多黄金。", "error_description": "词形错误：“黄金”是物质名词，不能加“们”表示复数。应说“很多黄金”；“们”一般只用于指人或有生命的名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed880c2a-f0c2-4fac-8d1e-932e3919a069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88370, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个箱子里装的是一只黄金。", "corrected_sentence": "那个箱子里装的是一块黄金。", "error_description": "量词错误：“黄金”作为贵重材料，量词应用“块”，不能用“只”（“只”多用于动物或成对物品中的一个）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed880c2a-f0c2-4fac-8d1e-932e3919a069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
