INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88374, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用来（做某事）。", "primary_collocate": null, "pronunciation": "yòng yǐ", "ipa": "jʊŋ⁵¹ i²¹⁴", "syllable_count": 2, "sentences": [{"text": "厨房里放着一个小秤，用以称量面粉。", "target_word": "用以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他带了一本笔记，用以记录每天的变化。", "target_word": "用以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们打了一口井，用以解决村里的用水问题。", "target_word": "用以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校开了一个网站，用以通知家长。", "target_word": "用以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把长尺用以测量桌子的大小。", "target_word": "用以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她写了一封信，用以感谢帮助过她的人。", "target_word": "用以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里种了很多树，用以挡住大风。", "target_word": "用以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间用以存放旧书。", "target_word": "用以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人养了几只鸡，用以补贴家用。", "target_word": "用以", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府拿出一笔钱，用以修路。", "target_word": "用以", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "用来做某事（书面）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b561781c-ab85-4690-8dcd-c94501bb469d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88374, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "扔掉", "is_correct": false, "explanation": "语义：小秤被扔掉就不能再用来称量面粉，与“放着一个小秤”的语境矛盾。"}, {"text": "用以", "is_correct": true, "explanation": "正确：“用以”表示用来做某事，后接动词“称量”。"}, {"text": "打碎", "is_correct": false, "explanation": "搭配：“打碎”后接的是器物，不能接“称量面粉”这样的动作。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”说的是修好东西，不能表示用秤来称量。"}], "explanations": {"扔掉": "语义：小秤被扔掉就不能再用来称量面粉，与“放着一个小秤”的语境矛盾。", "用以": "正确：“用以”表示用来做某事，后接动词“称量”。", "打碎": "搭配：“打碎”后接的是器物，不能接“称量面粉”这样的动作。", "修理": "语义：“修理”说的是修好东西，不能表示用秤来称量。"}, "sentence_index": 0, "correct_answer": "用以"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们走路时很小心，用以摔倒。", "explanation": "这里应该用〈以免〉。“用以”表示有意达到的目的，“以免”表示为了避免某种不好的结果；“用以摔倒”把摔倒说成了目的，不合常理。"}, {"text": "天气变热，用以冰箱里的东西坏了。", "explanation": "“用以”表示人有意达到的目的，不能用来说明天气造成的结果。"}, {"text": "他没来上课，用以生病了。", "explanation": "这里应该用〈因为〉。“用以”表示目的，不能表示原因。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbc2740c-b12d-4c61-95a2-f3c0c27fdb06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88374, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "砍掉", "is_correct": false, "explanation": "语义：树被砍掉就挡不住风了，与“种了很多树”的目的矛盾。"}, {"text": "浇灌", "is_correct": false, "explanation": "搭配：“浇灌”的对象是植物或土地，不能接“挡住大风”。"}, {"text": "拔掉", "is_correct": false, "explanation": "语义：树被拔掉就不能挡住大风，句子前后矛盾。"}, {"text": "用以", "is_correct": true, "explanation": "正确：“用以”表示目的，后接动词“挡住”。"}], "explanations": {"砍掉": "语义：树被砍掉就挡不住风了，与“种了很多树”的目的矛盾。", "浇灌": "搭配：“浇灌”的对象是植物或土地，不能接“挡住大风”。", "拔掉": "语义：树被拔掉就不能挡住大风，句子前后矛盾。", "用以": "正确：“用以”表示目的，后接动词“挡住”。"}, "sentence_index": 6, "correct_answer": "用以"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她用以担心考试，晚上睡不着。", "explanation": "“用以”表示有意达到的目的，“担心”是心理状态，不能作为有意达到的目的，这里应直接说“她担心考试”。"}, {"text": "妈妈用以生气，没有说话。", "explanation": "“用以”表示有意达到的目的，“生气”是情绪反应，不能作为有意的目的，这里应直接说“妈妈生气了”。"}, {"text": "我用以知道答案，所以没问老师。", "explanation": "“用以”表示有意达到的目的，“知道”是认知状态，不能作为目的，这里应去掉“用以”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbc2740c-b12d-4c61-95a2-f3c0c27fdb06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88374, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "书桌上放着一把尺子，用以着量纸的长度。", "corrected_sentence": "书桌上放着一把尺子，用以量纸的长度。", "error_description": "错误：“用以”后面加了“着”。“用以”后接动词时不带“着”，应去掉“着”，改为“用以量”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbc2740c-b12d-4c61-95a2-f3c0c27fdb06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88374, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校修了一道围墙，用以了挡住外面的噪音。", "corrected_sentence": "学校修了一道围墙，用以挡住外面的噪音。", "error_description": "错误：“用以”后面加了“了”。“用以”后接动词时不带“了”，应去掉“了”，改为“用以挡住”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbc2740c-b12d-4c61-95a2-f3c0c27fdb06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
