INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88378, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "旧时把一夜分为五更，三更相当于半夜（二十三点到次日一点）。", "primary_collocate": null, "pronunciation": "sān gēng", "ipa": "sɑn˥˥ kɤŋ˥˥", "syllable_count": 2, "sentences": [{"text": "旧时一夜分五更，三更是半夜。", "target_word": "三更", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "三更差不多是晚上十一点到一点。", "target_word": "三更", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在说的半夜，旧时叫三更。", "target_word": "三更", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一夜有五更，三更在中间。", "target_word": "三更", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书上说，他到三更才回家。", "target_word": "三更", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人说三更就是半夜十二点左右。", "target_word": "三更", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一更天刚黑，到三更就是半夜了。", "target_word": "三更", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她读了一个晚上的书，已经是三更了。", "target_word": "三更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古书里写着，三更时他还没睡。", "target_word": "三更", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过了三更，月亮已经高高挂着。", "target_word": "三更", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "三更天", "label": "复合"}, {"form": "三更半夜", "label": "复合"}], "register": "书面", "sense_fingerprint": "旧时五更计时中的第三更，约二十三点到一点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9239f1d7-ff0d-4c60-a806-0b26eef92068') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88378, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "三更", "is_correct": true, "explanation": "三更：旧时一夜分五更，三更就是半夜，与“是半夜”相符。"}, {"text": "中午", "is_correct": false, "explanation": "语义：中午是白天，与“是半夜”矛盾。"}, {"text": "天", "is_correct": false, "explanation": "搭配：“天”不是时刻，不能与“是半夜”搭配。"}, {"text": "五更", "is_correct": false, "explanation": "语义：五更是快天亮的时候，与“是半夜”矛盾。"}], "explanations": {"三更": "三更：旧时一夜分五更，三更就是半夜，与“是半夜”相符。", "中午": "语义：中午是白天，与“是半夜”矛盾。", "天": "搭配：“天”不是时刻，不能与“是半夜”搭配。", "五更": "语义：五更是快天亮的时候，与“是半夜”矛盾。"}, "sentence_index": 0, "correct_answer": "三更"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "三更天刚黑，村子里的灯就亮了。", "explanation": "这里应该用〈一更〉。三更是半夜（二十三点到次日一点），天刚黑时是一更，不能说“三更天刚黑”。"}, {"text": "三更一到，东方就泛白了，我们该起床了。", "explanation": "这里应该用〈五更〉。三更是半夜，东方泛白是天快亮的时候，应说〈五更〉。"}, {"text": "下午两点的三更，学校里很热闹。", "explanation": "这里把“三更”当作下午的时间来用。三更是半夜（二十三点到次日一点），下午的时间不能说“三更”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0daa5daa-5bbd-4018-b8e4-a2d70022759f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88378, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "三更", "is_correct": true, "explanation": "三更：旧时的第三更，就是半夜，与“到三更就是半夜了”相符。"}, {"text": "一更", "is_correct": false, "explanation": "语义：一更是天刚黑的时候，与“就是半夜”矛盾。"}, {"text": "日出", "is_correct": false, "explanation": "语义：日出是天亮的时候，与“就是半夜”矛盾。"}, {"text": "晌午", "is_correct": false, "explanation": "搭配：“晌午”指中午前后，不能用在“就是半夜了”这样的句子里。"}], "explanations": {"三更": "三更：旧时的第三更，就是半夜，与“到三更就是半夜了”相符。", "一更": "语义：一更是天刚黑的时候，与“就是半夜”矛盾。", "日出": "语义：日出是天亮的时候，与“就是半夜”矛盾。", "晌午": "搭配：“晌午”指中午前后，不能用在“就是半夜了”这样的句子里。"}, "sentence_index": 6, "correct_answer": "三更"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "三更到了，太阳正晒得人很热。", "explanation": "这里把“三更”当作中午来用。三更是半夜（二十三点到次日一点），太阳很晒的中午不能说“三更”，应说〈中午〉。"}, {"text": "我们走了三更路才到山顶。", "explanation": "这里把“三更”当作计量时长的单位。三更是半夜这一段时间（二十三点到次日一点），不能用来计量走路的时长，应说“走了几个小时的路”。"}, {"text": "他把书读完了三更。", "explanation": "这里把“三更”当作计量时长的单位。三更指半夜这一段时间，不能用来计算读书用了多久，应说“读了几个小时”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0daa5daa-5bbd-4018-b8e4-a2d70022759f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88378, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "旧时一夜分五更，半夜就是个三更。", "corrected_sentence": "旧时一夜分五更，半夜就是三更。", "error_description": "错误在“个”：三更是时刻，不能用量词“个”修饰，应说“半夜就是三更”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0daa5daa-5bbd-4018-b8e4-a2d70022759f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88378, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜深了，过了个三更，月亮还挂着。", "corrected_sentence": "夜深了，过了三更，月亮还挂着。", "error_description": "错误在“个”：三更是时刻，不能用量词“个”修饰，应说“过了三更”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0daa5daa-5bbd-4018-b8e4-a2d70022759f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
