INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88379, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "各地就是每一个地方。", "primary_collocate": null, "pronunciation": "gè dì", "ipa": "kɤ˥˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "雨季到了，各地都开始下雨。", "target_word": "各地", "complexity_tier": "T3", "furigana": "yǔ jì dào le, gè dì dōu kāi shǐ xià yǔ", "sentence_source": "generated"}, {"text": "各地的学校都在放假。", "target_word": "各地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电影在各地都很受欢迎。", "target_word": "各地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，各地的花都开了。", "target_word": "各地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们从各地来到北京开会。", "target_word": "各地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各地的小吃都很有名。", "target_word": "各地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天各地有大雨，请注意安全。", "target_word": "各地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走遍各地，找到了那本旧书。", "target_word": "各地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条新闻让各地的人都知道了。", "target_word": "各地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各地的商店晚上九点关门。", "target_word": "各地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "名词；每一个地方，强调各处无一例外", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8be650e-3146-4abd-abb3-7556cce2575d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88379, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "各地", "is_correct": true, "explanation": "名词，指每一个地方，与“雨季到了，都开始下雨”的全称义相合。"}, {"text": "某地", "is_correct": false, "explanation": "语义：“某地”指不确定的一处，与“都开始下雨”表示每一处的全称义冲突。"}, {"text": "大家", "is_correct": false, "explanation": "语义：“大家”指人，不指地方，不能作“都开始下雨”的主语。"}, {"text": "某个", "is_correct": false, "explanation": "语法：“某个”须接名词作定语，单独作主语不成立，无法承接“都”。"}], "explanations": {"各地": "名词，指每一个地方，与“雨季到了，都开始下雨”的全称义相合。", "某地": "语义：“某地”指不确定的一处，与“都开始下雨”表示每一处的全称义冲突。", "大家": "语义：“大家”指人，不指地方，不能作“都开始下雨”的主语。", "某个": "语法：“某个”须接名词作定语，单独作主语不成立，无法承接“都”。"}, "sentence_index": 0, "correct_answer": "各地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "春天到了，这个各地的花都开了。", "explanation": "这里应该用〈某地〉。各地指每一个地方，不能与“这个”这样的单指词连用；指一处应说“某地”。"}, {"text": "春天到了，各地的花只在一处开。", "explanation": "这里应该用〈某地〉。各地指每一个地方，与“只在一处开”的单一地点相矛盾，应改用“某地”。"}, {"text": "春天到了，我和各地一起赏了花。", "explanation": "这里应该用〈大家〉。各地指地方，不能作为一起赏花的人，应说“大家”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad91384-eeef-4b89-8621-5184273b70af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88379, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "各地", "is_correct": true, "explanation": "名词，指每一个地方，与“明天有大雨”的全称范围相合。"}, {"text": "一切", "is_correct": false, "explanation": "语法：“一切”指所有事物，不能作“有大雨”的处所主语，句子不通。"}, {"text": "大家", "is_correct": false, "explanation": "语法：“大家”指人，不能作“有大雨”的处所主语，句子不通。"}, {"text": "外国", "is_correct": false, "explanation": "语义：“外国”指国外，与“明天有大雨，请注意安全”的国内语境不符。"}], "explanations": {"各地": "名词，指每一个地方，与“明天有大雨”的全称范围相合。", "一切": "语法：“一切”指所有事物，不能作“有大雨”的处所主语，句子不通。", "大家": "语法：“大家”指人，不能作“有大雨”的处所主语，句子不通。", "外国": "语义：“外国”指国外，与“明天有大雨，请注意安全”的国内语境不符。"}, "sentence_index": 6, "correct_answer": "各地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家商店的各地分店都开在一处。", "explanation": "这里应该用〈某个〉。各地指每一个地方，与“开在一处”的单一地点矛盾，应指某一个地方。"}, {"text": "各地的商店都只在一家营业。", "explanation": "这里应该用〈本地〉。各地指每一个地方，与“只在一家营业”矛盾，应指某个地方。"}, {"text": "这种饮料只在一处卖，各地的商店都有。", "explanation": "这里应该用〈本地〉。各地与“只在一处卖”前后矛盾，应指某个地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad91384-eeef-4b89-8621-5184273b70af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88379, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场比赛的消息让各地们的球迷都兴奋起来了。", "corrected_sentence": "这场比赛的消息让各地的球迷都兴奋起来了。", "error_description": "错误形式：“各地们”；正确形式：“各地”。“各地”是处所词，不能加“们”表示复数，应说“各地的球迷”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad91384-eeef-4b89-8621-5184273b70af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88379, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明天各地有都大雨，请注意安全。", "corrected_sentence": "明天各地都有大雨，请注意安全。", "error_description": "错误形式：“有都大雨”；正确形式：“都有大雨”。“都”要放在动词“有”之前，表示每一处都如此。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ad91384-eeef-4b89-8621-5184273b70af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
