INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88385, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "不该是说这样做不对，不应该做。", "primary_collocate": null, "pronunciation": "bù gāi", "ipa": "pu˥˩ kaɪ̯˥", "syllable_count": 2, "sentences": [{"text": "你不该骗他。", "target_word": "不该", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他不该打人。", "target_word": "不该", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我不该说那些话。", "target_word": "不该", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子不该玩火。", "target_word": "不该", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你不该一个人去那里。", "target_word": "不该", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "开车时不该看手机。", "target_word": "不该", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他不该拿别人的东西。", "target_word": "不该", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这件事我不该告诉你。", "target_word": "不该", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你不该对妈妈大声说话。", "target_word": "不该", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师说，我们不该迟到。", "target_word": "不该", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "情态动词：不该+动作，表示这样做不对，是不应该的错误行为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e0c221-b8bd-4749-8a15-ebb972445d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88385, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不该", "is_correct": true, "explanation": "正确：“不该”指按道理不应当做某事。"}, {"text": "不改", "is_correct": false, "explanation": "gǎi（第三声）与 gāi（第一声）声调不同，意思是“不改”，即不做改变。"}, {"text": "不开", "is_correct": false, "explanation": "k 与 g 声母不同（送气与不送气），意思是“不开”，即不打开。"}, {"text": "不盖", "is_correct": false, "explanation": "gài（第四声）与 gāi（第一声）声调不同，意思是“不盖”，即不遮盖。"}], "explanations": {"不该": "正确：“不该”指按道理不应当做某事。", "不改": "gǎi（第三声）与 gāi（第一声）声调不同，意思是“不改”，即不做改变。", "不开": "k 与 g 声母不同（送气与不送气），意思是“不开”，即不打开。", "不盖": "gài（第四声）与 gāi（第一声）声调不同，意思是“不盖”，即不遮盖。"}, "sentence_index": null, "correct_answer": "不该"}, "level_3": {"options": [{"text": "不该", "is_correct": true, "explanation": "正确：“你不该骗他”表示这样做不对，句意合理。"}, {"text": "应该", "is_correct": false, "explanation": "语义：“应该骗他”表示应当去骗人，与骗人的道德语义冲突，句子不通。"}, {"text": "必须", "is_correct": false, "explanation": "语义：“必须骗他”要求去做错误的事，与劝阻的语义相反，句子不通。"}, {"text": "宜", "is_correct": false, "explanation": "语域：“宜”是书面语，与口语句“你……骗他”的语域不协调。"}], "explanations": {"不该": "正确：“你不该骗他”表示这样做不对，句意合理。", "应该": "语义：“应该骗他”表示应当去骗人，与骗人的道德语义冲突，句子不通。", "必须": "语义：“必须骗他”要求去做错误的事，与劝阻的语义相反，句子不通。", "宜": "语域：“宜”是书面语，与口语句“你……骗他”的语域不协调。"}, "sentence_index": 0, "correct_answer": "不该"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子饿了，不该吃饭。", "explanation": "这里应该用〈该〉。不该表示不应当；此处要说应当吃饭，应说“该吃饭”。"}, {"text": "这次考试我考得很好，不该及格。", "explanation": "这里应该用〈会〉。不该表示按情理不应当；考得很好应说“会及格”，“不该及格”与语境矛盾。"}, {"text": "天气很冷，我们不该穿外套。", "explanation": "这里应去掉“不”，应说“该穿外套”。不该表示不应当；天冷应穿外套，与语境相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e2401e-2f59-4ebb-9d07-980fe50a58c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88385, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不该", "is_correct": true, "explanation": "正确：“他不该拿别人的东西”表示这样做不对，句意合理。"}, {"text": "可以", "is_correct": false, "explanation": "语义：“可以拿别人的东西”表示允许，与“别人的东西”的语境冲突，句子不通。"}, {"text": "得", "is_correct": false, "explanation": "语义：“得拿别人的东西”表示必须去拿，与句中否定的劝阻语义相反。"}, {"text": "能", "is_correct": false, "explanation": "语义：“能拿别人的东西”表示能力，与句中的道德评价不符，句子不通。"}], "explanations": {"不该": "正确：“他不该拿别人的东西”表示这样做不对，句意合理。", "可以": "语义：“可以拿别人的东西”表示允许，与“别人的东西”的语境冲突，句子不通。", "得": "语义：“得拿别人的东西”表示必须去拿，与句中否定的劝阻语义相反。", "能": "语义：“能拿别人的东西”表示能力，与句中的道德评价不符，句子不通。"}, "sentence_index": 6, "correct_answer": "不该"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下雨了，你不该带伞。", "explanation": "这里应去掉“不”，应说“该带伞”。不该表示不应当；下雨时带伞是应当的，与语境相反。"}, {"text": "学生都到齐了，老师不该开始上课。", "explanation": "这里应去掉“不”，应说“该开始上课”。不该表示不应当；人已到齐，应当开始上课，与语境相反。"}, {"text": "你累了，不该躺下休息。", "explanation": "这里应去掉“不”，应说“该躺下休息”。不该表示不应当；累了应当休息，与语境相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e2401e-2f59-4ebb-9d07-980fe50a58c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88385, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你不该了骗朋友。", "corrected_sentence": "你不该骗朋友。", "error_description": "错误：“不该了骗朋友”。正确：“不该骗朋友”。“不该”是情态动词，后面不能直接加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e2401e-2f59-4ebb-9d07-980fe50a58c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88385, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他不该着拿朋友的书。", "corrected_sentence": "他不该拿朋友的书。", "error_description": "错误：“不该着拿”。正确：“不该拿”。“着”表示持续，不能用在情态动词“不该”与动词之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e2401e-2f59-4ebb-9d07-980fe50a58c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
