INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88386, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "不应该；不应当。", "primary_collocate": null, "pronunciation": "bù gāi", "ipa": "pu˥˩ kaɪ̯˥", "syllable_count": 2, "sentences": [{"text": "天气很冷，你不该穿这么少。", "target_word": "不该", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你生病了，不该喝冰水。", "target_word": "不该", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太晚了，你不该一个人回家。", "target_word": "不该", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这么贵的东西，我们不该买。", "target_word": "不该", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他还小，不该做这么重的事。", "target_word": "不该", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你已经吃很多了，不该再吃了。", "target_word": "不该", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你累了，今天不该再工作了。", "target_word": "不该", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说他不该喝酒。", "target_word": "不该", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "不该去的地方，我们就别去。", "target_word": "不该", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他还没好，不该上课。", "target_word": "不该", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "情态动词：不该+动作，表示按情理或情况不应当这样做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e0c221-b8bd-4749-8a15-ebb972445d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88386, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不该", "is_correct": true, "explanation": "正确：“不该”表示按情理不应当这样做。"}, {"text": "不改", "is_correct": false, "explanation": "gǎi（第三声）与 gāi（第一声）声调不同，意思是“不改”，即不做改变。"}, {"text": "不开", "is_correct": false, "explanation": "k 与 g 声母不同（送气与不送气），意思是“不开”，即不打开。"}, {"text": "不盖", "is_correct": false, "explanation": "gài（第四声）与 gāi（第一声）声调不同，意思是“不盖”，即不遮盖。"}], "explanations": {"不该": "正确：“不该”表示按情理不应当这样做。", "不改": "gǎi（第三声）与 gāi（第一声）声调不同，意思是“不改”，即不做改变。", "不开": "k 与 g 声母不同（送气与不送气），意思是“不开”，即不打开。", "不盖": "gài（第四声）与 gāi（第一声）声调不同，意思是“不盖”，即不遮盖。"}, "sentence_index": null, "correct_answer": "不该"}, "level_3": {"options": [{"text": "不该", "is_correct": true, "explanation": "正确：“天气很冷，你不该穿这么少”表示按情理不应当，句意合理。"}, {"text": "应该", "is_correct": false, "explanation": "语义：“天气很冷，你应该穿这么少”前后矛盾，与“天气很冷”的语境冲突。"}, {"text": "必须", "is_correct": false, "explanation": "语义：“必须穿这么少”要求这样做，与“天气很冷”的常理相反，句子不通。"}, {"text": "理应", "is_correct": false, "explanation": "语域：“理应”是书面语，与口语句的语域不协调，且语义与“天气很冷”的劝阻相反。"}], "explanations": {"不该": "正确：“天气很冷，你不该穿这么少”表示按情理不应当，句意合理。", "应该": "语义：“天气很冷，你应该穿这么少”前后矛盾，与“天气很冷”的语境冲突。", "必须": "语义：“必须穿这么少”要求这样做，与“天气很冷”的常理相反，句子不通。", "理应": "语域：“理应”是书面语，与口语句的语域不协调，且语义与“天气很冷”的劝阻相反。"}, "sentence_index": 0, "correct_answer": "不该"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "饭已经做好了，我不该吃饭。", "explanation": "这里应去掉“不”，应说“该吃饭”。不该表示不应当；饭做好了应当吃，与语境相反。"}, {"text": "你渴了，不该喝水。", "explanation": "这里应去掉“不”，应说“该喝水”。不该表示不应当；渴了应当喝水，与语境相反。"}, {"text": "这么冷的天，你不该多穿一件衣服。", "explanation": "这里应该用〈不妨〉。不妨表示建议尝试；不该表示按情理不应当，两者语义相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e2401e-2f59-4ebb-9d07-980fe50a58c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88386, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不该", "is_correct": true, "explanation": "正确：“你累了，今天不该再工作了”表示按情理不应当，句意合理。"}, {"text": "可以", "is_correct": false, "explanation": "语义：“可以再工作了”表示允许，与“你累了”的劝阻语境相反。"}, {"text": "得", "is_correct": false, "explanation": "语义：“得再工作了”表示必须，与“你累了”的劝阻语境相反，句子不通。"}, {"text": "能", "is_correct": false, "explanation": "语义：“能再工作了”强调能力，与“你累了”的语境冲突，句子不通。"}], "explanations": {"不该": "正确：“你累了，今天不该再工作了”表示按情理不应当，句意合理。", "可以": "语义：“可以再工作了”表示允许，与“你累了”的劝阻语境相反。", "得": "语义：“得再工作了”表示必须，与“你累了”的劝阻语境相反，句子不通。", "能": "语义：“能再工作了”强调能力，与“你累了”的语境冲突，句子不通。"}, "sentence_index": 6, "correct_answer": "不该"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你饿了，今天不该吃午饭。", "explanation": "这里应去掉“不”，应说“该吃午饭”。不该表示不应当；饿了应当吃饭，与语境相反。"}, {"text": "客人来了，主人不该开门。", "explanation": "这里应去掉“不”，应说“该开门”。不该表示不应当；客人来了应当开门，与语境相反。"}, {"text": "车快没油了，你不该去加油。", "explanation": "这里应去掉“不”，应说“该去加油”。不该表示不应当；车快没油应当去加油，与语境相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e2401e-2f59-4ebb-9d07-980fe50a58c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88386, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天气很冷，你不该了穿这么薄。", "corrected_sentence": "天气很冷，你不该穿这么薄。", "error_description": "错误：“不该了穿”。正确：“不该穿”。“不该”是情态动词，后面不能直接加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e2401e-2f59-4ebb-9d07-980fe50a58c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88386, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他病了，今天不该着上班。", "corrected_sentence": "他病了，今天不该上班。", "error_description": "错误：“不该着上班”。正确：“不该上班”。“着”表示持续，不能直接放在情态动词“不该”后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e2401e-2f59-4ebb-9d07-980fe50a58c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
