INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88411, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "原处是东西以前在的那个地方。", "primary_collocate": null, "pronunciation": "yuán chù", "ipa": "ɥɛn˧˥ ʈʂʰu˥˩", "syllable_count": 2, "sentences": [{"text": "书不在原处，我找不到它。", "target_word": "原处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用完东西，请放回原处。", "target_word": "原处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫跑出去玩，后来又回到原处。", "target_word": "原处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图还在原处，没有人动过。", "target_word": "原处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杯子拿走以后，原处是空的。", "target_word": "原处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把手机放回原处就去睡觉了。", "target_word": "原处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他等了很久，还是站在原处不动。", "target_word": "原处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家以后，我把桌子又搬回了原处。", "target_word": "原处", "complexity_tier": "T3", "furigana": "bān jiā yǐ hòu, wǒ bǎ zhuō zi yòu bān huí le yuán chù。", "sentence_source": "generated"}, {"text": "这把伞放在原处，明天还要用。", "target_word": "原处", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们收拾完，每样东西都在原处。", "target_word": "原处", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "原處", "label": "繁体"}], "register": "中性", "sense_fingerprint": "东西以前所在的那个地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e5d9128-ce98-4150-aea3-14a63da0a28d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88411, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "原处", "is_correct": true, "explanation": "正确：原处指东西以前所在的那个地方。"}, {"text": "远处", "is_correct": false, "explanation": "远处（yuǎn chù）与原处（yuán chù）第一音节声调不同（第三声与第二声），意思是远的地方。"}, {"text": "原初", "is_correct": false, "explanation": "原初（yuán chū）与原处（yuán chù）末音节声调不同（第一声与第四声），意思是最开始的时候。"}, {"text": "远出", "is_correct": false, "explanation": "远出（yuǎn chū）与原处两个音节的声调都不同，意思是到远方去。"}], "explanations": {"原处": "正确：原处指东西以前所在的那个地方。", "远处": "远处（yuǎn chù）与原处（yuán chù）第一音节声调不同（第三声与第二声），意思是远的地方。", "原初": "原初（yuán chū）与原处（yuán chù）末音节声调不同（第一声与第四声），意思是最开始的时候。", "远出": "远出（yuǎn chū）与原处两个音节的声调都不同，意思是到远方去。"}, "sentence_index": null, "correct_answer": "原处"}, "level_3": {"options": [{"text": "原处", "is_correct": true, "explanation": "正确：原处指东西以前所在的地方，与“找不到”的语境相符。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：书不会放在海洋里，与“不在”后的处所语境不合。"}, {"text": "天空", "is_correct": false, "explanation": "语义：书不会放在天空里，与句中的语境不合。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“不在”后接处所，“时间”不是处所，不能说“书不在时间”。"}], "explanations": {"原处": "正确：原处指东西以前所在的地方，与“找不到”的语境相符。", "海洋": "语义：书不会放在海洋里，与“不在”后的处所语境不合。", "天空": "语义：书不会放在天空里，与句中的语境不合。", "时间": "搭配：“不在”后接处所，“时间”不是处所，不能说“书不在时间”。"}, "sentence_index": 0, "correct_answer": "原处"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这半年他的工作一直在原处踏步。", "explanation": "这里应该用〈原地〉。“原地踏步”是固定说法，比喻没有进步；“原处”只指地点，不能和“踏步”搭配。"}, {"text": "这件毛衣洗后仍保持原处，没有缩水。", "explanation": "这里应该用〈原样〉。“原处”指地点，衣物洗后状态不变要说“保持原样”，不能说“保持原处”。"}, {"text": "这件事的原处让我们都很担心。", "explanation": "这里应该用〈原因〉。“原处”指东西原来的地方，不能用来指事情的起因。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed880c2a-f0c2-4fac-8d1e-932e3919a069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88411, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原处", "is_correct": true, "explanation": "正确：原处指原来的地方，与“站在”相符。"}, {"text": "故事", "is_correct": false, "explanation": "语义：故事是抽象内容，人不能“站在”故事上。"}, {"text": "眼泪", "is_correct": false, "explanation": "语义：眼泪是液体，人不能“站在”眼泪上。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“站在”后接处所，“声音”不是处所，不能说“站在声音”。"}], "explanations": {"原处": "正确：原处指原来的地方，与“站在”相符。", "故事": "语义：故事是抽象内容，人不能“站在”故事上。", "眼泪": "语义：眼泪是液体，人不能“站在”眼泪上。", "声音": "搭配：“站在”后接处所，“声音”不是处所，不能说“站在声音”。"}, "sentence_index": 6, "correct_answer": "原处"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们收拾完，每样东西都在一张原处。", "explanation": "量词错误：“张”多用于平面的东西，不能用来计量“原处”。"}, {"text": "孩子们收拾完，每样东西都在一颗原处。", "explanation": "量词错误：“颗”多用于粒状或小而圆的东西，不能用来计量“原处”。"}, {"text": "孩子们收拾完，每样东西都在一把原处。", "explanation": "量词错误：“把”多用于有柄的器具或椅子等，不能用来计量“原处”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed880c2a-f0c2-4fac-8d1e-932e3919a069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88411, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "东西一直在原处在。", "corrected_sentence": "东西一直在原处。", "error_description": "多余成分：句末多加了“在”，表示位置只说“在原处”，“原处”后不能再加“在”，应说“东西一直在原处”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed880c2a-f0c2-4fac-8d1e-932e3919a069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88411, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把它搬回了在原处。", "corrected_sentence": "她把它搬回了原处。", "error_description": "多余成分：“搬回了”后直接接处所“原处”，不需要“在”；多加“在”是错误，应说“搬回了原处”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed880c2a-f0c2-4fac-8d1e-932e3919a069') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
