INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88424, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "经历的时间;多用于固定说法,如「为时已晚」「为时不远」。", "primary_collocate": null, "pronunciation": "wéi shí", "ipa": "weɪ˧˥ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "现在开始学习，还不算为时已晚。", "target_word": "为时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他后悔没早点努力，可惜为时已晚。", "target_word": "为时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛才开始，现在说谁会赢还为时尚早。", "target_word": "为时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要你肯努力，哪怕现在才开始，也不算为时已晚。", "target_word": "为时", "complexity_tier": "T3", "furigana": "zhǐ yào nǐ kěn nǔlì, nǎpà xiànzài cái kāishǐ, yě bú suàn wèi shí yǐ wǎn.", "sentence_source": "generated"}, {"text": "比赛才开始，现在下结论为时过早。", "target_word": "为时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我相信，我们团聚的日子为时不远。", "target_word": "为时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "等你发现问题，恐怕为时已晚。", "target_word": "为时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习新东西永远不会为时已晚。", "target_word": "为时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想改变自己，什么时候开始都不算为时已晚。", "target_word": "为时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在才想到复习，是不是为时已晚了？", "target_word": "为时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "為時", "label": "繁体"}], "register": "书面", "sense_fingerprint": "为时:经历的时间,多用于为时已晚、为时不远等固定说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b078f6bf-921d-40ec-bb52-91d878751ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88424, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "为时", "is_correct": true, "explanation": "为时在“为时已晚”中指经历的时间，是正确答案。"}, {"text": "委实", "is_correct": false, "explanation": "委实（wěi shí）与为时（wéi shí）第一音节声调不同，意思是确实，不用于“已晚”的说法。"}, {"text": "卫视", "is_correct": false, "explanation": "卫视（wèi shì）与为时（wéi shí）两个音节声调都不同，指卫星电视频道。"}, {"text": "威势", "is_correct": false, "explanation": "威势（wēi shì）与为时（wéi shí）两个音节声调都不同，意思是威严的气势。"}, {"text": "为使", "is_correct": false, "explanation": "为使（wéi shǐ）与为时（wéi shí）第二音节声调不同，意思是为了让。"}], "explanations": {"为时": "为时在“为时已晚”中指经历的时间，是正确答案。", "委实": "委实（wěi shí）与为时（wéi shí）第一音节声调不同，意思是确实，不用于“已晚”的说法。", "卫视": "卫视（wèi shì）与为时（wéi shí）两个音节声调都不同，指卫星电视频道。", "威势": "威势（wēi shì）与为时（wéi shí）两个音节声调都不同，意思是威严的气势。", "为使": "为使（wéi shǐ）与为时（wéi shí）第二音节声调不同，意思是为了让。"}, "sentence_index": null, "correct_answer": "为时"}, "level_3": {"options": [{"text": "为时", "is_correct": true, "explanation": "为时是名词，指经历的时间，此处用于“为时已晚”的固定说法。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指岁数，“年龄已晚”说不通，此处说的是经历的时间。"}, {"text": "人数", "is_correct": false, "explanation": "搭配：“人数”不能用“已晚”来形容。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”与“已晚”搭配不当。"}], "explanations": {"为时": "为时是名词，指经历的时间，此处用于“为时已晚”的固定说法。", "年龄": "语义：“年龄”指岁数，“年龄已晚”说不通，此处说的是经历的时间。", "人数": "搭配：“人数”不能用“已晚”来形容。", "体重": "搭配：“体重”与“已晚”搭配不当。"}, "sentence_index": 0, "correct_answer": "为时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服为时已晚。", "explanation": "这里应该用〈过时〉：这件衣服过时了。「为时已晚」说的是做某事太迟，不能用来形容物品落后。"}, {"text": "他刚开始学习，为时已晚。", "explanation": "这里应该用〈还来得及〉：他刚开始学习，还来得及。「为时已晚」表示太晚，刚开始时不能用。"}, {"text": "他的成绩为时很好。", "explanation": "这里应该用〈优秀〉：他的成绩很优秀。「为时」只表示经历的时间，不能用来形容成绩的好坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b84136e5-6a12-4d26-a4f5-7e2fd0c4690a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88424, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "为时", "is_correct": true, "explanation": "为时是名词，指经历的时间，此处用于“为时已晚”的固定说法。"}, {"text": "成绩", "is_correct": false, "explanation": "语义：“成绩”指学习的结果，不能说“成绩已晚”。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“体温”不能用“已晚”来形容。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”与“已晚”搭配不通，此处说不通。"}], "explanations": {"为时": "为时是名词，指经历的时间，此处用于“为时已晚”的固定说法。", "成绩": "语义：“成绩”指学习的结果，不能说“成绩已晚”。", "体温": "搭配：“体温”不能用“已晚”来形容。", "身高": "搭配：“身高”与“已晚”搭配不通，此处说不通。"}, "sentence_index": 6, "correct_answer": "为时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我为时三天看完了这本书。", "explanation": "这里应该用〈花〉：我花了三天看完这本书。「为时」作名词只用于「为时已晚」「为时不远」等固定说法，不能作谓语。"}, {"text": "这条路为时三公里。", "explanation": "这里应该用〈有〉：这条路有三公里长。为时只用于经历的时间，不用来说路的长度。"}, {"text": "离考试还有很久，为时已晚。", "explanation": "这里应该用〈还来得及〉：离考试还有很久，还来得及。“为时已晚”表示太晚，时间充裕时不能用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b84136e5-6a12-4d26-a4f5-7e2fd0c4690a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88424, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "现在下结论，还为时已早。", "corrected_sentence": "现在下结论，还为时尚早。", "error_description": "错误形式：“为时已早”。正确形式：“为时尚早”。“已”表示已经，与“早”矛盾；表示时间还早要用“尚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b84136e5-6a12-4d26-a4f5-7e2fd0c4690a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88424, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "事情拖到现在，为时尚晚。", "corrected_sentence": "事情拖到现在，为时已晚。", "error_description": "错误形式：“为时尚晚”。正确形式：“为时已晚”。“已晚”表示已经太晚；“尚”表示仍然，不能与“晚”搭配表示太晚。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b84136e5-6a12-4d26-a4f5-7e2fd0c4690a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
