INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88434, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "天主教、东正教中主持宗教仪式的神职人员。", "primary_collocate": null, "pronunciation": "shén fu", "ipa": "ʂən˧˥ fu", "syllable_count": 2, "sentences": [{"text": "神父在教堂里主持仪式。", "target_word": "神父", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位神父每个星期天都讲话。", "target_word": "神父", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老神父给孩子们讲故事。", "target_word": "神父", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "结婚那天，神父问了他们几句话。", "target_word": "神父", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神父穿着黑色的长衣服。", "target_word": "神父", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想去教堂找神父聊聊。", "target_word": "神父", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神父为大家祈祷。", "target_word": "神父", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位神父在小镇住了三十年。", "target_word": "神父", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神父说，人要有爱心。", "target_word": "神父", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的神父帮助了穷人。", "target_word": "神父", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "老神父", "label": "复合"}], "register": "正式", "sense_fingerprint": "天主教、东正教中主持宗教仪式的神职人员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccf90837-6f53-4998-80b9-e0ed350bbcb8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88434, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "神父", "is_correct": true, "explanation": "神父 shén fu：天主教、东正教中主持宗教仪式的神职人员，是正确答案。"}, {"text": "生父", "is_correct": false, "explanation": "生父（shēng fù）与 shén fu 的韵母和声调都不同，意思是亲生父亲，不是神职人员。"}, {"text": "圣父", "is_correct": false, "explanation": "圣父（shèng fù）与 shén fu 的韵母和声调都不同，指天主教中三位一体的第一位。"}, {"text": "神符", "is_correct": false, "explanation": "神符（shén fú）第二个音节声调不同（fú 与 fu），意思是画有神秘文字或图形的符。"}], "explanations": {"神父": "神父 shén fu：天主教、东正教中主持宗教仪式的神职人员，是正确答案。", "生父": "生父（shēng fù）与 shén fu 的韵母和声调都不同，意思是亲生父亲，不是神职人员。", "圣父": "圣父（shèng fù）与 shén fu 的韵母和声调都不同，指天主教中三位一体的第一位。", "神符": "神符（shén fú）第二个音节声调不同（fú 与 fu），意思是画有神秘文字或图形的符。"}, "sentence_index": null, "correct_answer": "神父"}, "level_3": {"options": [{"text": "神父", "is_correct": true, "explanation": "正确：神父是天主教、东正教中主持仪式的神职人员，符合“教堂里主持仪式”。"}, {"text": "和尚", "is_correct": false, "explanation": "语义：和尚是佛教僧人，不在教堂主持仪式，与“教堂里”的语境冲突。"}, {"text": "厨房", "is_correct": false, "explanation": "配价：“主持仪式”要求有人作施事，厨房不能主持仪式。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师不主持宗教仪式，与“主持仪式”的语境冲突。"}], "explanations": {"神父": "正确：神父是天主教、东正教中主持仪式的神职人员，符合“教堂里主持仪式”。", "和尚": "语义：和尚是佛教僧人，不在教堂主持仪式，与“教堂里”的语境冲突。", "厨房": "配价：“主持仪式”要求有人作施事，厨房不能主持仪式。", "厨师": "语义：厨师不主持宗教仪式，与“主持仪式”的语境冲突。"}, "sentence_index": 0, "correct_answer": "神父"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们学校来了一只神父。", "explanation": "这里应该用〈位〉。神父指人，量词用“位”；“只”一般用于动物，不能用来数人。"}, {"text": "寺庙里住着一位老神父，他每天吃素。", "explanation": "这里应该用〈和尚〉。神父是天主教、东正教的神职人员；寺庙里的佛教僧人称和尚。"}, {"text": "道观里的老神父每天早上打扫院子。", "explanation": "这里应该用〈道士〉。神父属于基督教系统；道观里的道教人员称道士。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c3ca9f6-1c4f-477a-bb5a-7e1bcdade1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88434, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "神父", "is_correct": true, "explanation": "正确：神父是主持宗教仪式的神职人员，可以为大家祈祷。"}, {"text": "作家", "is_correct": false, "explanation": "语义：作家的职业不包括为大家祈祷，与语境冲突。"}, {"text": "邮递员", "is_correct": false, "explanation": "语义：邮递员的职责是送信，不能为大家祈祷。"}, {"text": "小子", "is_correct": false, "explanation": "语域：“小子”是口语，带轻蔑色彩，不适用于庄重的祈祷语境。"}], "explanations": {"神父": "正确：神父是主持宗教仪式的神职人员，可以为大家祈祷。", "作家": "语义：作家的职业不包括为大家祈祷，与语境冲突。", "邮递员": "语义：邮递员的职责是送信，不能为大家祈祷。", "小子": "语域：“小子”是口语，带轻蔑色彩，不适用于庄重的祈祷语境。"}, "sentence_index": 6, "correct_answer": "神父"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天上的神父住在云里。", "explanation": "这里应该用〈神仙〉。神父指人间主持仪式的神职人员，不指天上的神仙。"}, {"text": "清真寺里的神父每天带领大家祈祷。", "explanation": "这里应该用〈阿訇〉。神父是天主教、东正教的神职人员；清真寺里的伊斯兰教教职人员称阿訇。"}, {"text": "她是一位神父，每个星期天在教堂帮忙。", "explanation": "这里应该用〈修女〉。神父指男性神职人员，女性的宗教人员称修女，不能用神父指女性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c3ca9f6-1c4f-477a-bb5a-7e1bcdade1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88434, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们请了三只神父来主持婚礼。", "corrected_sentence": "他们请了三位神父来主持婚礼。", "error_description": "错误形式：“三只神父”。“只”多用于动物，不用于人；神父指人，应用量词“位”。正确形式：“三位神父”，把量词“只”换成“位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c3ca9f6-1c4f-477a-bb5a-7e1bcdade1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
