INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88453, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "私人", "is_correct": true, "explanation": "反义：「公共」指属于大家，与之相对的是「私人」，指属于个人。"}, {"text": "美丽", "is_correct": false, "explanation": "无关：「美丽」形容外貌好看，与「公共」没有反义关系。"}, {"text": "寒冷", "is_correct": false, "explanation": "无关：「寒冷」形容温度，与「公共」不构成反义。"}, {"text": "聪明", "is_correct": false, "explanation": "无关：「聪明」形容智力，与「公共」不构成反义。"}], "correct_answer": "私人", "explanations": {"私人": "反义：「公共」指属于大家，与之相对的是「私人」，指属于个人。", "美丽": "无关：「美丽」形容外貌好看，与「公共」没有反义关系。", "寒冷": "无关：「寒冷」形容温度，与「公共」不构成反义。", "聪明": "无关：「聪明」形容智力，与「公共」不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac88911d-0e7f-4e56-9f4e-77105f58f5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
