INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88453, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "公共是说大家都可以用,不是只给一个人的。", "primary_collocate": null, "pronunciation": "gōng gòng", "ipa": "kʊŋ˥ kʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这个公园是公共的，谁都可以进去。", "target_word": "公共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公共电话在楼下，大家都能用。", "target_word": "公共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的公共椅子可以随便坐。", "target_word": "公共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要把公共的东西带回家。", "target_word": "公共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校门口有一个公共厕所。", "target_word": "公共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台电脑是公共的，不是我一个人的。", "target_word": "公共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆的书是公共的，要爱护它们。", "target_word": "公共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在公共地方，请小声说话。", "target_word": "公共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公共自行车很方便，一小时只要一块钱。", "target_word": "公共", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把公共的杯子洗干净了。", "target_word": "公共", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "公共汽车", "label": "复合"}, {"form": "公共场所", "label": "复合"}], "register": "中性", "sense_fingerprint": "大家都可以使用、不属于某一个人的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7b718ac-c4e5-459d-b8b0-a4e451916030') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88453, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公共", "is_correct": true, "explanation": "正确：「公共」指大家都可以使用，与「谁都可以进去」相符。"}, {"text": "私有", "is_correct": false, "explanation": "语义：「私有」指属于个人，与「谁都可以进去」矛盾。"}, {"text": "封闭", "is_correct": false, "explanation": "语义：「封闭」指不对外开放，与「谁都可以进去」矛盾。"}, {"text": "高", "is_correct": false, "explanation": "体貌：「高」形容高度，不能用来说明公园的性质。"}], "explanations": {"公共": "正确：「公共」指大家都可以使用，与「谁都可以进去」相符。", "私有": "语义：「私有」指属于个人，与「谁都可以进去」矛盾。", "封闭": "语义：「封闭」指不对外开放，与「谁都可以进去」矛盾。", "高": "体貌：「高」形容高度，不能用来说明公园的性质。"}, "sentence_index": 0, "correct_answer": "公共"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们是公共的朋友。", "explanation": "这里应该用〈共同〉。「公共」指属于社会或大家使用的事物，不用来说人与人之间共有的关系。"}, {"text": "他做事很公共。", "explanation": "这里应该用〈公正〉。「公共」表示属于大家，不表示做事是否公平。"}, {"text": "这场比赛很公共。", "explanation": "这里应该用〈公平〉。「公共」不用来评价比赛是否公平。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac88911d-0e7f-4e56-9f4e-77105f58f5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88453, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公共", "is_correct": true, "explanation": "正确：「公共」指大家共用，与「图书馆的书」相符，也与「要爱护它们」相合。"}, {"text": "个人", "is_correct": false, "explanation": "语义：「个人」指属于某一个人，与「图书馆的书」矛盾。"}, {"text": "透明", "is_correct": false, "explanation": "体貌：「透明」形容外观可以看穿，不能用来说明书的归属。"}, {"text": "私人", "is_correct": false, "explanation": "语义：「私人」指属于个人，图书馆的书属于公共机构，与句意矛盾。"}], "explanations": {"公共": "正确：「公共」指大家共用，与「图书馆的书」相符，也与「要爱护它们」相合。", "个人": "语义：「个人」指属于某一个人，与「图书馆的书」矛盾。", "透明": "体貌：「透明」形容外观可以看穿，不能用来说明书的归属。", "私人": "语义：「私人」指属于个人，图书馆的书属于公共机构，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "公共"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店的价格很公共。", "explanation": "这里应该用〈公道〉。「公共」指属于大家使用的，不用来说价格是否合理。"}, {"text": "这份评价很公共。", "explanation": "这里应该用〈公允〉。「公共」不用来说评价是否客观，只表示属于大家。"}, {"text": "这是我的公共电话，别随便打。", "explanation": "这里应该用〈私人〉。电话是我个人的，应说「私人电话」；「公共」指大家都能用的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac88911d-0e7f-4e56-9f4e-77105f58f5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88453, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条小路是公共地，谁都可以走。", "corrected_sentence": "这条小路是公共的，谁都可以走。", "error_description": "「公共」作谓语须用「的」，不能用「地」（「地」只构成副词，不能用于谓语位置）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac88911d-0e7f-4e56-9f4e-77105f58f5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88453, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把椅子是公共，谁都可以坐。", "corrected_sentence": "这把椅子是公共的，谁都可以坐。", "error_description": "「是公共的」中的「的」不能省。写成「是公共」语法不完整，应改为「是公共的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac88911d-0e7f-4e56-9f4e-77105f58f5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88454, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "私人", "is_correct": true, "explanation": "反义：「公共」指属于社会、大家共享，与之相对的是「私人」。"}, {"text": "漂亮", "is_correct": false, "explanation": "无关：「漂亮」形容外貌好看，与「公共」没有反义关系。"}, {"text": "干燥", "is_correct": false, "explanation": "无关：「干燥」形容水分少，与「公共」不构成反义。"}, {"text": "勇敢", "is_correct": false, "explanation": "无关：「勇敢」形容性格，与「公共」不构成反义。"}], "correct_answer": "私人", "explanations": {"私人": "反义：「公共」指属于社会、大家共享，与之相对的是「私人」。", "漂亮": "无关：「漂亮」形容外貌好看，与「公共」没有反义关系。", "干燥": "无关：「干燥」形容水分少，与「公共」不构成反义。", "勇敢": "无关：「勇敢」形容性格，与「公共」不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac88911d-0e7f-4e56-9f4e-77105f58f5b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
