INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88462, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "进食；吃正餐。", "primary_collocate": null, "pronunciation": "chī fàn", "ipa": "ʈʂʰɨ˥ fan˥˩", "syllable_count": 2, "sentences": [{"text": "我们六点去吃饭。", "target_word": "吃饭", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "周末请朋友来家里吃饭。", "target_word": "吃饭", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你吃饭了吗？", "target_word": "吃饭", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中午我们在公司吃饭。", "target_word": "吃饭", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今天晚上谁请客吃饭？", "target_word": "吃饭", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们常常一起出去吃饭。", "target_word": "吃饭", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我还没吃饭，肚子很饿。", "target_word": "吃饭", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们约好明天在学校吃饭。", "target_word": "吃饭", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爸爸今晚不回家吃饭。", "target_word": "吃饭", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们在饭馆吃饭，聊了很久。", "target_word": "吃饭", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "吃过饭", "label": "体标形式"}, {"form": "吃着饭", "label": "体标形式"}], "register": "口语", "sense_fingerprint": "动词：吃饭，指在某时某地吃一顿正餐", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18e0c221-b8bd-4749-8a15-ebb972445d4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88462, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃饭", "is_correct": true, "explanation": "正确：“吃饭”表示去吃一顿饭，与“六点去”搭配自然。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“去生病”不是可以去做的事，句子不通。"}, {"text": "喜欢", "is_correct": false, "explanation": "配价：“喜欢”要带宾语，“去喜欢”说不完整。"}, {"text": "迟到", "is_correct": false, "explanation": "语义：“迟到”是结果，不能用“去”引出一个动作，句子不通。"}], "explanations": {"吃饭": "正确：“吃饭”表示去吃一顿饭，与“六点去”搭配自然。", "生病": "语义：“去生病”不是可以去做的事，句子不通。", "喜欢": "配价：“喜欢”要带宾语，“去喜欢”说不完整。", "迟到": "语义：“迟到”是结果，不能用“去”引出一个动作，句子不通。"}, "sentence_index": 0, "correct_answer": "吃饭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "食堂十一点吃饭，大家排队领饭。", "explanation": "这里应该用〈开餐〉。开餐指食堂开始供应饭菜；食堂不能吃饭。"}, {"text": "饭店五点吃饭，门口已经排起了队。", "explanation": "这里应该用〈开饭〉。开饭指饭店开始供应饭菜；饭店本身不能吃饭。"}, {"text": "孩子渴了，要吃饭。", "explanation": "这里应该用〈喝水〉。喝水指饮用液体解渴；吃饭指吃正餐，不用来解渴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e2401e-2f59-4ebb-9d07-980fe50a58c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88462, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吃饭", "is_correct": true, "explanation": "正确：“没吃饭”与“肚子很饿”构成因果，句意合理。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：没结婚与肚子饿毫无关系，句子不通。"}, {"text": "怀孕", "is_correct": false, "explanation": "语义：怀孕与肚子饿没有因果关系，句子不通。"}, {"text": "接", "is_correct": false, "explanation": "配价：“接”要带宾语，“我还没接”说不完整。"}], "explanations": {"吃饭": "正确：“没吃饭”与“肚子很饿”构成因果，句意合理。", "结婚": "语义：没结婚与肚子饿毫无关系，句子不通。", "怀孕": "语义：怀孕与肚子饿没有因果关系，句子不通。", "接": "配价：“接”要带宾语，“我还没接”说不完整。"}, "sentence_index": 6, "correct_answer": "吃饭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校食堂中午吃饭，同学们排着长队。", "explanation": "这里应该用〈开餐〉。开餐指食堂开始供应饭菜；食堂不能吃饭。"}, {"text": "婚宴十二点吃饭，亲戚们都到齐了。", "explanation": "这里应该用〈开席〉。开席指宴会开始上菜；宴会本身不能吃饭。"}, {"text": "做生意不能总是吃饭，要想办法赚钱。", "explanation": "这里应该用〈吃亏〉。吃亏指受到损失；吃饭指进食，不能表示亏损。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e2401e-2f59-4ebb-9d07-980fe50a58c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88462, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天吃饭过了，所以不饿。", "corrected_sentence": "我昨天吃过饭了，所以不饿。", "error_description": "错误：“吃饭过”。正确：“吃过饭”。“吃饭”是离合词，表示经历的“过”要放在动词“吃”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e2401e-2f59-4ebb-9d07-980fe50a58c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88462, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我弟弟吃饭吃很快。", "corrected_sentence": "我弟弟吃饭吃得很快。", "error_description": "错误：“吃饭吃很快”。正确：“吃饭吃得很快”。表示程度的补语前必须加“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e2401e-2f59-4ebb-9d07-980fe50a58c1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
