INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88469, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "取消就是说不做了,把原来的事停下来。", "primary_collocate": null, "pronunciation": "qǔ xiāo", "ipa": "tɕʰy˨˩ ɕiɑʊ˥", "syllable_count": 2, "sentences": [{"text": "我今天太累，想取消晚上的约会。", "target_word": "取消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友生病了，我们取消了旅行。", "target_word": "取消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天下雨，我们取消爬山吧。", "target_word": "取消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他临时取消了和我的见面。", "target_word": "取消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈取消了今晚的聚会。", "target_word": "取消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把周六的课取消了。", "target_word": "取消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影票太贵，我们取消了看电影的计划。", "target_word": "取消", "complexity_tier": "T3", "furigana": "diàn yǐng piào tài guì wǒ men qǔ xiāo le kàn diàn yǐng de jì huà", "sentence_source": "generated"}, {"text": "因为太忙，她取消了去海边的计划。", "target_word": "取消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要取消明天的约会。", "target_word": "取消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他取消了去医院的预约，因为已经好了。", "target_word": "取消", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "取消了", "label": "体标"}, {"form": "取消过", "label": "体标"}], "register": "中性", "sense_fingerprint": "说不做了，让原来打算的事停下来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93b857e6-3c49-4de3-8fae-c67dc4ed796b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88469, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "取消", "is_correct": true, "explanation": "正确。今天太累，想不去赴约，所以用“取消”，表示不做了。"}, {"text": "扩大", "is_correct": false, "explanation": "语义：“扩大约会”说不通，与“太累，想不去”的意愿相反。"}, {"text": "参加", "is_correct": false, "explanation": "搭配：“参加”多与会议、活动搭配，与“约会”不搭配。"}, {"text": "忍耐", "is_correct": false, "explanation": "语义：“忍耐”表示勉强承受，与“太累，想取消”的意愿矛盾。"}], "explanations": {"取消": "正确。今天太累，想不去赴约，所以用“取消”，表示不做了。", "扩大": "语义：“扩大约会”说不通，与“太累，想不去”的意愿相反。", "参加": "搭配：“参加”多与会议、活动搭配，与“约会”不搭配。", "忍耐": "语义：“忍耐”表示勉强承受，与“太累，想取消”的意愿矛盾。"}, "sentence_index": 0, "correct_answer": "取消"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他取消了手机里的旧照片。", "explanation": "这里应该用〈删除〉。取消用于事项或规定，删除手机里的照片等数据要说删除。"}, {"text": "他取消了熬夜的习惯。", "explanation": "这里应该用〈改掉〉。取消不用于习惯，改变习惯要说改掉。"}, {"text": "公司取消了那位员工。", "explanation": "这里应该用〈辞退〉。取消用于事项或规定，不直接用于指人，让员工离职要说辞退。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '821120fb-29b6-4e15-b4de-5bac71794620') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88469, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "取消", "is_correct": true, "explanation": "正确。票价太贵，所以放弃了看电影的计划，用“取消”。"}, {"text": "实现", "is_correct": false, "explanation": "语义：票价太贵是放弃的理由，说“实现计划”与句中的原因矛盾。"}, {"text": "增加", "is_correct": false, "explanation": "语义：“增加计划”与“票太贵”的理由不符，无法说明放弃。"}, {"text": "取得", "is_correct": false, "explanation": "搭配：“取得”后要接成绩、成果等，不能接“计划”。"}], "explanations": {"取消": "正确。票价太贵，所以放弃了看电影的计划，用“取消”。", "实现": "语义：票价太贵是放弃的理由，说“实现计划”与句中的原因矛盾。", "增加": "语义：“增加计划”与“票太贵”的理由不符，无法说明放弃。", "取得": "搭配：“取得”后要接成绩、成果等，不能接“计划”。"}, "sentence_index": 6, "correct_answer": "取消"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把桌上的旧报纸取消了。", "explanation": "这里是“拿走、清理掉”具体东西的意思，指把物品搬开。取消用于事项或规定，不用于具体的物品，因此不符合本义。"}, {"text": "他取消了心里的紧张。", "explanation": "这里是“消除”心理状态的意思，指让紧张的感觉消失。取消用于已定的安排或规定，不用于心理状态，因此不符合本义。"}, {"text": "他把窗户上的雨水取消了。", "explanation": "这里是“擦去、清除”附着在物体上的东西的意思。取消用于事项或规定，不用于附着的雨水，因此不符合本义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '821120fb-29b6-4e15-b4de-5bac71794620') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88469, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把今晚的球赛取消。", "corrected_sentence": "他把今晚的球赛取消了。", "error_description": "错误：用“把”字句时，“取消”后面缺少“了”，句子不完整。正确：应说“他把今晚的球赛取消了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '821120fb-29b6-4e15-b4de-5bac71794620') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88469, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没取消了去上海的计划。", "corrected_sentence": "他没取消去上海的计划。", "error_description": "错误：否定句中“没”后面又加了“了”（没取消了）。正确：“没取消”之后不加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '821120fb-29b6-4e15-b4de-5bac71794620') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
