INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88470, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "撤销原定的事项或规定,使其不再有效。", "primary_collocate": null, "pronunciation": "qǔ xiāo", "ipa": "tɕʰy˨˩ ɕiɑʊ˥", "syllable_count": 2, "sentences": [{"text": "因为下大雨，今天的比赛取消了。", "target_word": "取消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校取消了周末的考试。", "target_word": "取消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司取消了那个旧规定。", "target_word": "取消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他取消了明天去北京的机票。", "target_word": "取消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把今天的会议取消了。", "target_word": "取消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店取消了我们的预订。", "target_word": "取消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "航班取消了，我们只好回家。", "target_word": "取消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他取消过一次约会。", "target_word": "取消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理取消了所有人的假期。", "target_word": "取消", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校为什么取消这个活动？", "target_word": "取消", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "取消了", "label": "体标"}, {"form": "取消过", "label": "体标"}], "register": "中性", "sense_fingerprint": "撤销原定的安排或规定，使其失效", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93b857e6-3c49-4de3-8fae-c67dc4ed796b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88470, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "取消", "is_correct": true, "explanation": "正确。下大雨导致比赛无法举行，所以用“取消”，表示撤销原定的比赛。"}, {"text": "开始", "is_correct": false, "explanation": "语义：比赛“开始”与“因为下大雨”没有因果联系，句意矛盾。"}, {"text": "参加", "is_correct": false, "explanation": "搭配：“参加”的主语要是人或团体，“比赛”不能作“参加”的主语。"}, {"text": "取得", "is_correct": false, "explanation": "配价：“取得”后要带成绩、成果等宾语，“取得了”没有宾语，句子不完整。"}], "explanations": {"取消": "正确。下大雨导致比赛无法举行，所以用“取消”，表示撤销原定的比赛。", "开始": "语义：比赛“开始”与“因为下大雨”没有因果联系，句意矛盾。", "参加": "搭配：“参加”的主语要是人或团体，“比赛”不能作“参加”的主语。", "取得": "配价：“取得”后要带成绩、成果等宾语，“取得了”没有宾语，句子不完整。"}, "sentence_index": 0, "correct_answer": "取消"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他取消了吸烟的习惯。", "explanation": "这里应该用〈戒掉〉。取消用于已定的安排或规定，戒除习惯要说戒掉。"}, {"text": "他取消了刚才说的那句话。", "explanation": "这里应该用〈收回〉。取消的对象是安排或规定，已经说出口的话要说收回。"}, {"text": "公司取消了那个员工。", "explanation": "这里应该用〈辞退〉。取消用于事项或规定，不直接用于指人，让员工离职要说辞退。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '821120fb-29b6-4e15-b4de-5bac71794620') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88470, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "取消", "is_correct": true, "explanation": "正确。航班停飞，乘客只好回家，所以用“取消”。"}, {"text": "起飞", "is_correct": false, "explanation": "语义：航班起飞后乘客不必回家，与“只好回家”的因果关系不通。"}, {"text": "登记", "is_correct": false, "explanation": "搭配：“登记”要求人作主语或登记的内容作宾语，“航班登记了”不成立。"}, {"text": "旅行", "is_correct": false, "explanation": "搭配：“旅行”的主语应是人，“航班旅行了”不通，也与句意不合。"}], "explanations": {"取消": "正确。航班停飞，乘客只好回家，所以用“取消”。", "起飞": "语义：航班起飞后乘客不必回家，与“只好回家”的因果关系不通。", "登记": "搭配：“登记”要求人作主语或登记的内容作宾语，“航班登记了”不成立。", "旅行": "搭配：“旅行”的主语应是人，“航班旅行了”不通，也与句意不合。"}, "sentence_index": 6, "correct_answer": "取消"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把地上的积水取消了。", "explanation": "这里是“排除、清除”积水的意思，指把具体的水去掉。取消用于已定的事项或规定，不用于具体的物体，因此不符合本义。"}, {"text": "他取消了肩上的疲劳。", "explanation": "这里是“消除”身体上疲劳的意思，指使疲劳感消失。取消用于事项或规定，不用于身体的感受，因此不符合本义。"}, {"text": "他取消了纸上的错字。", "explanation": "这里是“擦去”字迹的意思，指把纸上的字去掉。取消用于事项或规定，不用于具体的字迹，因此不符合本义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '821120fb-29b6-4e15-b4de-5bac71794620') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88470, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校把运动会取消。", "corrected_sentence": "学校把运动会取消了。", "error_description": "错误：用“把”字句时，“取消”后面缺少“了”，句子不完整。正确：应说“学校把运动会取消了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '821120fb-29b6-4e15-b4de-5bac71794620') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88470, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校取消着那次考试。", "corrected_sentence": "学校取消了那次考试。", "error_description": "错误：“取消”后加了“着”，表示动作持续。正确：“取消”是一次性完成的动作，应说“取消了”，表示已经撤销。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '821120fb-29b6-4e15-b4de-5bac71794620') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88479, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "回来", "is_correct": true, "explanation": "“回来”与“回去”意义相反，表示回到说话人所在的地方。"}, {"text": "进入", "is_correct": false, "explanation": "“进入”表示由外往里走，与“回去”没有反义关系。"}, {"text": "坐下", "is_correct": false, "explanation": "“坐下”表示由站到坐的动作，与“回去”没有反义关系。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与“回去”的动作和方向都无关，不构成反义关系。"}], "correct_answer": "回来", "explanations": {"回来": "“回来”与“回去”意义相反，表示回到说话人所在的地方。", "进入": "“进入”表示由外往里走，与“回去”没有反义关系。", "坐下": "“坐下”表示由站到坐的动作，与“回去”没有反义关系。", "睡觉": "语义：“睡觉”与“回去”的动作和方向都无关，不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8fe8702-03bd-4132-ad10-aea67fcf0340') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88479, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "回来", "is_correct": true, "explanation": "“回来”与“回去”意义相反，表示回到说话人所在的地方。"}, {"text": "写字", "is_correct": false, "explanation": "语义：“写字”与“回去”的动作和方向都无关，不构成反义关系。"}, {"text": "登记", "is_correct": false, "explanation": "“登记”指办理登记手续，与“回去”没有反义关系。"}, {"text": "吃饭", "is_correct": false, "explanation": "“吃饭”指进食，与“回去”没有反义关系。"}], "correct_answer": "回来", "explanations": {"回来": "“回来”与“回去”意义相反，表示回到说话人所在的地方。", "写字": "语义：“写字”与“回去”的动作和方向都无关，不构成反义关系。", "登记": "“登记”指办理登记手续，与“回去”没有反义关系。", "吃饭": "“吃饭”指进食，与“回去”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8fe8702-03bd-4132-ad10-aea67fcf0340') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88479, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "回去是从别的地方走回原来的地方。", "primary_collocate": null, "pronunciation": "huí qù", "ipa": "xweɪ˧˥ tɕʰy˥˩", "syllable_count": 2, "sentences": [{"text": "我在公司，六点回去。", "target_word": "回去", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他去超市买菜，买完就回去。", "target_word": "回去", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子玩完了，该回去了。", "target_word": "回去", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你先回去，我再坐一会儿。", "target_word": "回去", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我去朋友家玩，晚上回去。", "target_word": "回去", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他吃过饭就回去了。", "target_word": "回去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课后，同学们都回去了。", "target_word": "回去", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "外面太冷，我们快回去吧。", "target_word": "回去", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你从公园回去时，请买点水果。", "target_word": "回去", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在老家住了三天，昨天回去了。", "target_word": "回去", "complexity_tier": "T3", "furigana": "huí qù", "sentence_source": "generated"}], "morphological_forms": [{"form": "回去了", "label": "体标"}, {"form": "回去过", "label": "体标"}], "register": "口语", "sense_fingerprint": "动词：从别处走回原来所在的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '173555db-e539-4abf-a4ea-80fc8e3de36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88479, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "回去", "is_correct": true, "explanation": "“回去”表示从公司返回原来的地方，与“六点”下班的语境相符。"}, {"text": "出国", "is_correct": false, "explanation": "语义：“出国”指离开国境，与“在公司”“六点”的语境不符。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“考试”需要在考场进行，与“在公司”的语境不符。"}, {"text": "回忆", "is_correct": false, "explanation": "配价：“回忆”是及物动词，后面通常要带宾语，如“回忆往事”，句中没有宾语。"}], "explanations": {"回去": "“回去”表示从公司返回原来的地方，与“六点”下班的语境相符。", "出国": "语义：“出国”指离开国境，与“在公司”“六点”的语境不符。", "考试": "语义：“考试”需要在考场进行，与“在公司”的语境不符。", "回忆": "配价：“回忆”是及物动词，后面通常要带宾语，如“回忆往事”，句中没有宾语。"}, "sentence_index": 0, "correct_answer": "回去"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从没到过那家超市，今晚要回去那家超市。", "explanation": "这里应该用〈去〉。“回去”表示返回以前待过的地方，他从未到过那家超市，应说“去那家超市”。"}, {"text": "我从没到过那家餐厅，今晚想回去那家餐厅。", "explanation": "这里应该用〈去〉。“回去”要求此前待过该处，这里应说“去那家餐厅”。"}, {"text": "他从没来过这个城市，下周要回去这个城市。", "explanation": "这里应该用〈去〉。“回去”表示回到以前待过的地方，他从未来过这个城市，应说“去”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8fe8702-03bd-4132-ad10-aea67fcf0340') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88479, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回去", "is_correct": true, "explanation": "“回去”表示同学们离开教室返回原地，与“下课后”相符。"}, {"text": "上课", "is_correct": false, "explanation": "语义：“下课后”再“上课”与语境矛盾，不能说“同学们都上课了”。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”的主语只能是天气，“同学们”不能下雨，与句意不符。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”指人降生，与“下课后”的时间和语境不符。"}], "explanations": {"回去": "“回去”表示同学们离开教室返回原地，与“下课后”相符。", "上课": "语义：“下课后”再“上课”与语境矛盾，不能说“同学们都上课了”。", "下雨": "语义：“下雨”的主语只能是天气，“同学们”不能下雨，与句意不符。", "出生": "语义：“出生”指人降生，与“下课后”的时间和语境不符。"}, "sentence_index": 6, "correct_answer": "回去"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他刚从公司回去，现在在我家。", "explanation": "这里应该用〈回来〉。“回去”表示离开说话人所在地回到原处，这里“他”已在说话人家中，应说“回来”。"}, {"text": "我在门口，你回去帮我开门。", "explanation": "这里应该用〈过来〉。“回去”指回到对方原来的地方，请对方到说话人所在的门口帮忙要用“过来”。"}, {"text": "明天你回去我公司找我。", "explanation": "这里应该用〈来〉。“回去”指回到原来的地方，“我公司”不是对方原来所在之处，请对方到说话人这里应说“来”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8fe8702-03bd-4132-ad10-aea67fcf0340') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88479, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我先回去家，你们再来吧。", "corrected_sentence": "我先回家，你们再来吧。", "error_description": "“回去”后不能直接接处所名词“家”，表示回家应说“回家”，这里应去掉“去”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8fe8702-03bd-4132-ad10-aea67fcf0340') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88479, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把书回去了。", "corrected_sentence": "他把书带回去了。", "error_description": "“回去”不能直接带物品作宾语，把东西带回去要加“带”，这里应说“把书带回去”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8fe8702-03bd-4132-ad10-aea67fcf0340') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88483, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "少数", "is_correct": true, "explanation": "正确。“少数”与“多数”相对，指一组中所占比例较小的那部分。"}, {"text": "全体", "is_correct": false, "explanation": "不是反义：“全体”指整体，与“多数”是部分与整体的关系，不是对立。"}, {"text": "整体", "is_correct": false, "explanation": "不是反义：“整体”指全部的集合，与“多数”不构成对立。"}, {"text": "群体", "is_correct": false, "explanation": "不是反义：“群体”指聚在一起的人，与“多数”不构成对立。"}], "correct_answer": "少数", "explanations": {"少数": "正确。“少数”与“多数”相对，指一组中所占比例较小的那部分。", "全体": "不是反义：“全体”指整体，与“多数”是部分与整体的关系，不是对立。", "整体": "不是反义：“整体”指全部的集合，与“多数”不构成对立。", "群体": "不是反义：“群体”指聚在一起的人，与“多数”不构成对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '821120fb-29b6-4e15-b4de-5bac71794620') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88483, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "少数", "is_correct": true, "explanation": "正确。“少数”与“多数”相对，指一组中所占比例较小的那部分。"}, {"text": "个体", "is_correct": false, "explanation": "不是反义：“个体”指单个的人或事物，与“多数”不构成对立。"}, {"text": "全部", "is_correct": false, "explanation": "不是反义：“全部”指整体的全部，与“多数”不是对立关系。"}, {"text": "人群", "is_correct": false, "explanation": "不是反义：“人群”指聚在一起的一群人，与“多数”不构成对立。"}], "correct_answer": "少数", "explanations": {"少数": "正确。“少数”与“多数”相对，指一组中所占比例较小的那部分。", "个体": "不是反义：“个体”指单个的人或事物，与“多数”不构成对立。", "全部": "不是反义：“全部”指整体的全部，与“多数”不是对立关系。", "人群": "不是反义：“人群”指聚在一起的一群人，与“多数”不构成对立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '821120fb-29b6-4e15-b4de-5bac71794620') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88483, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "多数是人或东西里面,比一半多的那一些。", "primary_collocate": null, "pronunciation": "duō shù", "ipa": "twɔ˥ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "我的朋友里，多数住在北京。", "target_word": "多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个班有三十个人，多数是女生。", "target_word": "多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多数老师星期六不上班。", "target_word": "多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买来的苹果，多数是红的。", "target_word": "多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家多数人喜欢吃面。", "target_word": "多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书架上的书，多数是新买的。", "target_word": "多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多数小孩儿喜欢吃糖。", "target_word": "多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天，多数人带着伞。", "target_word": "多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些菜里多数是我做的。", "target_word": "多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全班同学多数通过了考试。", "target_word": "多数", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大多数", "label": "复合"}, {"form": "多数人", "label": "复合"}], "register": "中性", "sense_fingerprint": "人或东西里比一半多的那一部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93b857e6-3c49-4de3-8fae-c67dc4ed796b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88483, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多数", "is_correct": true, "explanation": "正确。“多数”指朋友中比一半多的人，作主语，句意通顺。"}, {"text": "城市", "is_correct": false, "explanation": "语义：“城市”是地方，不是朋友，“城市住在北京”句意不通。"}, {"text": "公寓", "is_correct": false, "explanation": "搭配：“住”的主语要是人，“公寓”不能作“住”的主语。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”不属于朋友的范畴，与句中的“住在北京”不搭。"}], "explanations": {"多数": "正确。“多数”指朋友中比一半多的人，作主语，句意通顺。", "城市": "语义：“城市”是地方，不是朋友，“城市住在北京”句意不通。", "公寓": "搭配：“住”的主语要是人，“公寓”不能作“住”的主语。", "厨房": "语义：“厨房”不属于朋友的范畴，与句中的“住在北京”不搭。"}, "sentence_index": 0, "correct_answer": "多数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了多数个苹果。", "explanation": "这里应该用〈好几〉。多数指一组中超过半数的部分，不能直接放在量词“个”前表示不定的数量，这里要说买了好几个。"}, {"text": "买来的苹果，多数是三斤。", "explanation": "这里应该用〈重量〉。多数表示比例，不能表示重量，要说重量是三斤。"}, {"text": "我们班的多数是三十个。", "explanation": "这里应该用〈人数〉。多数不能表示具体数目，说班里的人数是三十个要用人数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '821120fb-29b6-4e15-b4de-5bac71794620') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88483, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多数", "is_correct": true, "explanation": "正确。“多数小孩儿喜欢吃糖”指大部分孩子喜欢，“多数”作主语，句意通顺。"}, {"text": "成年", "is_correct": false, "explanation": "语义：“成年小孩儿”自相矛盾，与“小孩儿喜欢吃糖”冲突。"}, {"text": "老年", "is_correct": false, "explanation": "语义：“老年小孩儿”自相矛盾，与“小孩儿”的意思冲突。"}, {"text": "大学生", "is_correct": false, "explanation": "搭配：“大学生”与“小孩儿”不能并列修饰同一个名词，搭配不当。"}], "explanations": {"多数": "正确。“多数小孩儿喜欢吃糖”指大部分孩子喜欢，“多数”作主语，句意通顺。", "成年": "语义：“成年小孩儿”自相矛盾，与“小孩儿喜欢吃糖”冲突。", "老年": "语义：“老年小孩儿”自相矛盾，与“小孩儿”的意思冲突。", "大学生": "搭配：“大学生”与“小孩儿”不能并列修饰同一个名词，搭配不当。"}, "sentence_index": 6, "correct_answer": "多数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "全班同学多数次通过了考试。", "explanation": "这里应该用〈多次〉。多数表示超过半数的部分，不修饰次数，说通过了很多次要用多次。"}, {"text": "全班同学多数地通过了考试。", "explanation": "这里不能把“多数”当副词加“地”用，表示“顺利”的意思要用〈顺利〉。多数只表示超过半数的部分。"}, {"text": "全班同学多数是通过了考试。", "explanation": "这里不能把“多数”当成“基本”的意思用，表示“基本都”要用〈基本〉。多数只表示超过半数的部分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '821120fb-29b6-4e15-b4de-5bac71794620') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88483, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们小区一个多数住户养了狗。", "corrected_sentence": "我们小区多数住户养了狗。", "error_description": "错误：“多数”前面加了量词“一个”。正确：“多数”不带量词，直接说“多数住户”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '821120fb-29b6-4e15-b4de-5bac71794620') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88483, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "放学以后，很多数学生去图书馆。", "corrected_sentence": "放学以后，多数学生去图书馆。", "error_description": "错误：“多数”前面加了副词“很”（很多数）。正确：“多数”不受“很”修饰，应说“多数学生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '821120fb-29b6-4e15-b4de-5bac71794620') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88484, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "少数", "is_correct": true, "explanation": "正确。“少数”与“多数”意义相对，指一组中所占比例较小的那部分。"}, {"text": "全体", "is_correct": false, "explanation": "不是反义：“全体”指整体，与“多数”是部分与整体的关系，不是对立。"}, {"text": "整体", "is_correct": false, "explanation": "不是反义：“整体”指全部的集合，与“多数”不构成对立。"}, {"text": "群体", "is_correct": false, "explanation": "不是反义：“群体”指聚在一起的人，与“多数”不构成对立。"}], "correct_answer": "少数", "explanations": {"少数": "正确。“少数”与“多数”意义相对，指一组中所占比例较小的那部分。", "全体": "不是反义：“全体”指整体，与“多数”是部分与整体的关系，不是对立。", "整体": "不是反义：“整体”指全部的集合，与“多数”不构成对立。", "群体": "不是反义：“群体”指聚在一起的人，与“多数”不构成对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '821120fb-29b6-4e15-b4de-5bac71794620') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88484, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "少数", "is_correct": true, "explanation": "正确。“少数”与“多数”相对，指一组中所占比例较小的那部分。"}, {"text": "个体", "is_correct": false, "explanation": "不是反义：“个体”指单个的人或事物，与“多数”不构成对立。"}, {"text": "全部", "is_correct": false, "explanation": "不是反义：“全部”指整体的全部，与“多数”不是对立关系。"}, {"text": "人群", "is_correct": false, "explanation": "不是反义：“人群”指聚在一起的一群人，与“多数”不构成对立。"}], "correct_answer": "少数", "explanations": {"少数": "正确。“少数”与“多数”相对，指一组中所占比例较小的那部分。", "个体": "不是反义：“个体”指单个的人或事物，与“多数”不构成对立。", "全部": "不是反义：“全部”指整体的全部，与“多数”不是对立关系。", "人群": "不是反义：“人群”指聚在一起的一群人，与“多数”不构成对立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '821120fb-29b6-4e15-b4de-5bac71794620') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88484, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "较大的数量;超过半数的部分。", "primary_collocate": null, "pronunciation": "duō shù", "ipa": "twɔ˥ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "多数人同意这个办法。", "target_word": "多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会时，多数同学选了第二个办法。", "target_word": "多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班多数学生喜欢踢足球。", "target_word": "多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "投票的结果由多数人决定。", "target_word": "多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这家店买东西的，多数是老人。", "target_word": "多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多数时候，我坐地铁上班。", "target_word": "多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少数人要听多数人的意见。", "target_word": "多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的多数商店晚上十点关门。", "target_word": "多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多数孩子都怕打针。", "target_word": "多数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司里多数人不会说日语。", "target_word": "多数", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大多数", "label": "复合"}, {"form": "多数人", "label": "复合"}], "register": "中性", "sense_fingerprint": "超过半数的较大部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93b857e6-3c49-4de3-8fae-c67dc4ed796b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88484, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多数", "is_correct": true, "explanation": "正确。“多数人”指超过半数的人，与“同意这个办法”相符。"}, {"text": "植物", "is_correct": false, "explanation": "语义：“植物人”指没有意识的人，无法表示同意，句意冲突。"}, {"text": "木头", "is_correct": false, "explanation": "语义：“木头人”指呆板不动的人，不能表示同意办法。"}, {"text": "纸人", "is_correct": false, "explanation": "语义：“纸人”是纸做的人偶，不能表示同意办法，句意不通。"}], "explanations": {"多数": "正确。“多数人”指超过半数的人，与“同意这个办法”相符。", "植物": "语义：“植物人”指没有意识的人，无法表示同意，句意冲突。", "木头": "语义：“木头人”指呆板不动的人，不能表示同意办法。", "纸人": "语义：“纸人”是纸做的人偶，不能表示同意办法，句意不通。"}, "sentence_index": 0, "correct_answer": "多数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他多数会来。", "explanation": "这里应该用〈多半〉。多数表示超过半数的部分，推测“大概”要用多半。"}, {"text": "你有多数钱？", "explanation": "这里应该用〈多少〉。多数表示超过半数的部分，不用于询问钱的数量，问数量要用多少。"}, {"text": "班里的多数是三十。", "explanation": "这里应该用〈人数〉。多数指部分占整体的比例，不能表示具体数目，说人数是三十要用人数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '821120fb-29b6-4e15-b4de-5bac71794620') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88484, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多数", "is_correct": true, "explanation": "正确。“少数人要听多数人的意见”是常见说法，“多数人”指超过半数的人。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头人”不是能提意见的人，与句意不通。"}, {"text": "外星", "is_correct": false, "explanation": "语义：“外星人”不在现实社会中，无法提出意见，句意不通。"}, {"text": "小", "is_correct": false, "explanation": "语域：“小人”是带贬义的书面词，用在这里不合语境。"}], "explanations": {"多数": "正确。“少数人要听多数人的意见”是常见说法，“多数人”指超过半数的人。", "石头": "语义：“石头人”不是能提意见的人，与句意不通。", "外星": "语义：“外星人”不在现实社会中，无法提出意见，句意不通。", "小": "语域：“小人”是带贬义的书面词，用在这里不合语境。"}, "sentence_index": 6, "correct_answer": "多数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我去过多数次日本。", "explanation": "这里应该用〈多次〉。多数表示超过半数的部分，不修饰次数，说去过很多次要用多次。"}, {"text": "他多数每天跑步。", "explanation": "这里应该用〈经常〉。多数表示部分，不表示动作的频率，说每天做某事的频繁程度要用经常。"}, {"text": "这件事我多数知道。", "explanation": "这里应该用〈大都〉。多数表示超过半数的部分，不用于表示对事情的了解程度，要说大都知道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '821120fb-29b6-4e15-b4de-5bac71794620') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88484, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "班里一个多数同学都喜欢这门课。", "corrected_sentence": "班里多数同学都喜欢这门课。", "error_description": "错误：“多数”前面加了量词“一个”。正确：“多数”不带量词，直接修饰名词，说“多数同学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '821120fb-29b6-4e15-b4de-5bac71794620') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88484, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "周末的时候，很多数人在家休息。", "corrected_sentence": "周末的时候，多数人在家休息。", "error_description": "错误：“多数”前面加了副词“很”（很多数）。正确：“多数”不受“很”修饰，应说“多数人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '821120fb-29b6-4e15-b4de-5bac71794620') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
