INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88511, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "爱将是将军特别喜欢、特别相信的手下。", "primary_collocate": null, "pronunciation": "ài jiàng", "ipa": "aɪ˥˩ tɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "将军很喜欢这位年轻的爱将。", "target_word": "爱将", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "张飞是刘备的爱将。", "target_word": "爱将", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爱将死了，将军哭了很久。", "target_word": "爱将", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从小就是主帅身边的爱将。", "target_word": "爱将", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战场上，爱将一直保护着将军。", "target_word": "爱将", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将军夸他是自己最得力的爱将。", "target_word": "爱将", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个爱将很会打仗。", "target_word": "爱将", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "皇帝送了一匹好马给将军的爱将。", "target_word": "爱将", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想让爱将留在身边。", "target_word": "爱将", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大家都知道，他是将军的爱将。", "target_word": "爱将", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "员", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "愛將", "label": "繁体"}], "register": "书面", "sense_fingerprint": "名词：将军特别喜欢和相信的手下", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '173555db-e539-4abf-a4ea-80fc8e3de36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88511, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "爱将", "is_correct": true, "explanation": "爱将（ài jiàng）：将军特别喜欢、特别相信的手下，是本题正确答案。"}, {"text": "败将", "is_correct": false, "explanation": "bài jiàng 与 ài jiàng 的声母不同（多一个 b），意思是“战败的将领”。"}, {"text": "挨讲", "is_correct": false, "explanation": "ái jiǎng 与 ài jiàng 两个音节的声调都不同，意思是“受到责备”。"}, {"text": "爱讲", "is_correct": false, "explanation": "ài jiǎng 与 ài jiàng 第二个音节声调不同，意思是“喜欢说”。"}], "explanations": {"爱将": "爱将（ài jiàng）：将军特别喜欢、特别相信的手下，是本题正确答案。", "败将": "bài jiàng 与 ài jiàng 的声母不同（多一个 b），意思是“战败的将领”。", "挨讲": "ái jiǎng 与 ài jiàng 两个音节的声调都不同，意思是“受到责备”。", "爱讲": "ài jiǎng 与 ài jiàng 第二个音节声调不同，意思是“喜欢说”。"}, "sentence_index": null, "correct_answer": "爱将"}, "level_3": {"options": [{"text": "爱将", "is_correct": true, "explanation": "爱将：将军特别喜欢、特别相信的手下，与“很喜欢这位年轻的”相符。"}, {"text": "老人", "is_correct": false, "explanation": "体貌：“年轻”与“老人”的外貌描写相矛盾。"}, {"text": "老将", "is_correct": false, "explanation": "语义：“老将”指年老的将领，与“年轻的”相矛盾。"}, {"text": "敌将", "is_correct": false, "explanation": "语义：“敌将”是敌方的将领，将军不会喜欢他。"}], "explanations": {"爱将": "爱将：将军特别喜欢、特别相信的手下，与“很喜欢这位年轻的”相符。", "老人": "体貌：“年轻”与“老人”的外貌描写相矛盾。", "老将": "语义：“老将”指年老的将领，与“年轻的”相矛盾。", "敌将": "语义：“敌将”是敌方的将领，将军不会喜欢他。"}, "sentence_index": 0, "correct_answer": "爱将"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位爱将指挥全军，威震四方。", "explanation": "这里应该用〈大将〉。“爱将”指主将的部下，不能用来指统率全军、威震四方的将领。"}, {"text": "这台电脑是老师最得意的爱将。", "explanation": "这里应该用〈爱物〉。“爱将”指将军身边的部下将领，是人，不能指电脑。"}, {"text": "这只猫是他的爱将，每天抓老鼠。", "explanation": "这里应该用〈宠物〉。“爱将”指将军身边的部下将领，是人，不能指猫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8fe8702-03bd-4132-ad10-aea67fcf0340') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88511, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "爱将", "is_correct": true, "explanation": "爱将：将军特别喜欢、特别相信的手下，与“很会打仗”相符。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师与“很会打仗”的能力无关，不符合句意。"}, {"text": "花瓶", "is_correct": false, "explanation": "搭配：“很会打仗”要求有行动能力的人作主语，“花瓶”不能打仗。"}, {"text": "病人", "is_correct": false, "explanation": "语义：“病人”身体不适，与“很会打仗”相矛盾。"}], "explanations": {"爱将": "爱将：将军特别喜欢、特别相信的手下，与“很会打仗”相符。", "厨师": "语义：厨师与“很会打仗”的能力无关，不符合句意。", "花瓶": "搭配：“很会打仗”要求有行动能力的人作主语，“花瓶”不能打仗。", "病人": "语义：“病人”身体不适，与“很会打仗”相矛盾。"}, "sentence_index": 6, "correct_answer": "爱将"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家都知道，他是三军的爱将，统率全军。", "explanation": "这里应该用〈主帅〉。“爱将”是主将的部下，不能用来指统率全军的人。"}, {"text": "这棵果树是他的爱将，每年都结很多果。", "explanation": "这里应该用〈宝贝〉。“爱将”指将军身边的部下将领，是人，不能指果树。"}, {"text": "这部手机是将军的爱将，从不离身。", "explanation": "这里应该用〈心爱之物〉。“爱将”指将军的部下将领，是人，不能指手机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8fe8702-03bd-4132-ad10-aea67fcf0340') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88511, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这头爱将深受将军的信任。", "corrected_sentence": "这位爱将深受将军的信任。", "error_description": "错误形式：“这头”中的量词“头”。正确形式：“这位”。“头”用于牛、猪等动物，指人应该用“位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8fe8702-03bd-4132-ad10-aea67fcf0340') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88511, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位年轻的爱将深将军的信任。", "corrected_sentence": "这位年轻的爱将深得将军的信任。", "error_description": "错误形式：“深将军的信任”中漏了动词“得”。正确形式：“深得将军的信任”。“深得”是固定搭配，动词“得”不可省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8fe8702-03bd-4132-ad10-aea67fcf0340') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
