INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88519, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "摘", "is_correct": true, "explanation": "摘：把戴在头上、脸上或手上的东西取下来，与“戴”构成反义关系。"}, {"text": "拿", "is_correct": false, "explanation": "拿：用手握住或取得，与“戴”不构成反义关系。"}, {"text": "放", "is_correct": false, "explanation": "放：搁置、安置，与“戴”不构成反义关系。"}, {"text": "送", "is_correct": false, "explanation": "送：把东西给别人，与“戴”不构成反义关系。"}], "correct_answer": "摘", "explanations": {"摘": "摘：把戴在头上、脸上或手上的东西取下来，与“戴”构成反义关系。", "拿": "拿：用手握住或取得，与“戴”不构成反义关系。", "放": "放：搁置、安置，与“戴”不构成反义关系。", "送": "送：把东西给别人，与“戴”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8fe8702-03bd-4132-ad10-aea67fcf0340') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
