INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88519, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "戴是把东西放在头上、脸上或手上。", "primary_collocate": null, "pronunciation": "dài", "ipa": "tai˥˩", "syllable_count": 1, "sentences": [{"text": "他每天都戴帽子。", "target_word": "戴", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她脸上戴着一副黑眼镜。", "target_word": "戴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面很冷，你要戴手套。", "target_word": "戴", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她手上戴了一个红色的戒指。", "target_word": "戴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明在室内也戴着帽子。", "target_word": "戴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生进来时，脸上戴着口罩。", "target_word": "戴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骑自行车的时候要戴头盔。", "target_word": "戴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你戴过这种手表吗？", "target_word": "戴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把新帽子戴在头上。", "target_word": "戴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他戴着耳机听音乐。", "target_word": "戴", "complexity_tier": "T3", "furigana": "tā dài zhe ěrjī tīng yīnyuè.", "sentence_source": "generated"}], "morphological_forms": [{"form": "戴着", "label": "着体"}, {"form": "戴了", "label": "了体"}, {"form": "戴过", "label": "过体"}], "register": "中性", "sense_fingerprint": "把帽子、眼镜、戒指等放在头上、脸上或手上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '173555db-e539-4abf-a4ea-80fc8e3de36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88519, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "戴", "is_correct": true, "explanation": "戴（dài）：把东西放在头上、脸上或手上，是本题正确答案。"}, {"text": "太", "is_correct": false, "explanation": "tài（第四声）与 dài 声母不同（t 与 d），意思是“太”，表示程度过分。"}, {"text": "大", "is_correct": false, "explanation": "dà（第四声）与 dài 韵母不同（没有 -i），意思是“大”。"}, {"text": "呆", "is_correct": false, "explanation": "dāi（第一声）与 dài 声调不同，意思是“呆板、停留”。"}], "explanations": {"戴": "戴（dài）：把东西放在头上、脸上或手上，是本题正确答案。", "太": "tài（第四声）与 dài 声母不同（t 与 d），意思是“太”，表示程度过分。", "大": "dà（第四声）与 dài 韵母不同（没有 -i），意思是“大”。", "呆": "dāi（第一声）与 dài 声调不同，意思是“呆板、停留”。"}, "sentence_index": null, "correct_answer": "戴"}, "level_3": {"options": [{"text": "戴", "is_correct": true, "explanation": "戴：把东西放在头上、脸上或手上，与“他每天都”和“帽子”搭配相符。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”用于衣服、鞋袜，不能用于帽子。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，“帽子”不能吃。"}, {"text": "踢", "is_correct": false, "explanation": "搭配：“踢”的对象是球或脚下的物体，不能说“踢帽子”。"}], "explanations": {"戴": "戴：把东西放在头上、脸上或手上，与“他每天都”和“帽子”搭配相符。", "穿": "搭配：“穿”用于衣服、鞋袜，不能用于帽子。", "吃": "语义：“吃”的对象是食物，“帽子”不能吃。", "踢": "搭配：“踢”的对象是球或脚下的物体，不能说“踢帽子”。"}, "sentence_index": 0, "correct_answer": "戴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她今天戴了一件红色的外套。", "explanation": "这里应该用〈穿〉。“戴”用于头、脸、手上的东西，衣服要用“穿”。"}, {"text": "她手上戴了一封信。", "explanation": "这里应该用〈拿〉。“戴”指把东西加在头、脸、手上，信件只能拿。"}, {"text": "门上戴着一把锁。", "explanation": "这里应该用〈挂〉。“戴”指把东西放在头、脸、手上，锁应挂在门上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8fe8702-03bd-4132-ad10-aea67fcf0340') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88519, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "戴", "is_correct": true, "explanation": "戴（dài）：把东西放在头上、脸上或手上，是本题正确答案。"}, {"text": "拜", "is_correct": false, "explanation": "bài 与 dài 声母不同（b 与 d），意思是“拜访、拜”。"}, {"text": "盖", "is_correct": false, "explanation": "gài 与 dài 声母不同（g 与 d），意思是“覆盖、盖子”。"}, {"text": "赖", "is_correct": false, "explanation": "lài 与 dài 声母不同（l 与 d），意思是“依靠、耍赖”。"}], "explanations": {"戴": "戴（dài）：把东西放在头上、脸上或手上，是本题正确答案。", "拜": "bài 与 dài 声母不同（b 与 d），意思是“拜访、拜”。", "盖": "gài 与 dài 声母不同（g 与 d），意思是“覆盖、盖子”。", "赖": "lài 与 dài 声母不同（l 与 d），意思是“依靠、耍赖”。"}, "sentence_index": null, "correct_answer": "戴"}, "level_3": {"options": [{"text": "戴", "is_correct": true, "explanation": "戴：把东西放在头上，与“骑自行车的时候要”和“头盔”相符。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的对象是液体，“头盔”不能喝。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能说“唱头盔”。"}, {"text": "咬", "is_correct": false, "explanation": "语义：咬头盔会损坏保护用品，与骑车时佩戴头盔的语境相矛盾。"}], "explanations": {"戴": "戴：把东西放在头上，与“骑自行车的时候要”和“头盔”相符。", "喝": "语义：“喝”的对象是液体，“头盔”不能喝。", "唱": "搭配：“唱”的对象是歌曲，不能说“唱头盔”。", "咬": "语义：咬头盔会损坏保护用品，与骑车时佩戴头盔的语境相矛盾。"}, "sentence_index": 6, "correct_answer": "戴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他戴着书包上学。", "explanation": "这里应该用〈背〉。“戴”指把东西放在头、脸、手上，书包应背在肩上。"}, {"text": "她戴着一个枕头睡觉。", "explanation": "这里应该用〈抱〉。“戴”指加在头、脸、手上，枕头不能戴。"}, {"text": "他把钥匙戴在桌上。", "explanation": "这里应该用〈放〉。“戴”指把东西放在头、脸、手上，桌上的东西只能放。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8fe8702-03bd-4132-ad10-aea67fcf0340') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.v