INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88520, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西加在头、面、胸、手等处。", "primary_collocate": null, "pronunciation": "dài", "ipa": "tai˥˩", "syllable_count": 1, "sentences": [{"text": "他胸前戴着一朵红花。", "target_word": "戴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩脖子上戴着银项链。", "target_word": "戴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都戴红领巾。", "target_word": "戴", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "参加晚会时，她戴了面具。", "target_word": "戴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她耳朵上戴着一对耳环。", "target_word": "戴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新娘头上戴了一朵白花。", "target_word": "戴", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天我常常戴围巾。", "target_word": "戴", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她左手戴着一块小手表。", "target_word": "戴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师手腕上戴过一条红绳。", "target_word": "戴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你出门别忘了戴口罩。", "target_word": "戴", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "戴着", "label": "着体"}, {"form": "戴了", "label": "了体"}, {"form": "戴过", "label": "过体"}], "register": "中性", "sense_fingerprint": "把花、项链、围巾、面具等加在头、面、胸、手等处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '173555db-e539-4abf-a4ea-80fc8e3de36d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88520, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "戴", "is_correct": true, "explanation": "戴（dài）：把花、项链、面具等加在头、面、胸、手等处，是本题正确答案。"}, {"text": "太", "is_correct": false, "explanation": "tài（第四声）与 dài 声母不同（t 与 d），意思是“太”，表示程度过分。"}, {"text": "大", "is_correct": false, "explanation": "dà（第四声）与 dài 韵母不同（没有 -i），意思是“大”。"}, {"text": "呆", "is_correct": false, "explanation": "dāi（第一声）与 dài 声调不同，意思是“呆板、停留”。"}], "explanations": {"戴": "戴（dài）：把花、项链、面具等加在头、面、胸、手等处，是本题正确答案。", "太": "tài（第四声）与 dài 声母不同（t 与 d），意思是“太”，表示程度过分。", "大": "dà（第四声）与 dài 韵母不同（没有 -i），意思是“大”。", "呆": "dāi（第一声）与 dài 声调不同，意思是“呆板、停留”。"}, "sentence_index": null, "correct_answer": "戴"}, "level_3": {"options": [{"text": "戴", "is_correct": true, "explanation": "戴：把花加在胸前，与“他胸前”和“一朵红花”相符。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”用于衣服、鞋袜，不能说“穿着一朵红花”。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，“红花”不能吃。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”的对象是文字，与“一朵红花”的语境不符。"}], "explanations": {"戴": "戴：把花加在胸前，与“他胸前”和“一朵红花”相符。", "穿": "搭配：“穿”用于衣服、鞋袜，不能说“穿着一朵红花”。", "吃": "语义：“吃”的对象是食物，“红花”不能吃。", "写": "语义：“写”的对象是文字，与“一朵红花”的语境不符。"}, "sentence_index": 0, "correct_answer": "戴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她冷了，戴上了毛衣。", "explanation": "这里应该用〈穿〉。“戴”指加在头、面、胸、手等处，毛衣要用“穿”。"}, {"text": "墙上戴着一幅画。", "explanation": "这里应该用〈挂〉。“戴”是把东西加在身体部位上，画应挂在墙上。"}, {"text": "他把钥匙戴在口袋里。", "explanation": "这里应该用〈放〉。“戴”指加在头、面、胸、手等处，口袋里的东西只能放。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8fe8702-03bd-4132-ad10-aea67fcf0340') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88520, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "戴", "is_correct": true, "explanation": "戴（dài）：把东西加在头、面、胸、手等处，是本题正确答案。"}, {"text": "拜", "is_correct": false, "explanation": "bài 与 dài 声母不同（b 与 d），意思是“拜访、拜”。"}, {"text": "盖", "is_correct": false, "explanation": "gài 与 dài 声母不同（g 与 d），意思是“覆盖、盖子”。"}, {"text": "赖", "is_correct": false, "explanation": "lài 与 dài 声母不同（l 与 d），意思是“依靠、耍赖”。"}], "explanations": {"戴": "戴（dài）：把东西加在头、面、胸、手等处，是本题正确答案。", "拜": "bài 与 dài 声母不同（b 与 d），意思是“拜访、拜”。", "盖": "gài 与 dài 声母不同（g 与 d），意思是“覆盖、盖子”。", "赖": "lài 与 dài 声母不同（l 与 d），意思是“依靠、耍赖”。"}, "sentence_index": null, "correct_answer": "戴"}, "level_3": {"options": [{"text": "戴", "is_correct": true, "explanation": "戴：把围巾围在颈上，与“冬天我常常”和“围巾”相符。"}, {"text": "踩", "is_correct": false, "explanation": "语义：“踩”是用脚压，与把围巾戴在身上的语境不符。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的对象是液体，“围巾”不能喝。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能说“唱围巾”。"}], "explanations": {"戴": "戴：把围巾围在颈上，与“冬天我常常”和“围巾”相符。", "踩": "语义：“踩”是用脚压，与把围巾戴在身上的语境不符。", "喝": "语义：“喝”的对象是液体，“围巾”不能喝。", "唱": "搭配：“唱”的对象是歌曲，不能说“唱围巾”。"}, "sentence_index": 6, "correct_answer": "戴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "出门别忘了戴钥匙。", "explanation": "这里应该用〈拿〉。“戴”指加在头、面、胸、手等处，钥匙要拿，不能戴。"}, {"text": "上学别忘了戴书包。", "explanation": "这里应该用〈背〉。“戴”指加在头、面、胸、手等处，书包要背，不能戴。"}, {"text": "他把杯子戴在窗台上。", "explanation": "这里应该用〈摆〉。“戴”指加在头、面、胸、手等处，窗台上的东西只能摆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8fe8702-03bd-4132-ad10-aea67fcf0340') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88520, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她今天戴了一只银项链。", "corrected_sentence": "她今天戴了一条银项链。", "error_description": "错误形式：“一只银项链”中的量词“只”。正确形式：“一条银项链”。“只”不用于项链，项链应用“条”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8fe8702-03bd-4132-ad10-aea67fcf0340') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88520, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他戴了过一副眼镜。", "corrected_sentence": "他戴过一副眼镜。", "error_description": "错误形式：“戴”后同时用了“了”和“过”。正确形式：“戴过一副眼镜”。两个动态助词只保留“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8fe8702-03bd-4132-ad10-aea67fcf0340') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
