INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88536, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手掌或其他东西向上承受。", "primary_collocate": null, "pronunciation": "tuō", "ipa": "tʰwo˥˥", "syllable_count": 1, "sentences": [{"text": "一根柱子托着屋顶。", "target_word": "托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水托着小船慢慢往前走。", "target_word": "托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上有个架子托着花盆。", "target_word": "托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树枝托着一个小鸟窝。", "target_word": "托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桥墩托着那座大桥。", "target_word": "托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个架子托不住那么多书。", "target_word": "托", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用一块木板托住了箱子。", "target_word": "托", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人用千斤顶把车托起一点。", "target_word": "托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海水托着大船，船不会沉。", "target_word": "托", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游泳时，老师用手托着我的背。", "target_word": "托", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "托着", "label": "体标"}, {"form": "托住", "label": "复合"}, {"form": "托举", "label": "复合"}], "register": "中性", "sense_fingerprint": "用手掌或柱子、架子、水等从下面向上承受物体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9239f1d7-ff0d-4c60-a806-0b26eef92068') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88536, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "托", "is_correct": true, "explanation": "托 tuō 为第一声，意思是从下面向上承受。"}, {"text": "唾", "is_correct": false, "explanation": "唾 tuò（第四声）与 tuō（第一声）声调不同，意思是唾液。"}, {"text": "诺", "is_correct": false, "explanation": "诺 nuò 声母为 n，声调也不同，意思是承诺。"}, {"text": "妥", "is_correct": false, "explanation": "妥 tuǒ（第三声）与 tuō（第一声）声调不同，意思是妥当。"}, {"text": "多", "is_correct": false, "explanation": "多 duō 声母为 d 而不是 t，意思是数量大。"}, {"text": "拓", "is_correct": false, "explanation": "拓 tuò（第四声）与 tuō（第一声）声调不同，意思是开拓。"}, {"text": "挪", "is_correct": false, "explanation": "挪 nuó 声母为 n，声调也不同，意思是移动。"}], "explanations": {"托": "托 tuō 为第一声，意思是从下面向上承受。", "唾": "唾 tuò（第四声）与 tuō（第一声）声调不同，意思是唾液。", "诺": "诺 nuò 声母为 n，声调也不同，意思是承诺。", "妥": "妥 tuǒ（第三声）与 tuō（第一声）声调不同，意思是妥当。", "多": "多 duō 声母为 d 而不是 t，意思是数量大。", "拓": "拓 tuò（第四声）与 tuō（第一声）声调不同，意思是开拓。", "挪": "挪 nuó 声母为 n，声调也不同，意思是移动。"}, "sentence_index": null, "correct_answer": "托"}, "level_3": {"options": [{"text": "托", "is_correct": true, "explanation": "正确：“托”表示从下面向上承受，符合“一根柱子托着屋顶”。"}, {"text": "压", "is_correct": false, "explanation": "语义：“压”是从上往下施力，与柱子从下面承受屋顶相反。"}, {"text": "挂", "is_correct": false, "explanation": "搭配：“挂”要借助钩子或墙面，不说挂屋顶。"}, {"text": "吊", "is_correct": false, "explanation": "语义：“吊”是从上方悬着，与从下面承受的意思不符。"}], "explanations": {"托": "正确：“托”表示从下面向上承受，符合“一根柱子托着屋顶”。", "压": "语义：“压”是从上往下施力，与柱子从下面承受屋顶相反。", "挂": "搭配：“挂”要借助钩子或墙面，不说挂屋顶。", "吊": "语义：“吊”是从上方悬着，与从下面承受的意思不符。"}, "sentence_index": 0, "correct_answer": "托"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一盏灯托在天花板上。", "explanation": "这里应该用〈吊〉。托是从下面向上承受，灯悬在天花板上要说吊。"}, {"text": "一根铁丝托着一只鸟笼，挂在树上。", "explanation": "这里应该用〈挂〉。鸟笼悬在树上是从上方吊着，托是从下往上承受，应说挂。"}, {"text": "工人托着一袋水泥走上了二楼。", "explanation": "这里应该用〈扛〉。托多用于手掌能托住的轻物，一袋水泥要扛在肩上，应说扛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0daa5daa-5bbd-4018-b8e4-a2d70022759f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88536, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "托", "is_correct": true, "explanation": "托 tuō 为第一声，意思是从下面向上承受。"}, {"text": "驼", "is_correct": false, "explanation": "驼 tuó（第二声）与 tuō（第一声）声调不同，意思是骆驼。"}, {"text": "夺", "is_correct": false, "explanation": "夺 duó 声母为 d，声调为第二声，意思是抢夺。"}, {"text": "跺", "is_correct": false, "explanation": "跺 duò 声母为 d，声调为第四声，意思是用脚重重踏地。"}, {"text": "陀", "is_correct": false, "explanation": "陀 tuó（第二声）与 tuō（第一声）声调不同，如陀螺。"}, {"text": "椭", "is_correct": false, "explanation": "椭 tuǒ（第三声）与 tuō（第一声）声调不同，如椭圆。"}], "explanations": {"托": "托 tuō 为第一声，意思是从下面向上承受。", "驼": "驼 tuó（第二声）与 tuō（第一声）声调不同，意思是骆驼。", "夺": "夺 duó 声母为 d，声调为第二声，意思是抢夺。", "跺": "跺 duò 声母为 d，声调为第四声，意思是用脚重重踏地。", "陀": "陀 tuó（第二声）与 tuō（第一声）声调不同，如陀螺。", "椭": "椭 tuǒ（第三声）与 tuō（第一声）声调不同，如椭圆。"}, "sentence_index": null, "correct_answer": "托"}, "level_3": {"options": [{"text": "托", "is_correct": true, "explanation": "正确：“托住”表示用手或物体从下面承受，符合“用木板托住了箱子”。"}, {"text": "砸", "is_correct": false, "explanation": "语义：“砸”是猛力撞击，与稳稳承受箱子不符。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是抛出去，与用木板承住箱子的意思相反。"}, {"text": "拆", "is_correct": false, "explanation": "搭配：“拆”是拆开、拆除，不能说拆住箱子。"}], "explanations": {"托": "正确：“托住”表示用手或物体从下面承受，符合“用木板托住了箱子”。", "砸": "语义：“砸”是猛力撞击，与稳稳承受箱子不符。", "扔": "语义：“扔”是抛出去，与用木板承住箱子的意思相反。", "拆": "搭配：“拆”是拆开、拆除，不能说拆住箱子。"}, "sentence_index": 6, "correct_answer": "托"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他托着一担柴走过了小桥。", "explanation": "这里应该用〈挑〉。托是手掌在下面撑着，用扁担担柴要说挑。"}, {"text": "两个人托着一张大床上楼。", "explanation": "这里应该用〈抬〉。大件家具要两人合力，应说抬，托不这么用。"}, {"text": "他把一幅画托在墙上。", "explanation": "这里应该用〈挂〉。托是从下往上承受，画挂在墙上要说挂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0daa5daa-5bbd-4018-b8e4-a2d70022759f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88536, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "湖水托了住那只小船，轻轻晃动。", "corrected_sentence": "湖水托住了那只小船，轻轻晃动。", "error_description": "“住”是结果补语，“了”应放在补语之后，写作“托住了”，不能写成“托了住”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0daa5daa-5bbd-4018-b8e4-a2d70022759f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88536, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "架子托了着一盆花。", "corrected_sentence": "架子托着一盆花。", "error_description": "“了”不能插在“托”和“着”之间。“着”是动词的状态标记，应直接跟在“托”后，写作“托着”，“托了着”有误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0daa5daa-5bbd-4018-b8e4-a2d70022759f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88555, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "入学", "is_correct": true, "explanation": "「入学」指进入学校开始学习，与「毕业」相对，是反义词。"}, {"text": "唱歌", "is_correct": false, "explanation": "「唱歌」指用声音演唱，与「毕业」没有反义关系。"}, {"text": "跑步", "is_correct": false, "explanation": "「跑步」指快速跑动，与「毕业」没有反义关系。"}, {"text": "写信", "is_correct": false, "explanation": "「写信」指用文字写书信，与「毕业」没有反义关系。"}], "correct_answer": "入学", "explanations": {"入学": "「入学」指进入学校开始学习，与「毕业」相对，是反义词。", "唱歌": "「唱歌」指用声音演唱，与「毕业」没有反义关系。", "跑步": "「跑步」指快速跑动，与「毕业」没有反义关系。", "写信": "「写信」指用文字写书信，与「毕业」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '821120fb-29b6-4e15-b4de-5bac71794620') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88555, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "入学", "is_correct": true, "explanation": "「入学」指进入学校开始学习，与「毕业」相对，是反义词。"}, {"text": "睡觉", "is_correct": false, "explanation": "「睡觉」指闭眼休息，与「毕业」没有反义关系。"}, {"text": "洗澡", "is_correct": false, "explanation": "「洗澡」指清洗身体，与「毕业」没有反义关系。"}, {"text": "下棋", "is_correct": false, "explanation": "「下棋」指对弈棋类游戏，与「毕业」没有反义关系。"}], "correct_answer": "入学", "explanations": {"入学": "「入学」指进入学校开始学习，与「毕业」相对，是反义词。", "睡觉": "「睡觉」指闭眼休息，与「毕业」没有反义关系。", "洗澡": "「洗澡」指清洗身体，与「毕业」没有反义关系。", "下棋": "「下棋」指对弈棋类游戏，与「毕业」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '821120fb-29b6-4e15-b4de-5bac71794620') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88555, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "毕业是学完了一个学校的课,可以离开了。", "primary_collocate": null, "pronunciation": "bì yè", "ipa": "pi˥˩ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "弟弟中学毕业了。", "target_word": "毕业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想早点儿毕业，找一份工作。", "target_word": "毕业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你什么时候毕业？", "target_word": "毕业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹今年小学毕业，要去中学了。", "target_word": "毕业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业的时候，同学们都哭了。", "target_word": "毕业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他毕业三年了，现在在银行工作。", "target_word": "毕业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她们是同一年毕业的。", "target_word": "毕业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我还有一年才毕业。", "target_word": "毕业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学完所有的课，我就可以毕业了。", "target_word": "毕业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业以后，我们还常常见面。", "target_word": "毕业", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "毕业了", "label": "体标"}, {"form": "毕业生", "label": "复合"}, {"form": "毕业证", "label": "复合"}], "register": "中性", "sense_fingerprint": "学完一个学校的课程，可以离开学校", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93b857e6-3c49-4de3-8fae-c67dc4ed796b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88555, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "毕业", "is_correct": true, "explanation": "「毕业」指学完中学课程、可以离开学校，与句中的「弟弟」「中学」搭配，正确。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：「结婚」指成立婚姻关系，弟弟是中学生，不能结婚。"}, {"text": "退休", "is_correct": false, "explanation": "语义：「退休」指离开工作岗位，与中学生的身份不符。"}, {"text": "上班", "is_correct": false, "explanation": "搭配：「上班」说到工作单位，学生应说「上学」，不能说「中学上班」。"}], "explanations": {"毕业": "「毕业」指学完中学课程、可以离开学校，与句中的「弟弟」「中学」搭配，正确。", "结婚": "语义：「结婚」指成立婚姻关系，弟弟是中学生，不能结婚。", "退休": "语义：「退休」指离开工作岗位，与中学生的身份不符。", "上班": "搭配：「上班」说到工作单位，学生应说「上学」，不能说「中学上班」。"}, "sentence_index": 0, "correct_answer": "毕业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们参加的夏令营学了两周，今天毕业了。", "explanation": "这里应该用〈结业〉。毕业用于学完学校的规定课程，夏令营结束要用结业。"}, {"text": "他因为家里穷，初二就毕业了。", "explanation": "这里应该用〈辍学〉。毕业表示学完规定课程，中途不读了要用辍学。"}, {"text": "他在木匠铺学了三年，已经毕业了。", "explanation": "这里应该用〈出师〉。毕业用于学校的学业，学徒学成离开师傅要用出师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '821120fb-29b6-4e15-b4de-5bac71794620') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88555, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "毕业", "is_correct": true, "explanation": "「毕业」指学完规定课程，句中「她们」「同一年」「……的」都与之相合，正确。"}, {"text": "出版", "is_correct": false, "explanation": "语义：「出版」指书籍、报刊等印行，不能用于人。"}, {"text": "竣工", "is_correct": false, "explanation": "语义：「竣工」指工程建成，不能用于人。"}, {"text": "送", "is_correct": false, "explanation": "配价：「送」是及物动词，缺少宾语，「她们是同一年送的」说不完整。"}], "explanations": {"毕业": "「毕业」指学完规定课程，句中「她们」「同一年」「……的」都与之相合，正确。", "出版": "语义：「出版」指书籍、报刊等印行，不能用于人。", "竣工": "语义：「竣工」指工程建成，不能用于人。", "送": "配价：「送」是及物动词，缺少宾语，「她们是同一年送的」说不完整。"}, "sentence_index": 6, "correct_answer": "毕业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个学生因为转学，中途毕业了。", "explanation": "这里应该用〈离校〉。毕业表示学完全部课程，中途因转学离开学校要用离校。"}, {"text": "我们的暑期英语班，上周毕业了。", "explanation": "这里应该用〈结束〉。毕业只用于学完学校的规定课程，英语班结束只说结束。"}, {"text": "他因为身体原因，毕业在家养病。", "explanation": "这里应该用〈休学〉。毕业表示学完规定课程，因病暂时停学要用休学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '821120fb-29b6-4e15-b4de-5bac71794620') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88555, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我表弟今年把小学毕业了，下个月要去中学读书。", "corrected_sentence": "我表弟今年小学毕业了，下个月要去中学读书。", "error_description": "错误：“毕业”是不及物动词，不能用“把”字句，“把”后不能接“小学”作宾语。正确：应说“小学毕业了”，不加“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '821120fb-29b6-4e15-b4de-5bac71794620') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88555, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我妹妹还没毕业了，还在上初三。", "corrected_sentence": "我妹妹还没毕业，还在上初三。", "error_description": "「还没」表示尚未完成，句末不加「了」。错误形式是「还没毕业了」，应改为「还没毕业」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '821120fb-29b6-4e15-b4de-5bac71794620') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
