INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88557, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "宁可是选一个比较好的，不选更糟的。", "primary_collocate": null, "pronunciation": "nìng kě", "ipa": "niŋ⁵¹ kʰɤ²¹⁴", "syllable_count": 2, "sentences": [{"text": "我宁可走路，也不坐那辆很挤的车。", "target_word": "宁可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他宁可少睡觉，也要把工作做完。", "target_word": "宁可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宁可早点儿出门，也不要迟到。", "target_word": "宁可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹宁可饿着，也不吃不新鲜的饭。", "target_word": "宁可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我宁可多花点钱，也要买好东西。", "target_word": "宁可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王宁可自己累一点，也不麻烦别人。", "target_word": "宁可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她宁可不去旅行，也不想跟不熟的人一起。", "target_word": "宁可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我宁可等一个小时，也不想坐下一班车。", "target_word": "宁可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他宁可饿肚子，也不愿意吃那家的菜。", "target_word": "宁可", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宁可慢一点，也不要做错。", "target_word": "宁可", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "宁可：在两种坏结果中选较好的一个，常与“也不”连用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18932129-736e-4e30-ab71-e2b8f73da70b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88557, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宁可", "is_correct": true, "explanation": "正确：「宁可」表示在两种不好的选择中取舍，后面用「也不」与之配合，与句意相符。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：「竟然」表示出乎意料，不能表示主动权衡后的选择，与「也不坐那辆很挤的车」的取舍不合。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：「非常」修饰形容词或心理动词，不能修饰「走路」这类动作。"}, {"text": "果然", "is_correct": false, "explanation": "语义：「果然」表示与事先预料相符，句中没有这样的前提，也无法引出被放弃的一方。"}], "explanations": {"宁可": "正确：「宁可」表示在两种不好的选择中取舍，后面用「也不」与之配合，与句意相符。", "竟然": "语义：「竟然」表示出乎意料，不能表示主动权衡后的选择，与「也不坐那辆很挤的车」的取舍不合。", "非常": "搭配：「非常」修饰形容词或心理动词，不能修饰「走路」这类动作。", "果然": "语义：「果然」表示与事先预料相符，句中没有这样的前提，也无法引出被放弃的一方。"}, "sentence_index": 0, "correct_answer": "宁可"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他本来很累，听了这话宁可精神了。", "explanation": "这里应该用〈反而〉。宁可表示两种情况之间的取舍，不能表示与预期相反的结果；听了这话后精神起来是出乎意料的变化，要用〈反而〉。"}, {"text": "这个房间宁可很大。", "explanation": "这里应该去掉〈宁可〉，直接说「这个房间很大」。宁可只用于取舍，不能用来描述大小。"}, {"text": "经过多次尝试，他宁可成功了。", "explanation": "这里应该用〈终于〉。宁可表示取舍，后面要有被放弃的一方，不能表示经过努力后最终实现；表示结果要用〈终于〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13588d17-24d0-4455-8450-c63fe2e82d91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
